typedef struct JsArrayRuntimeItemsEntry {
    Item* items;
    Array* owner;
} JsArrayRuntimeItemsEntry;

// Hot-reload batches retain live arrays between tests; pointer lookup stays
// constant-time in the owning context so later array allocations never rescan
// retained buffers or contend with another realm.
#define g_js_array_runtime_items (js_runtime_state.array_runtime_items)

static uint64_t js_array_runtime_items_hash(const void* item, uint64_t seed0, uint64_t seed1) {
    const JsArrayRuntimeItemsEntry* entry = (const JsArrayRuntimeItemsEntry*)item;
    return hashmap_sip(&entry->items, sizeof(entry->items), seed0, seed1);
}

static int js_array_runtime_items_compare(const void* left, const void* right, void* udata) {
    (void)udata;
    const JsArrayRuntimeItemsEntry* a = (const JsArrayRuntimeItemsEntry*)left;
    const JsArrayRuntimeItemsEntry* b = (const JsArrayRuntimeItemsEntry*)right;
    uintptr_t a_key = (uintptr_t)a->items;
    uintptr_t b_key = (uintptr_t)b->items;
    return (a_key > b_key) - (a_key < b_key);
}

static void js_array_runtime_items_free_map_if_empty(void) {
    if (g_js_array_runtime_items && hashmap_count(g_js_array_runtime_items) == 0) {
        hashmap_free(g_js_array_runtime_items);
        g_js_array_runtime_items = NULL;
    }
}

static bool js_array_runtime_items_forget(Item* items, Array** owner_out) {
    if (owner_out) *owner_out = NULL;
    // Lambda heap finalization visits every Array, including arrays created
    // outside a JS realm.  The registry is context-owned, so it is absent
    // when a pure-Lambda context tears down and must not be dereferenced.
    if (!js_active_runtime_state || !g_js_array_runtime_items || !items) return false;
    JsArrayRuntimeItemsEntry probe = {items, NULL};
    const JsArrayRuntimeItemsEntry* found =
        (const JsArrayRuntimeItemsEntry*)hashmap_get(g_js_array_runtime_items, &probe);
    if (!found) return false;
    if (owner_out) *owner_out = found->owner;
    hashmap_delete(g_js_array_runtime_items, &probe);
    js_array_runtime_items_free_map_if_empty();
    return true;
}

static void js_array_runtime_items_neuter_owner(Array* owner, Item* items) {
    if (!owner || owner->items != items) return;
    // Runtime item buffers are mem_alloc-owned; stale Array slots must not be traced after release.
    owner->items = NULL;
    owner->capacity = 0;
}

static void js_array_runtime_items_register(Array* owner, Item* items) {
    if (!items) return;
    if (!g_js_array_runtime_items) {
        g_js_array_runtime_items = hashmap_new(sizeof(JsArrayRuntimeItemsEntry), 32, 0, 0,
            js_array_runtime_items_hash, js_array_runtime_items_compare, NULL, NULL);
        if (!g_js_array_runtime_items) return;
    }
    JsArrayRuntimeItemsEntry entry = {items, owner};
    const JsArrayRuntimeItemsEntry* found =
        (const JsArrayRuntimeItemsEntry*)hashmap_get(g_js_array_runtime_items, &entry);
    if (found) hashmap_delete(g_js_array_runtime_items, &entry);
    hashmap_set(g_js_array_runtime_items, &entry);
}

extern "C" bool js_array_runtime_items_release(Item* items) {
    Array* owner = NULL;
    if (!js_array_runtime_items_forget(items, &owner)) return false;
    js_array_runtime_items_neuter_owner(owner, items);
    mem_free(items);
    return true;
}

static void js_array_runtime_items_cleanup_map(HashMap* map) {
    if (!map) return;
    size_t iter = 0;
    void* raw = NULL;
    while (hashmap_iter(map, &iter, &raw)) {
        JsArrayRuntimeItemsEntry* entry = (JsArrayRuntimeItemsEntry*)raw;
        js_array_runtime_items_neuter_owner(entry->owner, entry->items);
        if (entry->items) mem_free(entry->items);
    }
    hashmap_free(map);
}

extern "C" void js_array_runtime_items_cleanup_all(void) {
    if (!js_active_runtime_state) return;
    js_array_runtime_items_cleanup_map(g_js_array_runtime_items);
    g_js_array_runtime_items = NULL;
}

static void js_array_install_runtime_items(Array* arr, Item* items, int64_t capacity) {
    if (!arr) return;
    Item* old_items = arr->items;
    int64_t old_capacity = arr->capacity;
    if (old_items && items && capacity >= arr->extra) {
        list_relocate_owned_tail((List*)arr, old_items, old_capacity, items, capacity);
    }
    if (old_items) js_array_runtime_items_release(old_items);
    arr->items = items;
    arr->capacity = capacity;
    js_array_runtime_items_register(arr, items);
}

static inline int64_t js_array_dense_capacity(const Array* arr) {
    return container_dense_capacity(arr);
}

// J0.1: array-store counters, dumped at exit. These validated the J1 diagnosis
// (scanned-slots ~= capacity x stores) in-tree and confirm the collapse to zero
// scans afterward.
//
// Compile-time gated, not env-gated: the enable check sits on the hot array
// store path, and an unset env var never latches, so the old getenv() probe
// took the libc environ lock on every store (__findenv_locked was ~5% of busy
// samples on the LJS navier_stokes profile). Flip to 1 (here or with -D) in a
// debug build when the counters are needed.
#ifndef LAMBDA_JS_ARRAY_STATS
#define LAMBDA_JS_ARRAY_STATS 0
#endif
#ifdef NDEBUG
// release carries no instrumentation: these increments are unsynchronized and
// sit inside the store fast path.
#undef LAMBDA_JS_ARRAY_STATS
#define LAMBDA_JS_ARRAY_STATS 0
#endif

#if LAMBDA_JS_ARRAY_STATS
static struct {
    uint64_t dense_required_calls;   // js_array_dense_required invocations
    uint64_t dense_required_scans;   // of those, ones that ran a backward scan
    uint64_t dense_required_slots;   // cumulative slots walked by scans
    uint64_t store_fast_bypass;      // js_array_store_owned direct-array_set hits
    uint64_t store_scan_path;        // js_array_store_owned grow-check stores
} g_js_array_stats;

static bool g_js_array_stats_reported = false;

static void js_array_stats_report(void) {
    if (g_js_array_stats_reported) return;
    g_js_array_stats_reported = true;
    const auto& s = g_js_array_stats;
    log_info("js-array-stats: dense_required=%llu scans=%llu scanned_slots=%llu "
        "(%.1f slots/scan) | store_fast=%llu store_growcheck=%llu",
        (unsigned long long)s.dense_required_calls,
        (unsigned long long)s.dense_required_scans,
        (unsigned long long)s.dense_required_slots,
        s.dense_required_scans ? (double)s.dense_required_slots / (double)s.dense_required_scans : 0.0,
        (unsigned long long)s.store_fast_bypass,
        (unsigned long long)s.store_scan_path);
}

static inline void js_array_stats_touch(void) {
    static bool registered = false;
    if (!registered) {
        // fallback for hosts that never reach lambda_main_finish() (test
        // binaries); there nothing has closed the log yet at exit time.
        atexit(js_array_stats_report);
        registered = true;
    }
}
// every counted path arms the dump: most stores are counted without ever
// reaching js_array_dense_required, so arming from there alone lost the whole
// report on runs whose stores all took the fast bypass.
#define JS_ARRAY_STATS_INC(counter) (js_array_stats_touch(), g_js_array_stats.counter++)
#else
#define JS_ARRAY_STATS_INC(counter) ((void)0)
#endif

// lambda_main_finish() calls this before log_finish() closes log.txt — the
// atexit dump runs after that point, where log_info output is discarded.
// Compiled either way so the call site needs no #if.
extern "C" void js_array_stats_dump(void) {
#if LAMBDA_JS_ARRAY_STATS
    js_array_stats_report();
#endif
}

// J1: the growth-sizing value for js_array_store_owned (its only caller).
//
// The former sparse branch ran an O(dense_capacity) backward hole scan on
// every store into a sparse array — the hashmap 2609x cliff (measured ~48k
// slots/scan). That scan is unnecessary: expand_list copies the whole physical
// buffer regardless of this value, and js_array_store_owned uses the result
// only in its grow-loop condition, always clamped up to `index + 1`. Every
// already-stored slot sits at an index < dense_capacity and was given its tail
// headroom when it was written (capacity only grows), so the write target is
// the only requirement the loop must newly satisfy. Returning 0 for the sparse
// case lets the index+1 clamp size growth — O(1), and it can never balloon on
// a spec length because it never reads arr->length as a physical bound.
static int64_t js_array_dense_required(const Array* arr) {
    JS_ARRAY_STATS_INC(dense_required_calls);
    int64_t dense_capacity = js_array_dense_capacity(arr);
    if (!arr || !arr->items || dense_capacity <= 0) return 0;
    if (arr->length <= dense_capacity) return arr->length;
    return 0;
}

static bool js_array_value_is_numeric(Item value) {
    TypeId value_type = get_type_id(value);
    return value_type == LMD_TYPE_INT || value_type == LMD_TYPE_INT64 ||
        value_type == LMD_TYPE_FLOAT || value_type == LMD_TYPE_FLOAT64 ||
        value_type == LMD_TYPE_UINT64;
}

extern "C" bool js_is_ordinary_numeric_array(Item value) {
    if (get_type_id(value) != LMD_TYPE_ARRAY_NUM || !value.array_num) return false;
    ArrayNum* arr = value.array_num;
    return !arr->is_content && !arr->is_ndim && !arr->is_view &&
        container_js_elements_kind((Container*)arr) == JS_ELEMENTS_PACKED_NUMERIC &&
        (arr->get_elem_type() == ELEM_INT ||
         arr->get_elem_type() == ELEM_INT64 ||
         arr->get_elem_type() == ELEM_FLOAT64);
}

extern "C" bool js_is_js_array(Item value) {
    TypeId type = get_type_id(value);
    return type == LMD_TYPE_ARRAY || js_is_ordinary_numeric_array(value);
}

static bool js_array_numeric_grow(Item array_item, int64_t required_length) {
    if (!js_is_ordinary_numeric_array(array_item) || required_length < 0) return false;
    RootFrame roots(1);
    Rooted<Item> array_root(roots, array_item);
    Item companion = ItemNull;
    ArrayNum* initial = array_root.get().array_num;
    if (initial->has_js_props && initial->capacity > 0) {
        companion = ((Item*)initial->data)[initial->capacity - 1];
    }
    Rooted<Item> companion_root(roots, companion);
    ArrayNum* arr = array_root.get().array_num;
    if (required_length <= container_dense_capacity((Array*)arr)) return true;
    int64_t old_capacity = arr->capacity;
    int64_t old_extra = arr->extra;
    int elem_size = ELEM_TYPE_SIZE[arr->get_elem_type() >> 4];
    if (old_capacity < 0 || old_extra < 0 || elem_size <= 0 ||
            old_capacity > INT64_MAX / elem_size) {
        return false;
    }
    if (old_extra > INT64_MAX - 4 ||
            required_length > INT64_MAX - old_extra - 4) return false;
    int64_t minimum_capacity = required_length + old_extra + 4;
    int64_t new_capacity = old_capacity > INT64_MAX / 2
        ? INT64_MAX : old_capacity * 2;
    if (new_capacity < minimum_capacity) new_capacity = minimum_capacity;
    if (new_capacity < required_length ||
            new_capacity > INT64_MAX / elem_size ||
            (uint64_t)new_capacity > (uint64_t)SIZE_MAX / (size_t)elem_size) {
        return false;
    }
    size_t bytes = (size_t)new_capacity * (size_t)elem_size;
    void* new_data = heap_data_alloc(bytes);
    arr = array_root.get().array_num;
    if (!new_data) return false;
    if (arr->data && old_capacity > 0) {
        memcpy(new_data, arr->data, (size_t)old_capacity * (size_t)elem_size);
    }
    if (arr->has_js_props && companion_root.get().item != ItemNull.item) {
        ((Item*)new_data)[new_capacity - 1] = companion_root.get();
    }
    // This is a raw numeric buffer, so its owner changes only after the copy;
    // no user callback or safepoint may observe the intermediate pointer.
    heap_no_gc_scope_begin();
    arr->data = new_data;
    arr->capacity = new_capacity;
    heap_no_gc_scope_end();
    return true;
}

static bool js_array_numeric_store(Item array_item, int64_t index, Item value) {
    if (!js_is_ordinary_numeric_array(array_item) || index < 0 ||
            index >= INT64_MAX || !js_array_value_is_numeric(value)) return false;
    RootFrame roots(2);
    Rooted<Item> array_root(roots, array_item);
    Rooted<Item> value_root(roots, value);
    ArrayNum* arr = array_root.get().array_num;
    if (index > arr->length) return false;
    if (!js_array_numeric_grow(array_root.get(), index + 1)) return false;
    arr = array_root.get().array_num;
    value = value_root.get();
    if (arr->get_elem_type() == ELEM_FLOAT64) {
        array_num_set_double_value(arr, index, js_get_number(value));
    } else {
        array_num_set_int64_value(arr, index, (int64_t)js_get_number(value));
    }
    if (index >= arr->length) arr->length = index + 1;
    return true;
}

// P5 promotion is identity-preserving: only the managed object header and
// payload contract change, so every rooted Item keeps the same pointer.
static bool js_array_promote_numeric_to_tagged(Item array_item) {
    if (!js_is_ordinary_numeric_array(array_item)) return false;
    RootFrame roots(3);
    Rooted<Item> array_root(roots, array_item);
    ArrayNum* numeric = array_root.get().array_num;
    Item companion = js_array_has_props((Array*)numeric)
        ? (Item){.map = js_array_props((Array*)numeric)} : ItemNull;
    Rooted<Item> companion_root(roots, companion);
    int64_t length = numeric->length;
    int64_t old_dense_capacity = container_dense_capacity((Array*)numeric);
    bool has_props = companion.item != ItemNull.item;
    if (length < 0 || old_dense_capacity < length ||
            length > (INT64_MAX - old_dense_capacity - (has_props ? 1 : 0) - 4) / 2) {
        return false;
    }
    // Reserve enough tail for every possible boxed scalar plus the companion;
    // array_set consumes only the tail slots it actually needs.
    int64_t new_capacity = old_dense_capacity + length + (has_props ? 1 : 0) + 4;
    size_t bytes = (size_t)new_capacity * sizeof(Item);
    Item* new_items = (Item*)heap_data_alloc(bytes);
    numeric = array_root.get().array_num;
    if (!new_items) return false;

    // save the numeric header before installing the tagged items pointer: both
    // representations reuse offset 8, so writing tagged->items would otherwise
    // erase the only pointer to the source scalar buffer before promotion reads it.
    ArrayNum numeric_source = *numeric;
    heap_no_gc_scope_begin();
    Array* tagged = (Array*)numeric;
    tagged->items = new_items;
    tagged->capacity = new_capacity;
    tagged->extra = has_props ? 1 : 0;
    tagged->has_js_props = has_props ? 1 : 0;
    for (int64_t i = 0; i < length; i++) {
        // array_num_read_item materializes the numeric lane; array_set then
        // adopts any out-of-band scalar into the new container-owned tail.
        Item numeric_value = array_num_read_item(&numeric_source, i);
        array_set(tagged, i, numeric_value);
    }
    if (has_props) tagged->items[new_capacity - 1] = companion_root.get();
    heap_retag_container((Container*)tagged, LMD_TYPE_ARRAY_NUM, LMD_TYPE_ARRAY);
    container_set_js_elements_kind((Container*)tagged,
                                   JS_ELEMENTS_PACKED_TAGGED);
    heap_no_gc_scope_end();
    return true;
}

extern "C" bool js_array_promote_numeric(Item array_item) {
    return js_array_promote_numeric_to_tagged(array_item);
}

static void js_array_store_owned(Array* arr, int64_t index, Item value) {
    if (!arr || index < 0) return;
    if (arr->is_content) {
        container_set_js_elements_kind((Container*)arr, JS_ELEMENTS_NONE);
    } else {
        JsElementsKind kind = container_js_elements_kind((Container*)arr);
        if (kind == JS_ELEMENTS_NONE) {
            container_set_js_elements_kind((Container*)arr,
                                           JS_ELEMENTS_PACKED_TAGGED);
        } else if (value.item == JS_DELETED_SENTINEL_VAL) {
            container_set_js_elements_kind((Container*)arr,
                kind == JS_ELEMENTS_SPARSE_TAGGED ? JS_ELEMENTS_SPARSE_TAGGED
                    : JS_ELEMENTS_HOLEY_TAGGED);
        } else if (kind == JS_ELEMENTS_PACKED_NUMERIC) {
            if (!js_array_value_is_numeric(value)) {
                // Undefined is a present value, so it cannot remain in the
                // no-hole numeric representation (D8.4.3).
                container_set_js_elements_kind((Container*)arr,
                                               JS_ELEMENTS_PACKED_TAGGED);
            }
        }
    }
    if (arr->items && arr->extra == 0 && index < js_array_dense_capacity(arr)) {
        // Only arrays without a scalar tail can bypass the required scan: wide
        // scalar writes consume capacity from that tail and must retain it.
        JS_ARRAY_STATS_INC(store_fast_bypass);
        array_set(arr, index, value);
        return;
    }
    JS_ARRAY_STATS_INC(store_scan_path);
    int64_t dense_required = js_array_dense_required(arr);
    if (dense_required < index + 1) dense_required = index + 1;
    while (!arr->items || dense_required + arr->extra + 2 > arr->capacity) {
        int64_t old_capacity = arr->capacity;
        RootFrame roots(1);
        Rooted<Item> rooted_value(roots, value);
        expand_list((List*)arr);
        value = rooted_value.get();
        if (arr->capacity <= old_capacity) return;
    }
    // Imported wide scalars may point into another container's tail. Re-home
    // them through the shared owned store before the source can move or die.
    array_set(arr, index, value);
}

