static bool js_function_has_vm_stack_source(JsFunction* fn) {
    return fn && fn->vm_stack_filename && fn->vm_stack_source;
}

static bool js_function_push_vm_stack_source(JsFunction* fn) {
    if (!js_function_has_vm_stack_source(fn)) return false;
    return js_eval_source_push_compact((Item){.item = s2it(fn->vm_stack_filename)},
                                       (Item){.item = s2it(fn->vm_stack_source)},
                                       fn->vm_stack_line_offset,
                                       fn->vm_stack_column_offset) != 0;
}

#define js_global_var_module_binding_keys (js_runtime_state.global_var_module_bindings.keys)
#define js_global_var_module_binding_indices (js_runtime_state.global_var_module_bindings.indices)
#define js_global_var_module_binding_state_ids (js_runtime_state.global_var_module_bindings.module_state_ids)
#define js_global_var_module_binding_count (js_runtime_state.global_var_module_bindings.count)
#define js_global_var_module_binding_epoch (js_runtime_state.global_var_module_bindings.epoch)
#define js_global_var_module_binding_global (js_runtime_state.global_var_module_bindings.global)

extern "C" Item js_vm_swap_global_this(Item next_global);
extern "C" uint64_t js_get_heap_epoch(void);
static Item js_262_eval_script(Item code);

static bool js_global_var_binding_key_same(Item a, Item b) {
    if (a.item == b.item) return true;
    if (get_type_id(a) != LMD_TYPE_STRING || get_type_id(b) != LMD_TYPE_STRING) return false;
    String* as = it2s(a);
    String* bs = it2s(b);
    return as && bs && as->len == bs->len &&
        memcmp(as->chars, bs->chars, (size_t)as->len) == 0;
}

static void js_global_var_binding_refresh(void) {
    Item global = js_get_global_this();
    uint64_t epoch = js_get_heap_epoch();
    if (js_global_var_module_binding_epoch == epoch &&
        js_global_var_module_binding_global.item == global.item) {
        return;
    }
    js_global_var_module_binding_epoch = epoch;
    js_global_var_module_binding_global = global;
    js_global_var_module_binding_count = 0;
}

extern "C" void js_register_global_var_module_binding(Item key, int64_t index) {
    js_global_var_binding_refresh();
    if (get_type_id(key) != LMD_TYPE_STRING || index < 0) return;
    uint32_t module_state_id = js_get_active_module_state_id();
    for (int i = 0; i < js_global_var_module_binding_count; i++) {
        if (js_global_var_binding_key_same(js_global_var_module_binding_keys[i], key)) {
            js_global_var_module_binding_indices[i] = (int)index;
            js_global_var_module_binding_state_ids[i] = module_state_id;
            return;
        }
    }
    if (js_global_var_module_binding_count >= JS_GLOBAL_VAR_MODULE_BINDING_CAP) return;
    js_global_var_module_binding_keys[js_global_var_module_binding_count] = key;
    js_global_var_module_binding_indices[js_global_var_module_binding_count] = (int)index;
    js_global_var_module_binding_state_ids[js_global_var_module_binding_count] = module_state_id;
    js_global_var_module_binding_count++;
}

extern "C" void js_register_global_var_module_bindings_bulk(const Item* keys,
        const int* indices, int count) {
    js_global_var_binding_refresh();
    if (!keys || !indices || count <= 0) return;
    uint32_t module_state_id = js_get_active_module_state_id();
    for (int i = 0; i < count; i++) {
        Item key = keys[i];
        int index = indices[i];
        if (get_type_id(key) != LMD_TYPE_STRING || index < 0) continue;
        bool updated = false;
        for (int j = 0; j < js_global_var_module_binding_count; j++) {
            if (js_global_var_binding_key_same(js_global_var_module_binding_keys[j], key)) {
                js_global_var_module_binding_indices[j] = index;
                js_global_var_module_binding_state_ids[j] = module_state_id;
                updated = true;
                break;
            }
        }
        if (updated) continue;
        if (js_global_var_module_binding_count >= JS_GLOBAL_VAR_MODULE_BINDING_CAP) return;
        js_global_var_module_binding_keys[js_global_var_module_binding_count] = key;
        js_global_var_module_binding_indices[js_global_var_module_binding_count] = index;
        js_global_var_module_binding_state_ids[js_global_var_module_binding_count] = module_state_id;
        js_global_var_module_binding_count++;
    }
}

static void js_sync_global_var_module_binding(Item object, Item key, Item value) {
    js_global_var_binding_refresh();
    if (object.item != js_global_var_module_binding_global.item ||
        get_type_id(key) != LMD_TYPE_STRING) {
        return;
    }
    for (int i = 0; i < js_global_var_module_binding_count; i++) {
        if (js_global_var_binding_key_same(js_global_var_module_binding_keys[i], key)) {
            // Global `var` bindings are backed by the global object. When code
            // writes through `this.x`/`globalThis.x`, keep the optimized module
            // slot coherent without making every identifier read a property get.
            // The writer may be an indirect-eval function in another slab, so
            // update the binding's owner rather than its currently active slab.
            uint32_t owner_state_id = js_global_var_module_binding_state_ids[i];
            uint32_t previous_state_id = js_get_active_module_state_id();
            bool switched_state = owner_state_id != UINT32_MAX &&
                owner_state_id != previous_state_id;
            if (switched_state && !js_set_active_module_state_id(owner_state_id)) return;
            js_set_module_var(js_global_var_module_binding_indices[i], value);
            if (switched_state && previous_state_id != UINT32_MAX) {
                js_set_active_module_state_id(previous_state_id);
            }
            return;
        }
    }
}

static bool js_reflect_target_is_object(Item target) {
    TypeId type = get_type_id(target);
    return type == LMD_TYPE_MAP || type == LMD_TYPE_ARRAY ||
           js_is_ordinary_numeric_array(target) ||
           type == LMD_TYPE_FUNC || type == LMD_TYPE_ELEMENT;
}

static int js_class_private_index(Item class_item) {
    if (get_type_id(class_item) != LMD_TYPE_MAP) return -1;
    bool found = false;
    Item index_item = js_map_shape_lookup_ext(class_item.map, JS_PRIVATE_CLASS_INDEX_KEY,
        JS_PRIVATE_CLASS_INDEX_KEY_LEN, &found);
    if (!found || get_type_id(index_item) != LMD_TYPE_INT) return -1;
    return (int)it2i(index_item);
}

extern "C" void js_set_private_class_index(Item class_item, int index) {
    if (get_type_id(class_item) != LMD_TYPE_MAP || index < 0) return;
    Item key = (Item){.item = s2it(heap_create_name(JS_PRIVATE_CLASS_INDEX_KEY, JS_PRIVATE_CLASS_INDEX_KEY_LEN))};
    Item val = (Item){.item = i2it(index)};
    js_set_key_default(class_item, key, val);
}

static bool js_private_source_name(Item source_name) {
    if (get_type_id(source_name) != LMD_TYPE_STRING) return false;
    String* source = it2s(source_name);
    return source && source->len > 1 && source->chars[0] == '#';
}

static Item js_private_environment_for_class(Item class_item, bool create) {
    if (get_type_id(class_item) != LMD_TYPE_MAP) return ItemNull;
    Item environment_key = (Item){.item = s2it(heap_create_name("__pk_env__", 10))};
    Item environment = js_get_key_default(class_item, environment_key);
    if (get_type_id(environment) == LMD_TYPE_MAP) return environment;
    if (!create) return ItemNull;

    RootFrame roots(3);
    Rooted<Item> class_root(roots, class_item);
    Rooted<Item> key_root(roots, environment_key);
    Rooted<Item> environment_root(roots, js_new_object());
    if (!roots.valid()) return ItemNull;
    // The environment is class-owned so each evaluation receives fresh private
    // records even when the compiled class entry and its source spellings repeat.
    JS_ASSIGN_OR_RETURN(set_result, js_set_key_default(class_root.get(), key_root.get(), environment_root.get()));
    js_mark_non_enumerable(class_root.get(), key_root.get());
    return environment_root.get();
}

static bool js_private_key_item_is_valid(Item key) {
    if (get_type_id(key) != LMD_TYPE_STRING) return false;
    String* key_string = it2s(key);
    return key_string && property_key_requires_identity(key_string) &&
        property_key_kind(key_string) == NAME_KEY_PRIVATE;
}

static Item js_private_key_for_class_environment(Item environment_item,
        NameRef source_name) {
    if (get_type_id(environment_item) != LMD_TYPE_MAP || !source_name) return ItemNull;

    bool found = false;
    Item cached_key = js_map_shape_lookup(environment_item.map, source_name->chars,
        (int)source_name->len, &found);
    if (found && js_private_key_item_is_valid(cached_key)) return cached_key;

    if (!context || !context->name_pool) return ItemNull;
    NameRef private_key = name_pool_create_unique_private(context->name_pool,
        {source_name->chars, source_name->len});
    if (!private_key) return ItemNull;
    Item private_key_item = (Item){.item = s2it(private_key)};

    // class metadata resolves thousands of private names in one batch.  The
    // environment is engine-owned and the source key is already canonical, so
    // append directly after the own-cache miss instead of rebuilding the full
    // JS property path for every declaration.
    if (js_input) {
        map_put(environment_item.map, source_name, private_key_item, js_input);
        return private_key_item;
    }
    return js_set_key_default(environment_item, (Item){.item = s2it(source_name)},
        private_key_item);
}

extern "C" Item js_private_key_for_class(Item class_item, Item source_name) {
    if (!js_private_source_name(source_name) || !context || !context->name_pool) {
        return js_throw_type_error("Invalid private name binding");
    }
    RootFrame roots(3);
    Rooted<Item> class_root(roots, class_item);
    Rooted<Item> source_root(roots, source_name);
    Rooted<Item> environment_root(roots,
        js_private_environment_for_class(class_root.get(), true));
    if (!roots.valid() || get_type_id(environment_root.get()) != LMD_TYPE_MAP) return ItemNull;
    String* source = it2s(source_root.get());
    NameRef binding_name = name_pool_create_len(context->name_pool,
        source->chars, source->len);
    if (!binding_name) return ItemNull;
    // private source literals are distinct heap strings; canonicalize their
    // spelling once before consulting the class-owned identity cache.
    source_root.set((Item){.item = s2it(binding_name)});
    return js_private_key_for_class_environment(environment_root.get(), binding_name);
}

extern "C" Item js_private_key_for_current_class(Item source_name) {
    if (js_current_private_home_class.item == 0 ||
        js_current_private_home_class.item == ItemNull.item) {
        Item eval_key = js_eval_private_resolve(source_name);
        if (get_type_id(eval_key) == LMD_TYPE_STRING &&
            property_key_requires_identity(it2s(eval_key)) &&
            property_key_kind(it2s(eval_key)) == NAME_KEY_PRIVATE) {
            return eval_key;
        }
        return js_throw_type_error("Private name used outside its declaring class");
    }
    return js_private_key_for_class(js_current_private_home_class, source_name);
}

extern "C" Item js_private_home_class_enter(Item class_item) {
    Item previous = js_current_private_home_class;
    // Field initializer code is emitted at the construction site rather than
    // through a method wrapper, so establish its lexical class explicitly.
    js_current_private_home_class = class_item;
    js_current_private_home_class_index = js_class_private_index(class_item);
    return previous;
}

extern "C" void js_private_home_class_leave(Item previous_class) {
    js_current_private_home_class = previous_class;
    js_current_private_home_class_index = js_class_private_index(previous_class);
}

extern "C" Item js_private_home_class_leave_result(Item previous_class, Item result) {
    // Restoring the lexical private home through a void call clears the MIR
    // transient exception lane; return the already-computed result through the
    // restore call so an abrupt field/key evaluation remains observable.
    js_private_home_class_leave(previous_class);
    return result;
}

extern "C" Item js_bound_function_target(Item func_item) {
    if (get_type_id(func_item) != LMD_TYPE_FUNC) return ItemNull;
    JsFunction* fn = (JsFunction*)func_item.function;
    if (!fn || !(fn->flags & JS_FUNC_FLAG_HAS_BOUND_THIS)) return ItemNull;
    return fn->bound_target.item ? fn->bound_target : ItemNull;
}

static Item js_bound_function_effective_new_target(Item callee, Item new_target) {
    Item current = callee;
    Item effective = new_target;
    for (int depth = 0; depth < 32 && get_type_id(current) == LMD_TYPE_FUNC; depth++) {
        Item target = js_bound_function_target(current);
        if (target.item == ItemNull.item) break;
        if (effective.item == current.item) effective = target;
        current = target;
    }
    return effective;
}

extern "C" void js_set_method_home_from_target(Item target, Item fn_item) {
    if (get_type_id(fn_item) != LMD_TYPE_FUNC || get_type_id(target) != LMD_TYPE_MAP) return;
    Item home = ItemNull;
    bool class_proto_found = false;
    Item class_proto = js_map_shape_lookup(target.map, "__instance_proto__", 18, &class_proto_found);
    if (class_proto_found && class_proto.item != ItemNull.item) {
        home = target;
    } else {
        Item constructor_key = (Item){.item = s2it(heap_create_name("constructor", 11))};
        Item ctor = js_get_key_default(target, constructor_key);
        if (get_type_id(ctor) == LMD_TYPE_MAP) {
            Item ctor_proto_key = (Item){.item = s2it(heap_create_name("__instance_proto__", 18))};
            Item ctor_proto = js_get_key_default(ctor, ctor_proto_key);
            bool ctor_proto_found = ctor_proto.item != ItemNull.item;
            if (ctor_proto_found && ctor_proto.item != ItemNull.item) home = ctor;
        }
    }
    if (home.item == ItemNull.item || home.item == 0) return;
    // Keep the legacy visible backing property coherent while dispatch reads
    // the dedicated field, avoiding a per-call properties-map hash probe.
    js_set_function_home_class(fn_item, home);
    Item home_key = (Item){.item = s2it(heap_create_name(JS_HOME_CLASS_KEY, JS_HOME_CLASS_KEY_LEN))};
    js_func_init_property(fn_item, home_key, home);
}

extern "C" void js_refresh_prototype_method_homes(Item prototype, Item class_item) {
    if (get_type_id(prototype) != LMD_TYPE_MAP || get_type_id(class_item) != LMD_TYPE_MAP ||
        !prototype.map || !prototype.map->type || !prototype.map->data) return;
    TypeMap* type = (TypeMap*)prototype.map->type;
    for (ShapeEntry* entry = type->shape; entry; entry = entry->next) {
        // Accessor slots use the FUNC tag for Item compatibility, but hold a
        // smaller JsAccessorPair; writing JsFunction home metadata would run
        // past that layout and corrupt a later accessor's getter pointer.
        if (entry->type && entry->type->type_id == LMD_TYPE_FUNC &&
                !jspd_is_accessor(entry)) {
            Item method = map_shape_field_to_item(prototype.map->data, entry);
            if (get_type_id(method) == LMD_TYPE_FUNC) js_set_function_home_class(method, class_item);
        }
    }
}

// v30: Helper to compute callback this value per ES spec OrdinaryCallBindThis.
// thisArg_item is the explicit thisArg (or ITEM_JS_UNDEFINED if not provided).
// For non-strict, non-arrow callbacks: undefined/null → globalThis.
static Item js_compute_callback_this(JsFunction* fn, Item thisArg_item) {
    // The uninitialized-this sentinel is not a value: sloppy-mode coercion would
    // turn it into globalThis or a wrapper object and silently hide the
    // pre-super() TDZ. It must reach the callee intact so a `this` read there
    // still throws (direct eval inside a derived constructor relies on this).
    if (thisArg_item.item == ITEM_JS_TDZ) return thisArg_item;
    if (!(fn->flags & JS_FUNC_FLAG_STRICT) && !(fn->flags & JS_FUNC_FLAG_ARROW)) {
        if (thisArg_item.item == ITEM_JS_UNDEFINED || thisArg_item.item == ITEM_NULL || thisArg_item.item == 0) {
            return js_get_global_this();
        }
        TypeId this_type = get_type_id(thisArg_item);
        if (this_type != LMD_TYPE_MAP && this_type != LMD_TYPE_ARRAY &&
            this_type != LMD_TYPE_ELEMENT && this_type != LMD_TYPE_FUNC &&
            this_type != LMD_TYPE_OBJECT && this_type != LMD_TYPE_VMAP) {
            return js_to_object(thisArg_item);
        }
    }
    return thisArg_item;
}

// Forward declarations for collection types used by property and intrinsic bodies.
#define JS_COLLECTION_MAP 0
#define JS_COLLECTION_SET 1

struct JsCollectionOrderNode {
    Item key;
    Item value;
    JsCollectionOrderNode* next;
    JsCollectionOrderNode* prev;
    bool deleted;
};

struct JsCollectionData {
    HashMap* hmap;
    int type; // JS_COLLECTION_MAP or JS_COLLECTION_SET
    bool is_weak; // true for WeakMap/WeakSet
    JsCollectionOrderNode* order_head;
    JsCollectionOrderNode* order_tail;
};

// Collection instances retain ordinary Map shape/data storage for expandos,
// while this trailing field implements the unobservable [[MapData]]/[[SetData]]
// internal slot. It must never be represented by a string-keyed shape entry.
struct JsCollectionMap {
    Map base;
    JsCollectionData* collection_data;
};

static JsCollectionData* js_get_collection_data(Item obj);



// P2: Pre-computed size class for sizeof(Map) = 32 bytes → SIZE_CLASSES[1] = 32.
// Skips the class-index lookup in gc_heap_alloc and uses the bump-pointer fast path.
#define JS_MAP_SIZE_CLASS 1

// Create a new JS object as a Lambda Map (empty, using map_put for dynamic keys)
extern "C" Item js_new_object() {
    JS_EXEC_PROFILE_SCOPE(JS_EXEC_PROF_NEW_OBJECT);
    Map* m = (Map*)heap_calloc_class(sizeof(Map), LMD_TYPE_MAP, JS_MAP_SIZE_CLASS);
    if (!m) return ItemNull;
    m->type_id = LMD_TYPE_MAP;
    m->type = &EmptyMap;
    return (Item){.map = m};
}

// =============================================================================
// ES6 Proxy
// =============================================================================

// Helper macros: JsProxyData stores target/handler as uint64_t for C header compat
#define PD_TARGET(pd) ((Item){.item = (pd)->target})
#define PD_HANDLER(pd) ((Item){.item = (pd)->handler})
#define PD_PRIVATE_SLOTS(pd) ((Item){.item = (pd)->private_slots})

static bool js_is_constructor_internal(Item callee);

extern "C" bool js_is_proxy(Item obj) {
    return get_type_id(obj) == LMD_TYPE_MAP && obj.map->map_kind == MAP_KIND_PROXY;
}

extern "C" JsProxyData* js_get_proxy_data(Item obj) {
    if (!js_is_proxy(obj)) return NULL;
    return (JsProxyData*)obj.map->data;
}

extern "C" Item js_proxy_get_target(Item obj) {
    int depth = 0;
    while (js_is_proxy(obj) && depth < 32) {
        JsProxyData* pd = js_get_proxy_data(obj);
        if (!pd || pd->revoked) return ItemNull;
        obj = PD_TARGET(pd);
        depth++;
    }
    return obj;
}

static Item js_proxy_private_slots(Item proxy, bool create) {
    JsProxyData* pd = js_get_proxy_data(proxy);
    if (!pd || pd->revoked) return ItemNull;
    Item slots = PD_PRIVATE_SLOTS(pd);
    if (get_type_id(slots) == LMD_TYPE_MAP) return slots;
    if (!create) return ItemNull;
    slots = js_new_object();
    pd->private_slots = slots.item;
    return slots;
}

extern "C" bool js_proxy_has_callable_target(Item obj) {
    JsProxyData* pd = js_get_proxy_data(obj);
    return pd && pd->callable;
}

extern "C" bool js_has_call_capability(Item target) {
    TypeId type = get_type_id(target);
    if (type == LMD_TYPE_FUNC) {
        JsFunction* fn = (JsFunction*)target.function;
        return fn && fn->invoke;
    }
    if (js_is_proxy(target)) {
        JsProxyData* pd = js_get_proxy_data(target);
        return pd && pd->callable;
    }
    if (type == LMD_TYPE_MAP) {
        // The temporary JR4 class-map representation models a class function:
        // it has [[Call]] (which rejects ordinary invocation) and [[Construct]].
        bool own_instance_proto = false;
        js_map_shape_lookup_ext(target.map, "__instance_proto__", 18,
            &own_instance_proto);
        return own_instance_proto;
    }
    return false;
}

// helper: check if object is extensible (returns C bool)
static bool js_is_extensible(Item obj) {
    return it2b(js_to_boolean(js_object_is_extensible(obj)));
}

// helper: look up a trap function on the handler, returns ItemNull if not found
static Item js_proxy_get_trap(JsProxyData* pd, const char* trap_name, int trap_len) {
    if (pd->revoked) {
        return js_throw_value(js_new_error_with_name(
            (Item){.item = s2it(heap_create_name("TypeError", 9))},
            (Item){.item = s2it(heap_create_name("Cannot perform operation on a revoked proxy", 44))}));
    }
    Item handler_item = PD_HANDLER(pd);
    // ES §7.3.10 GetMethod: do a proper [[Get]] (must invoke accessors) and
    // then validate callability. js_map_shape_lookup skips accessor getters.
    JS_ASSIGN_OR_RETURN(trap, js_get_key_default(handler_item,
        (Item){.item = s2it(heap_create_name(trap_name, trap_len))}));
    if (trap.item == ItemNull.item) return ItemNull;
    TypeId tt = get_type_id(trap);
    if (tt == LMD_TYPE_UNDEFINED || tt == LMD_TYPE_NULL) return ItemNull;
    if (!js_is_callable(trap)) {
        // GetMethod observes an exotic [[Call]] capability; the handler may
        // provide a callable Proxy trap (D6.2.2v2).
        char msg[96];
        snprintf(msg, sizeof(msg), "'%.*s' returned for property '%.*s' of object '#<Object>' is not a function",
                 trap_len, trap_name, trap_len, trap_name);
        return js_throw_type_error(msg);
    }
    return trap;
}

extern "C" Item js_proxy_new(Item target, Item handler) {
    // ES2020 §26.2.1.1: both target and handler must be objects
    TypeId tt = get_type_id(target);
    // Ordinary packed numeric arrays use ArrayNum storage but remain ordinary
    // JavaScript objects; rejecting that representation here made Proxy
    // construction disagree with every other object admission path (D4.6.1v2).
    if (tt != LMD_TYPE_MAP && !js_is_ordinary_numeric_array(target) &&
            tt != LMD_TYPE_ARRAY && tt != LMD_TYPE_FUNC && tt != LMD_TYPE_ELEMENT) {
        return js_throw_type_error("Cannot create proxy with a non-object as target");
    }
    TypeId ht = get_type_id(handler);
    if (ht != LMD_TYPE_MAP && !js_is_ordinary_numeric_array(handler) &&
            ht != LMD_TYPE_ARRAY && ht != LMD_TYPE_FUNC && ht != LMD_TYPE_ELEMENT) {
        return js_throw_type_error("Cannot create proxy with a non-object as handler");
    }

    RootFrame roots(2);
    Rooted<Item> target_root(roots, target);
    Rooted<Item> handler_root(roots, handler);
    if (!roots.valid()) return ItemError;
    JsProxyData* pd = (JsProxyData*)mem_alloc(sizeof(JsProxyData), MEM_CAT_JS_RUNTIME);
    if (!pd) return ItemError;
    pd->private_slots = ItemNull.item;
    // Proxy capabilities are immutable creation-time facts. Reading mutable
    // target metadata during every call let ordinary Maps acquire [[Call]].
    pd->callable = js_has_call_capability(target_root.get());
    pd->constructable = js_is_constructor_internal(target_root.get());
    pd->revoked = false;

    Map* m = (Map*)heap_calloc(sizeof(Map), LMD_TYPE_MAP);
    if (!m) {
        mem_free(pd);
        return ItemError;
    }
    // heap_calloc may compact both operands before the Proxy owns them; copy
    // the post-allocation rooted values into the native payload.
    pd->target = target_root.get().item;
    pd->handler = handler_root.get().item;
    m->type_id = LMD_TYPE_MAP;
    m->map_kind = MAP_KIND_PROXY;
    m->type = &EmptyMap;
    m->data = pd;
    m->data_cap = 0;

    return (Item){.map = m};
}

static Item js_proxy_revoke_call_body(Item callee, Item this_value,
        Item* args, int argc, uint64_t* result_home) {
    (void)this_value; (void)args; (void)argc; (void)result_home;
    JsFunction* fn = get_type_id(callee) == LMD_TYPE_FUNC
        ? (JsFunction*)callee.function : NULL;
    if (fn && fn->env && fn->env_size >= 1) {
        JsProxyData* pd = (JsProxyData*)(uintptr_t)fn->env[0].item;
        if (pd) pd->revoked = true;
    }
    return make_js_undefined();
}

// Proxy.revocable(target, handler) → { proxy, revoke }
extern "C" Item js_proxy_revocable(Item target, Item handler) {
    RootFrame roots(3);
    Rooted<Item> proxy_root(roots, ItemNull);
    Rooted<Item> revoke_root(roots, ItemNull);
    Rooted<Item> result_root(roots, ItemNull);
    Item proxy = js_proxy_new(target, handler);
    if (item_is_error(proxy)) return proxy;
    proxy_root.set(proxy);

    JsProxyData* pd = js_get_proxy_data(proxy_root.get());

    // create a fresh revoke function — each call to Proxy.revocable needs its own
    JsFunction* fn = js_alloc_gc_function_object();
    if (!fn) return ItemError;
    revoke_root.set((Item){.function = (Function*)fn});
    fn->func_ptr = NULL;
    fn->param_count = 0;
    fn->formal_length = 0;
    fn->native_call = js_proxy_revoke_call_body;
    fn->native_policy = JS_NATIVE_CALL_BODY;
    fn->name = heap_create_name("", 0);
    fn->prototype = ItemNull;
    // store proxy data pointer in env[0]
    fn->env = js_alloc_env(1);
    fn->env[0] = (Item){.item = (uint64_t)(uintptr_t)pd};
    fn->env_size = 1;
    // The per-object closure owns its revoke target directly; an observable
    // name or sentinel ID must not select its behavior (D6.2.2v2).
    js_function_finalize_capabilities(fn);

    // build result object { proxy, revoke }
    result_root.set(js_new_object());
    // The result does not own either exotic until both data properties are
    // published, so retain every edge across shape allocation (D5.2, D5.3.3).
    js_set_key_default(result_root.get(),
        (Item){.item = s2it(heap_create_name("proxy", 5))}, proxy_root.get());
    js_set_key_default(result_root.get(),
        (Item){.item = s2it(heap_create_name("revoke", 6))}, revoke_root.get());
    return result_root.get();
}

// Proxy [[Get]](key, receiver)
static Item js_proxy_trap_get(Item proxy, Item key, Item receiver) {
    JsProxyData* pd = js_get_proxy_data(proxy);
    if (!pd) return make_js_undefined();
    if (!js_key_is_symbol(key)) key = js_to_property_key(key);
    if (item_is_error(key)) return key;
    JS_ASSIGN_OR_RETURN(trap, js_proxy_get_trap(pd, "get", 3));
    if (trap.item == ItemNull.item) {
        // no trap — forward to target with receiver for getter this-binding.
        return js_get_key_core(PD_TARGET(pd), key, receiver);
    }
    // call trap(target, property, receiver)
    Item args[3] = { PD_TARGET(pd), key, proxy };
    JS_ASSIGN_OR_RETURN(trap_result, js_call_function(trap, PD_HANDLER(pd), args, 3));
    // ES2020 §9.5.8 invariant checks
    Item target = PD_TARGET(pd);
    JS_ASSIGN_OR_RETURN(target_desc, js_object_get_own_property_descriptor(target, key));
    if (get_type_id(target_desc) == LMD_TYPE_MAP) {
        bool conf_found = false;
        Item conf = js_map_shape_lookup(target_desc.map, "configurable", 12, &conf_found);
        bool configurable = conf_found ? it2b(js_to_boolean(conf)) : true;
        if (!configurable) {
            // check if data property
            bool wr_found = false;
            Item wr = js_map_shape_lookup(target_desc.map, "writable", 8, &wr_found);
            if (wr_found && !it2b(js_to_boolean(wr))) {
                // non-configurable non-writable data: trap result must match target value
                bool val_found = false;
                Item tval = js_map_shape_lookup(target_desc.map, "value", 5, &val_found);
                if (val_found) {
                    if (!it2b(js_strict_equal(trap_result, tval))) {
                        return js_throw_type_error("'get' on proxy: property is non-configurable and non-writable on the target, but the trap returned a different value");
                    }
                }
            }
            // check if accessor with undefined getter
            bool get_found = false;
            Item getter = js_map_shape_lookup(target_desc.map, "get", 3, &get_found);
            if (get_found && (getter.item == ItemNull.item || get_type_id(getter) == LMD_TYPE_UNDEFINED)) {
                if (trap_result.item != ItemNull.item && get_type_id(trap_result) != LMD_TYPE_UNDEFINED) {
                    return js_throw_type_error("'get' on proxy: property is a non-configurable accessor with undefined getter, but the trap returned a truthy value");
                }
            }
        }
    }
    return trap_result;
}

extern "C" Item js_reflect_get_with_receiver(Item target, Item key, Item receiver) {
    if (!js_reflect_target_is_object(target)) {
        return js_throw_type_error("Reflect.get called on non-object");
    }
    if (!js_key_is_symbol(key)) key = js_to_property_key(key);
    if (item_is_error(key)) return key;
    if (receiver.item == ItemNull.item) receiver = target;
    return js_get_key_core(target, key, receiver);
}

static Item js_proxy_trap_set_failure(Item key) {
    (void)key;
    // Proxy [[Set]] is a boolean completion. Assignment strictness belongs
    // to js_assignment_set_result, after the trap result returns here.
    return (Item){.item = b2it(false)};
}

// Proxy [[Set]](key, value, receiver)
extern "C" Item js_proxy_trap_set_with_receiver(Item proxy, Item key, Item value, Item receiver) {
    RootFrame roots(6);
    Rooted<Item> proxy_root(roots, proxy);
    Rooted<Item> key_root(roots, key);
    Rooted<Item> value_root(roots, value);
    Rooted<Item> receiver_root(roots, receiver);
    Rooted<Item> trap_root(roots, ItemNull);
    Rooted<Item> descriptor_root(roots, ItemNull);
    JsProxyData* pd = js_get_proxy_data(proxy);
    if (!pd) return (Item){.item = b2it(false)};
    if (!js_key_is_symbol(key)) key = js_to_property_key(key);
    key_root.set(key);
    if (item_is_error(key)) return key;
    Item trap = js_proxy_get_trap(pd, "set", 3);
    trap_root.set(trap);
    if (item_is_error(trap)) return trap;
    if (trap.item == ItemNull.item) {
        return js_reflect_set(PD_TARGET(pd), key, value, receiver);
    }
    // call trap(target, property, value, receiver)
    Item args[4] = { PD_TARGET(pd), key, value, receiver };
    JS_ASSIGN_OR_RETURN(result, js_call_function(trap, PD_HANDLER(pd), args, 4));
    bool bool_result = it2b(js_to_boolean(result));
    if (!bool_result) {
        // ES2020 §9.5.9 step 11: If booleanTrapResult is false, return false.
        // Don't throw — the caller (Reflect.set returns false, assignment in strict mode throws)
        return (Item){.item = b2it(false)};
    }
    // ES2020 §9.5.9 invariant checks
    Item target = PD_TARGET(pd);
    JS_ASSIGN_OR_RETURN(target_desc, js_object_get_own_property_descriptor(target, key));
    descriptor_root.set(target_desc);
    if (get_type_id(target_desc) == LMD_TYPE_MAP) {
        bool conf_found = false;
        Item conf = js_map_shape_lookup(target_desc.map, "configurable", 12, &conf_found);
        bool configurable = conf_found ? it2b(js_to_boolean(conf)) : true;
        if (!configurable) {
            // data property: check writable + value match
            bool wr_found = false;
            Item wr = js_map_shape_lookup(target_desc.map, "writable", 8, &wr_found);
            if (wr_found && !it2b(js_to_boolean(wr))) {
                bool val_found = false;
                Item tval = js_map_shape_lookup(target_desc.map, "value", 5, &val_found);
                if (val_found) {
                    if (!it2b(js_strict_equal(value, tval))) {
                        return js_throw_type_error("'set' on proxy: trap returned truish for property which is non-configurable and non-writable on the target");
                    }
                }
            }
            // accessor with undefined setter
            bool set_found = false;
            Item setter = js_map_shape_lookup(target_desc.map, "set", 3, &set_found);
            if (set_found && (setter.item == ItemNull.item || get_type_id(setter) == LMD_TYPE_UNDEFINED)) {
                return js_throw_type_error("'set' on proxy: trap returned truish for property which has only a getter on the target");
            }
        }
    }
    return (Item){.item = b2it(true)};
}

static Item js_proxy_trap_set(Item proxy, Item key, Item value, Item receiver) {
    JS_ASSIGN_OR_RETURN(result, js_proxy_trap_set_with_receiver(proxy, key, value, receiver));
    if (result.item == (uint64_t)b2it(false)) return js_proxy_trap_set_failure(key);
    return value;
}

// Proxy [[Has]](key)
extern "C" Item js_proxy_trap_has(Item proxy, Item key) {
    JsProxyData* pd = js_get_proxy_data(proxy);
    if (!pd) return (Item){.item = b2it(false)};
    if (!js_key_is_symbol(key)) key = js_to_property_key(key);
    if (item_is_error(key)) return key;
    JS_ASSIGN_OR_RETURN(trap, js_proxy_get_trap(pd, "has", 3));
    if (trap.item == ItemNull.item) {
        // no trap — forward to target using js_in
        return js_in(key, PD_TARGET(pd));
    }
    // call trap(target, property)
    Item args[2] = { PD_TARGET(pd), key };
    JS_ASSIGN_OR_RETURN(result, js_call_function(trap, PD_HANDLER(pd), args, 2));
    bool bool_result = it2b(js_to_boolean(result));
    // ES2020 §9.5.7 invariant checks
    if (!bool_result) {
        Item target = PD_TARGET(pd);
        JS_ASSIGN_OR_RETURN(target_desc, js_object_get_own_property_descriptor(target, key));
        if (get_type_id(target_desc) == LMD_TYPE_MAP) {
            // target has own property — check if non-configurable
            bool conf_found = false;
            Item conf = js_map_shape_lookup(target_desc.map, "configurable", 12, &conf_found);
            bool configurable = conf_found ? it2b(js_to_boolean(conf)) : true;
            if (!configurable) {
                return js_throw_type_error("'has' on proxy: trap returned falsish for property which exists as non-configurable on the target");
            }
            // check extensibility
            bool extensible = it2b(js_to_boolean(js_object_is_extensible(target)));
            if (!extensible) {
                return js_throw_type_error("'has' on proxy: trap returned falsish for property on a non-extensible target");
            }
        }
    }
    return (Item){.item = b2it(bool_result)};
}

// Proxy [[Delete]](key)
extern "C" Item js_proxy_trap_delete(Item proxy, Item key) {
    RootFrame roots(4);
    Rooted<Item> proxy_root(roots, proxy);
    Rooted<Item> key_root(roots, key);
    Rooted<Item> trap_root(roots, ItemNull);
    Rooted<Item> descriptor_root(roots, ItemNull);
    JsProxyData* pd = js_get_proxy_data(proxy);
    if (!pd) return (Item){.item = b2it(false)};
    if (!js_key_is_symbol(key)) key = js_to_property_key(key);
    key_root.set(key);
    if (item_is_error(key)) return key;
    Item trap = js_proxy_get_trap(pd, "deleteProperty", 14);
    trap_root.set(trap);
    if (item_is_error(trap)) return trap;
    if (trap.item == ItemNull.item) {
        return js_reflect_delete_property(PD_TARGET(pd), key);
    }
    Item args[2] = { PD_TARGET(pd), key };
    JS_ASSIGN_OR_RETURN(result, js_call_function(trap, PD_HANDLER(pd), args, 2));
    bool bool_result = it2b(js_to_boolean(result));
    if (bool_result) {
        // ES2020 §9.5.10 invariant checks
        Item target = PD_TARGET(pd);
        JS_ASSIGN_OR_RETURN(target_desc, js_object_get_own_property_descriptor(target, key));
        descriptor_root.set(target_desc);
        if (get_type_id(target_desc) == LMD_TYPE_MAP) {
            bool conf_found = false;
            Item conf = js_map_shape_lookup(target_desc.map, "configurable", 12, &conf_found);
            bool configurable = conf_found ? it2b(js_to_boolean(conf)) : true;
            if (!configurable) {
                return js_throw_type_error("'deleteProperty' on proxy: trap returned truish for property which is non-configurable on the target");
            }
            // non-extensible target: can't delete existing property
            if (!js_is_extensible(target)) {
                return js_throw_type_error("'deleteProperty' on proxy: trap returned truish for property on a non-extensible target");
            }
        }
    }
    return (Item){.item = b2it(bool_result)};
}

