static Item js_proxy_missing_own_key_error(Item key) {
    StrBuf* sb = strbuf_new();
    strbuf_append_str(sb, "'ownKeys' on proxy: trap result did not include ");
    if (get_type_id(key) == LMD_TYPE_STRING) {
        String* s = it2s(key);
        strbuf_append_char(sb, '\'');
        if (s) strbuf_append_str_n(sb, s->chars, s->len);
        strbuf_append_char(sb, '\'');
    } else {
        // The ownKeys invariant is about the exact omitted key; the generic
        // non-configurable text hid array length failures expected by Node.
        Item text = js_to_string_val(key);
        String* s = get_type_id(text) == LMD_TYPE_STRING ? it2s(text) : NULL;
        if (s) strbuf_append_str_n(sb, s->chars, s->len);
        else strbuf_append_str(sb, "non-configurable key");
    }
    Item result = js_throw_type_error(sb->str);
    strbuf_free(sb);
    return result;
}

extern "C" Item js_proxy_trap_own_keys(Item proxy) {
    JsProxyData* pd = js_get_proxy_data(proxy);
    if (!pd) return js_array_new(0);
    JS_ASSIGN_OR_RETURN(trap, js_proxy_get_trap(pd, "ownKeys", 7));
    if (trap.item == ItemNull.item) {
        return js_reflect_own_keys(PD_TARGET(pd));
    }
    Item args[1] = { PD_TARGET(pd) };
    JS_ASSIGN_OR_RETURN(trap_result, js_call_function(trap, PD_HANDLER(pd), args, 1));

    Item key_list = trap_result;
    if (get_type_id(key_list) != LMD_TYPE_ARRAY) {
        TypeId result_type = get_type_id(key_list);
        if (result_type != LMD_TYPE_NULL && result_type != LMD_TYPE_UNDEFINED &&
            result_type != LMD_TYPE_INT && result_type != LMD_TYPE_INT64 &&
            result_type != LMD_TYPE_FLOAT && result_type != LMD_TYPE_BOOL &&
            result_type != LMD_TYPE_STRING && !js_key_is_symbol(key_list)) {
            JS_ASSIGN_OR_RETURN_INTO(key_list, js_array_like_to_array(key_list));
        }
    }

    // ES2020 §9.5.11 invariant checks
    // trap result must be converted to a List (array)
    if (get_type_id(key_list) != LMD_TYPE_ARRAY) {
        return js_throw_type_error("'ownKeys' on proxy: trap result is not an Array");
    }

    // Each element must be a String or Symbol
    int len = js_array_length(key_list);
    for (int i = 0; i < len; i++) {
        Item elem = js_elements_get_int(key_list, i);
        TypeId tid = get_type_id(elem);
        if (tid != LMD_TYPE_STRING && tid != LMD_TYPE_SYMBOL && !js_key_is_symbol(elem)) {
            return js_throw_type_error("'ownKeys' on proxy: trap result must only contain Strings and Symbols");
        }
    }

    // Check for duplicates
    for (int i = 0; i < len; i++) {
        Item a = js_elements_get_int(key_list, i);
        for (int j = i + 1; j < len; j++) {
            Item b = js_elements_get_int(key_list, j);
            if (it2b(js_strict_equal(a, b))) {
                return js_throw_type_error("'ownKeys' on proxy: trap result must not contain duplicate entries");
            }
        }
    }

    // If target is not extensible, must include all target own keys and no extras
    Item target = PD_TARGET(pd);
    if (!js_is_extensible(target)) {
        Item target_keys = js_reflect_own_keys(target);
        int target_len = js_array_length(target_keys);
        // Every target key must be in trap result
        for (int i = 0; i < target_len; i++) {
            Item tk = js_elements_get_int(target_keys, i);
            bool found = false;
            for (int j = 0; j < len; j++) {
                if (it2b(js_strict_equal(tk, js_elements_get_int(key_list, j)))) { found = true; break; }
            }
            if (!found) {
                return js_throw_type_error("'ownKeys' on proxy: trap result did not include all non-extensible target's own keys");
            }
        }
        // No extra keys allowed
        if (len > target_len) {
            return js_throw_type_error("'ownKeys' on proxy: trap returned extra keys for non-extensible target");
        }
    } else {
        // Must include all non-configurable keys
        Item target_keys = js_reflect_own_keys(target);
        int target_len = js_array_length(target_keys);
        for (int i = 0; i < target_len; i++) {
            Item tk = js_elements_get_int(target_keys, i);
            Item td = js_object_get_own_property_descriptor(target, tk);
            if (get_type_id(td) == LMD_TYPE_MAP) {
                bool conf_found = false;
                Item conf = js_map_shape_lookup(td.map, "configurable", 12, &conf_found);
                if (conf_found && !it2b(js_to_boolean(conf))) {
                    // non-configurable — must be in trap result
                    bool found = false;
                    for (int j = 0; j < len; j++) {
                        if (it2b(js_strict_equal(tk, js_elements_get_int(key_list, j)))) { found = true; break; }
                    }
                    if (!found) {
                        return js_proxy_missing_own_key_error(tk);
                    }
                }
            }
        }
    }

    Item result = js_array_new(0);
    for (int i = 0; i < len; i++) {
        js_array_push(result, js_elements_get_int(key_list, i));
    }
    return result;
}

// Proxy [[GetOwnProperty]](key)
extern "C" Item js_proxy_trap_get_own_property_descriptor(Item proxy, Item key) {
    JsProxyData* pd = js_get_proxy_data(proxy);
    if (!pd) return make_js_undefined();
    JS_ASSIGN_OR_RETURN(trap, js_proxy_get_trap(pd, "getOwnPropertyDescriptor", 24));
    if (trap.item == ItemNull.item) {
        return js_object_get_own_property_descriptor(PD_TARGET(pd), key);
    }
    Item args[2] = { PD_TARGET(pd), key };
    JS_ASSIGN_OR_RETURN(trap_result, js_call_function(trap, PD_HANDLER(pd), args, 2));

    // ES2020 §9.5.5 invariant checks
    Item target = PD_TARGET(pd);
    JS_ASSIGN_OR_RETURN(target_desc, js_object_get_own_property_descriptor(target, key));

    // If trap returns undefined
    if (trap_result.item == ItemNull.item || get_type_id(trap_result) == LMD_TYPE_UNDEFINED) {
        if (get_type_id(target_desc) == LMD_TYPE_MAP) {
            // target has this property
            bool conf_found = false;
            Item conf = js_map_shape_lookup(target_desc.map, "configurable", 12, &conf_found);
            bool configurable = conf_found ? it2b(js_to_boolean(conf)) : true;
            if (!configurable) {
                return js_throw_type_error("'getOwnPropertyDescriptor' on proxy: trap returned undefined for property which is non-configurable on the target");
            }
            if (!js_is_extensible(target)) {
                return js_throw_type_error("'getOwnPropertyDescriptor' on proxy: trap returned undefined for property which exists on the non-extensible target");
            }
        }
        return make_js_undefined();
    }

    // trap result must be an Object
    if (get_type_id(trap_result) != LMD_TYPE_MAP) {
        return js_throw_type_error("'getOwnPropertyDescriptor' on proxy: trap must return an object or undefined");
    }

    // Check that the returned descriptor is valid
    // If target property is non-configurable, result must also be non-configurable
    if (get_type_id(target_desc) == LMD_TYPE_MAP) {
        bool td_conf_found = false;
        Item td_conf = js_map_shape_lookup(target_desc.map, "configurable", 12, &td_conf_found);
        bool target_configurable = td_conf_found ? it2b(js_to_boolean(td_conf)) : true;

        bool r_conf_found = false;
        Item r_conf = js_map_shape_lookup(trap_result.map, "configurable", 12, &r_conf_found);
        bool result_configurable = r_conf_found ? it2b(js_to_boolean(r_conf)) : true;

        if (!target_configurable) {
            if (result_configurable) {
                return js_throw_type_error("'getOwnPropertyDescriptor' on proxy: trap returned configurable descriptor for non-configurable property on target");
            }
            // non-configurable non-writable: result must also be non-writable
            bool td_wr_found = false;
            Item td_wr = js_map_shape_lookup(target_desc.map, "writable", 8, &td_wr_found);
            if (td_wr_found && !it2b(js_to_boolean(td_wr))) {
                bool r_wr_found = false;
                Item r_wr = js_map_shape_lookup(trap_result.map, "writable", 8, &r_wr_found);
                if (r_wr_found && it2b(js_to_boolean(r_wr))) {
                    return js_throw_type_error("'getOwnPropertyDescriptor' on proxy: trap returned writable descriptor for non-configurable non-writable property on target");
                }
            }
            // non-configurable + writable target: result must not be non-writable
            if (td_wr_found && it2b(js_to_boolean(td_wr))) {
                bool r_wr_found = false;
                Item r_wr = js_map_shape_lookup(trap_result.map, "writable", 8, &r_wr_found);
                if (r_wr_found && !it2b(js_to_boolean(r_wr))) {
                    return js_throw_type_error("'getOwnPropertyDescriptor' on proxy: trap returned non-writable descriptor for non-configurable writable property on target");
                }
            }
        }

        if (!result_configurable && target_configurable) {
            return js_throw_type_error("'getOwnPropertyDescriptor' on proxy: trap returned non-configurable descriptor for configurable property on target");
        }
    } else {
        // target doesn't have property
        if (!js_is_extensible(target)) {
            return js_throw_type_error("'getOwnPropertyDescriptor' on proxy: trap returned a descriptor for property on a non-extensible target that does not exist on target");
        }
        bool r_conf_found = false;
        Item r_conf = js_map_shape_lookup(trap_result.map, "configurable", 12, &r_conf_found);
        bool result_configurable = r_conf_found ? it2b(js_to_boolean(r_conf)) : true;
        if (!result_configurable) {
            return js_throw_type_error("'getOwnPropertyDescriptor' on proxy: trap returned non-configurable descriptor for property that does not exist on target");
        }
    }

    return trap_result;
}

// Proxy [[DefineOwnProperty]](key, desc)
extern "C" Item js_proxy_trap_define_property(Item proxy, Item key, Item desc) {
    RootFrame roots(5);
    Rooted<Item> proxy_root(roots, proxy);
    Rooted<Item> key_root(roots, key);
    Rooted<Item> input_descriptor_root(roots, desc);
    Rooted<Item> trap_root(roots, ItemNull);
    Rooted<Item> target_descriptor_root(roots, ItemNull);
    JsProxyData* pd = js_get_proxy_data(proxy);
    if (!pd) return (Item){.item = b2it(false)};
    if (!js_key_is_symbol(key)) key = js_to_property_key(key);
    key_root.set(key);
    if (item_is_error(key)) return key;
    Item trap = js_proxy_get_trap(pd, "defineProperty", 14);
    trap_root.set(trap);
    if (item_is_error(trap)) return trap;
    if (trap.item == ItemNull.item) {
        return js_reflect_define_property(PD_TARGET(pd), key, desc);
    }
    Item args[3] = { PD_TARGET(pd), key, desc };
    JS_ASSIGN_OR_RETURN(result, js_call_function(trap, PD_HANDLER(pd), args, 3));
    if (!it2b(js_to_boolean(result))) return (Item){.item = b2it(false)};

    // ES2020 §9.5.6 invariant checks
    Item target = PD_TARGET(pd);
    JS_ASSIGN_OR_RETURN(target_desc, js_object_get_own_property_descriptor(target, key));
    target_descriptor_root.set(target_desc);

    // Check extensibility
    bool extensible = it2b(js_to_boolean(js_object_is_extensible(target)));

    if (target_desc.item == ItemNull.item || get_type_id(target_desc) == LMD_TYPE_UNDEFINED) {
        // target doesn't have this property
        if (!extensible) {
            return js_throw_type_error("'defineProperty' on proxy: trap returned truish for defining property on a non-extensible target");
        }
        // ES2020 §9.5.6 step 19b: if settingConfigFalse is true, throw TypeError
        if (get_type_id(desc) == LMD_TYPE_MAP) {
            bool d_conf_found = false;
            Item d_conf = js_map_shape_lookup(desc.map, "configurable", 12, &d_conf_found);
            if (d_conf_found && !it2b(js_to_boolean(d_conf))) {
                return js_throw_type_error("'defineProperty' on proxy: trap returned truish for defining non-configurable property on a target that does not have it");
            }
        }
    } else {
        // target has this property — check compatibility
        // If target desc is non-configurable, the new desc must be compatible
        if (get_type_id(target_desc) == LMD_TYPE_MAP) {
            bool td_conf_found = false;
            Item td_configurable = js_map_shape_lookup(target_desc.map, "configurable", 12, &td_conf_found);
            bool target_configurable = td_conf_found ? it2b(js_to_boolean(td_configurable)) : true;

            if (!target_configurable) {
                // Desc must not change configurable to true
                if (get_type_id(desc) == LMD_TYPE_MAP) {
                    bool d_conf_found = false;
                    Item d_configurable = js_map_shape_lookup(desc.map, "configurable", 12, &d_conf_found);
                    if (d_conf_found && it2b(js_to_boolean(d_configurable))) {
                        return js_throw_type_error("'defineProperty' on proxy: trap returned truish for defining non-configurable property which is already non-configurable on the target");
                    }
                }
            }
            // ES2020 §9.5.6 step 20b: settingConfigFalse + target configurable → throw
            if (target_configurable) {
                if (get_type_id(desc) == LMD_TYPE_MAP) {
                    bool d_conf_found = false;
                    Item d_conf = js_map_shape_lookup(desc.map, "configurable", 12, &d_conf_found);
                    if (d_conf_found && !it2b(js_to_boolean(d_conf))) {
                        return js_throw_type_error("'defineProperty' on proxy: trap returned truish for defining non-configurable property but target property is configurable");
                    }
                }
            }
            if (!target_configurable) {
                bool td_writable_found = false;
                Item td_writable = js_map_shape_lookup(target_desc.map, "writable", 8, &td_writable_found);
                bool target_writable = td_writable_found ? it2b(js_to_boolean(td_writable)) : true;

                if (get_type_id(desc) == LMD_TYPE_MAP) {
                    // Check if trying to change value of non-configurable non-writable property
                    if (!target_writable) {
                        bool d_val_found = false;
                        Item d_value = js_map_shape_lookup(desc.map, "value", 5, &d_val_found);
                        if (d_val_found) {
                            bool td_val_found = false;
                            Item td_value = js_map_shape_lookup(target_desc.map, "value", 5, &td_val_found);
                            if (td_val_found) {
                                if (!it2b(js_strict_equal(d_value, td_value))) {
                                    return js_throw_type_error("'defineProperty' on proxy: trap returned truish for property which is non-configurable and non-writable on the target");
                                }
                            }
                        }
                        bool d_wr_found = false;
                        Item d_writable = js_map_shape_lookup(desc.map, "writable", 8, &d_wr_found);
                        if (d_wr_found && it2b(js_to_boolean(d_writable))) {
                            return js_throw_type_error("'defineProperty' on proxy: trap returned truish for property which is non-configurable and non-writable on the target");
                        }
                    }
                    // ES2020 §9.5.6 step 20c: non-configurable + writable → desc.writable false throws
                    if (target_writable) {
                        bool d_wr_found = false;
                        Item d_writable = js_map_shape_lookup(desc.map, "writable", 8, &d_wr_found);
                        if (d_wr_found && !it2b(js_to_boolean(d_writable))) {
                            return js_throw_type_error("'defineProperty' on proxy: trap returned truish for making non-configurable writable property non-writable");
                        }
                    }
                }
            }
        }
    }
    return (Item){.item = b2it(true)};
}

// Proxy [[GetPrototypeOf]]()
extern "C" Item js_proxy_trap_get_prototype_of(Item proxy) {
    JsProxyData* pd = js_get_proxy_data(proxy);
    if (!pd) return ItemNull;
    JS_ASSIGN_OR_RETURN(trap, js_proxy_get_trap(pd, "getPrototypeOf", 14));
    if (trap.item == ItemNull.item) {
        return js_get_prototype_of(PD_TARGET(pd));
    }
    Item args[1] = { PD_TARGET(pd) };
    LAMBDA_SCALAR_HOME(get_prototype_trap_home);
    // The result is validated and consumed by this proxy operation before it
    // returns, so the temporary home cannot escape this native frame.
    JS_ASSIGN_OR_RETURN(result, js_call_function_into(trap, PD_HANDLER(pd), args, 1,
        &get_prototype_trap_home));
    // ES2020 §9.5.1 invariant: result must be Object or null
    TypeId rt = get_type_id(result);
    if (rt != LMD_TYPE_MAP && rt != LMD_TYPE_ARRAY && rt != LMD_TYPE_FUNC &&
        rt != LMD_TYPE_ELEMENT && result.item != ItemNull.item && rt != LMD_TYPE_NULL) {
        return js_throw_type_error("'getPrototypeOf' on proxy: trap returned neither object nor null");
    }
    // If target is not extensible, result must match target's prototype
    if (!js_is_extensible(PD_TARGET(pd))) {
        JS_ASSIGN_OR_RETURN(target_proto, js_get_prototype_of(PD_TARGET(pd)));
        if (!it2b(js_strict_equal(result, target_proto))) {
            return js_throw_type_error("'getPrototypeOf' on proxy: proxy target is non-extensible but the trap did not return its actual prototype");
        }
    }
    return result;
}

// Proxy [[SetPrototypeOf]](proto)
extern "C" Item js_proxy_trap_set_prototype_of(Item proxy, Item proto) {
    JsProxyData* pd = js_get_proxy_data(proxy);
    if (!pd) return (Item){.item = b2it(false)};
    JS_ASSIGN_OR_RETURN(trap, js_proxy_get_trap(pd, "setPrototypeOf", 14));
    if (trap.item == ItemNull.item) {
        return js_reflect_set_prototype_of(PD_TARGET(pd), proto);
    }
    Item args[2] = { PD_TARGET(pd), proto };
    LAMBDA_SCALAR_HOME(set_prototype_trap_home);
    // The trap result is immediately coerced to boolean, so this native
    // boundary is a terminal scalar consumer rather than a forwarding ABI.
    JS_ASSIGN_OR_RETURN(result, js_call_function_into(trap, PD_HANDLER(pd), args, 2,
        &set_prototype_trap_home));
    bool bool_result = it2b(js_to_boolean(result));
    // ES2020 §9.5.2 step 9: If booleanTrapResult is false, return false
    // (skip IsExtensible check — step 10 only applies when trap returned true)
    if (!bool_result) {
        return (Item){.item = b2it(false)};
    }
    // ES2020 §9.5.2 step 10-12 invariant: if target is not extensible, proto must match target's prototype.
    // Use the abstract IsExtensible operation and propagate abrupt completion.
    JS_ASSIGN_OR_RETURN(target_extensible_item, js_object_is_extensible(PD_TARGET(pd)));
    bool target_extensible = it2b(js_to_boolean(target_extensible_item));
    if (!target_extensible) {
        JS_ASSIGN_OR_RETURN(target_proto, js_get_prototype_of(PD_TARGET(pd)));
        if (!it2b(js_strict_equal(proto, target_proto))) {
            return js_throw_type_error("'setPrototypeOf' on proxy: trap returned truish for setting a new prototype on a non-extensible target");
        }
    }
    return (Item){.item = b2it(bool_result)};
}

// Proxy [[IsExtensible]]()
extern "C" Item js_proxy_trap_is_extensible(Item proxy) {
    JsProxyData* pd = js_get_proxy_data(proxy);
    if (!pd) return (Item){.item = b2it(false)};
    JS_ASSIGN_OR_RETURN(trap, js_proxy_get_trap(pd, "isExtensible", 12));
    if (trap.item == ItemNull.item) {
        return js_object_is_extensible(PD_TARGET(pd));
    }
    Item args[1] = { PD_TARGET(pd) };
    JS_ASSIGN_OR_RETURN(result, js_call_function(trap, PD_HANDLER(pd), args, 1));
    bool bool_result = it2b(js_to_boolean(result));
    // ES2020 §9.5.3 invariant: must match target's actual extensibility
    bool target_extensible = js_is_extensible(PD_TARGET(pd));
    if (bool_result != target_extensible) {
        return js_throw_type_error("'isExtensible' on proxy: trap result does not reflect extensibility of proxy target");
    }
    return (Item){.item = b2it(bool_result)};
}

// Proxy [[PreventExtensions]]()
extern "C" Item js_proxy_trap_prevent_extensions(Item proxy) {
    JsProxyData* pd = js_get_proxy_data(proxy);
    if (!pd) return ItemNull;
    JS_ASSIGN_OR_RETURN(trap, js_proxy_get_trap(pd, "preventExtensions", 17));
    if (trap.item == ItemNull.item) {
        return js_object_prevent_extensions(PD_TARGET(pd));
    }
    Item args[1] = { PD_TARGET(pd) };
    JS_ASSIGN_OR_RETURN(result, js_call_function(trap, PD_HANDLER(pd), args, 1));
    bool bool_result = it2b(js_to_boolean(result));
    // ES2020 §9.5.4 invariant: if trap returns true, target must actually be non-extensible
    if (bool_result) {
        if (js_is_extensible(PD_TARGET(pd))) {
            return js_throw_type_error("'preventExtensions' on proxy: trap returned truish but the proxy target is extensible");
        }
    }
    return (Item){.item = b2it(bool_result)};
}

// Proxy [[Call]](thisArg, args)
extern "C" Item js_proxy_trap_apply(Item proxy, Item this_val, Item* args, int arg_count) {
    JsProxyData* pd = js_get_proxy_data(proxy);
    if (!pd) return ItemNull;
    if (!pd->callable) return js_throw_type_error("is not a function");
    JS_ASSIGN_OR_RETURN(trap, js_proxy_get_trap(pd, "apply", 5));
    if (trap.item == ItemNull.item) {
        return js_call_function(PD_TARGET(pd), this_val, args, arg_count);
    }
    // build args array
    Item args_array = js_array_new(0);
    for (int i = 0; i < arg_count; i++) {
        js_array_push(args_array, args[i]);
    }
    Item trap_args[3] = { PD_TARGET(pd), this_val, args_array };
    return js_call_function(trap, PD_HANDLER(pd), trap_args, 3);
}

// Proxy [[Construct]](args, newTarget)
extern "C" Item js_proxy_trap_construct(Item proxy, Item* args, int arg_count, Item new_target) {
    JsProxyData* pd = js_get_proxy_data(proxy);
    if (!pd) return ItemNull;
    JS_ASSIGN_OR_RETURN(trap, js_proxy_get_trap(pd, "construct", 9));
    if (trap.item == ItemNull.item) {
        Item args_array = js_array_new(0);
        for (int i = 0; i < arg_count; i++) {
            js_array_push(args_array, args[i]);
        }
        Item nt = new_target.item != ItemNull.item ? new_target : proxy;
        return js_reflect_construct(PD_TARGET(pd), args_array, nt);
    }
    // build args array
    Item args_array = js_array_new(0);
    for (int i = 0; i < arg_count; i++) {
        js_array_push(args_array, args[i]);
    }
    Item trap_args[3] = { PD_TARGET(pd), args_array, new_target.item != ItemNull.item ? new_target : proxy };
    JS_ASSIGN_OR_RETURN(result, js_call_function(trap, PD_HANDLER(pd), trap_args, 3));
    if (get_type_id(result) != LMD_TYPE_MAP && !js_is_js_array(result) &&
        get_type_id(result) != LMD_TYPE_FUNC) {
        return js_throw_type_error("'construct' on proxy: trap returned non-object");
    }
    return result;
}

// Create a new object for a constructor call: sets __proto__ from callee.prototype
extern "C" Item js_constructor_create_object(Item callee, Item new_target) {
    // Prototype lookup and builtin subclass allocation can compact the
    // unpublished instance; native argument registers are not GC roots.
    RootFrame roots(7);
    Rooted<Item> callee_root(roots, callee);
    Rooted<Item> target_root(roots,
        new_target.item ? new_target : callee);
    Rooted<Item> proto_source_root(roots, ItemNull);
    Rooted<Item> instance_proto_root(roots, ItemNull);
    Rooted<Item> object_root(roots, ItemNull);
    Rooted<Item> aux_one_root(roots, ItemNull);
    Rooted<Item> aux_two_root(roots, ItemNull);
    if (!roots.valid()) return ItemNull;
    object_root.set(js_new_object());
    TypeId callee_type = get_type_id(callee_root.get());
    if (callee_type == LMD_TYPE_FUNC || js_is_proxy(callee_root.get())) {
        // Bound construction substitutes the ultimate target only when the
        // explicit newTarget names the bound wrapper itself (D6.2.2v2).
        proto_source_root.set(js_bound_function_effective_new_target(
            callee_root.get(), target_root.get()));
        Item proto_key = (Item){.item = s2it(heap_create_name("prototype", 9))};
        instance_proto_root.set(js_get_key_default(proto_source_root.get(), proto_key));
        if (item_is_error(instance_proto_root.get())) return instance_proto_root.get();
        TypeId instance_proto_type = get_type_id(instance_proto_root.get());
        bool instance_proto_is_object = instance_proto_type == LMD_TYPE_MAP ||
            instance_proto_type == LMD_TYPE_FUNC ||
            instance_proto_type == LMD_TYPE_ARRAY ||
            instance_proto_type == LMD_TYPE_ELEMENT;
        if (!instance_proto_is_object && js_is_proxy(proto_source_root.get())) {
            JsProxyData* pd = js_get_proxy_data(proto_source_root.get());
            if (pd && pd->revoked) {
                return js_throw_type_error("Cannot perform operation on a revoked proxy");
            }
        }
        if (instance_proto_root.get().item != ItemNull.item) {
            TypeId pt = instance_proto_type;
            if (pt == LMD_TYPE_MAP || pt == LMD_TYPE_FUNC) {
                // Subclass builtin detection: walk the prototype chain of instance_proto
                // to find if a builtin class (Array, Map, Set, RegExp, Date, etc.) is in the ancestor chain.
                Item proto = js_get_prototype(instance_proto_root.get());
                int depth = 0;
                while (proto.item != ItemNull.item && depth < 16) {
                    TypeId proto_t = get_type_id(proto);
                    if (proto_t == LMD_TYPE_MAP) {
                        bool created_builtin = false;
                        switch (js_class_id(proto)) {
                            case JS_CLASS_ARRAY:
                                object_root.set(js_array_new(0));
                                created_builtin = true;
                                break;
                            case JS_CLASS_MAP:
                                object_root.set(js_map_collection_new());
                                created_builtin = true;
                                break;
                            case JS_CLASS_SET:
                                object_root.set(js_set_collection_new());
                                created_builtin = true;
                                break;
                            case JS_CLASS_WEAK_MAP: {
                                object_root.set(js_weakmap_new());
                                created_builtin = true;
                                break;
                            }
                            case JS_CLASS_WEAK_SET: {
                                object_root.set(js_weakset_new());
                                created_builtin = true;
                                break;
                            }
                            case JS_CLASS_REGEXP: {
                                aux_one_root.set((Item){.item = s2it(heap_create_name("(?:)", 4))});
                                aux_two_root.set((Item){.item = s2it(heap_create_name("", 0))});
                                object_root.set(js_regexp_construct(aux_one_root.get(), aux_two_root.get()));
                                created_builtin = true;
                                break;
                            }
                            case JS_CLASS_DATE: {
                                object_root.set(js_date_new());
                                created_builtin = true;
                                break;
                            }
                            case JS_CLASS_PROMISE: {
                                object_root.set(js_promise_create_pending());
                                created_builtin = true;
                                break;
                            }
                            default:
                                break;
                        }
                        if (created_builtin) break;
                        proto = js_get_prototype(proto);
                    } else {
                        break;
                    }
                    depth++;
                }
                js_set_prototype(object_root.get(), instance_proto_root.get());
            } else if (js_is_js_array(instance_proto_root.get()) || pt == LMD_TYPE_ELEMENT) {
                // ES OrdinaryCreateFromConstructor: when constructor's .prototype is
                // any Object (incl. Array/Element), use it as instance's [[Prototype]].
                js_set_prototype(object_root.get(), instance_proto_root.get());
            }
        }
    }
    return object_root.get();
}

// Dynamic class instantiation: new Type() where Type is a runtime variable.
// Handles both function constructors and class objects (MAPs with __ctor__).
static int js_resolve_ta_type_from_ctor(Item ctor);

static int js_resolve_ta_type_from_class_map(Item class_item) {
    int ta_type = js_resolve_ta_type_from_ctor(js_get_prototype(class_item));
    if (ta_type >= 0) return ta_type;
    if (get_type_id(class_item) != LMD_TYPE_MAP) return -1;
    bool instance_proto_own = false;
    Item instance_proto = js_map_shape_lookup(class_item.map, "__instance_proto__", 18, &instance_proto_own);
    if (instance_proto.item == ItemNull.item) {
        Item prototype_key = (Item){.item = s2it(heap_create_name("prototype", 9))};
        instance_proto = js_get_key_default(class_item, prototype_key);
    }
    Item proto = instance_proto;
    int depth = 0;
    while (proto.item != ItemNull.item && get_type_id(proto) == LMD_TYPE_MAP && depth < 16) {
        Item ctor_key = (Item){.item = s2it(heap_create_name("constructor", 11))};
        Item proto_ctor = js_get_key_default(proto, ctor_key);
        ta_type = js_resolve_ta_type_from_ctor(proto_ctor);
        if (ta_type >= 0) return ta_type;
        proto = js_get_prototype(proto);
        depth++;
    }
    return -1;
}

static Item js_typed_array_create_with_constructor(Item constructor, int length) {
    int ta_type = js_resolve_ta_type_from_ctor(constructor);
    if (ta_type >= 0) {
        return js_typed_array_new(ta_type, length);
    }

    TypeId constructor_type = get_type_id(constructor);
    if (constructor_type != LMD_TYPE_FUNC && constructor_type != LMD_TYPE_MAP) {
        return js_throw_type_error("TypedArrayCreate requires a TypedArray constructor");
    }
    if (constructor_type == LMD_TYPE_FUNC) {
        JsFunction* fn = (JsFunction*)constructor.function;
        if (!fn || !fn->construct) {
            return js_throw_type_error("TypedArrayCreate requires a constructor");
        }
    }

    Item len_arg = (Item){.item = i2it(length)};
    JS_ASSIGN_OR_RETURN(result, js_construct_value(constructor, &len_arg, 1,
        constructor, NULL, false));
    if (!js_is_typed_array(result)) {
        return js_throw_type_error("TypedArrayCreate constructor did not return a TypedArray");
    }
    if (js_typed_array_length(result) < length) {
        return js_throw_type_error("TypedArrayCreate constructor returned a TypedArray that is too small");
    }
    return result;
}

static bool js_can_host_private_slots(Item object) {
    TypeId type = get_type_id(object);
    return type == LMD_TYPE_MAP || type == LMD_TYPE_ARRAY || type == LMD_TYPE_FUNC ||
        type == LMD_TYPE_ELEMENT || type == LMD_TYPE_OBJECT || type == LMD_TYPE_VMAP;
}

static bool js_private_storage_has_own(Item object, Item private_key) {
    if (get_type_id(private_key) != LMD_TYPE_STRING ||
        !property_key_requires_identity(it2s(private_key)) ||
        property_key_kind(it2s(private_key)) != NAME_KEY_PRIVATE) return false;
    Item lookup_object = object;
    if (js_is_proxy(object)) {
        lookup_object = js_proxy_private_slots(object, false);
    }
    if (get_type_id(lookup_object) != LMD_TYPE_MAP) return false;
    JsShapeSlotStatus status = js_own_shape_slot_status_name_id(
        lookup_object, property_key_id(it2s(private_key)), NULL, NULL);
    return status == JS_SHAPE_SLOT_DATA || status == JS_SHAPE_SLOT_ACCESSOR;
}

static Item js_private_brand_key_for_class(Item class_item) {
    if (get_type_id(class_item) != LMD_TYPE_MAP || !context || !context->name_pool) {
        return ItemNull;
    }
    bool found = false;
    Item brand = js_map_shape_lookup(class_item.map, "__pk_brand__", 12, &found);
    if (found && get_type_id(brand) == LMD_TYPE_STRING &&
        property_key_requires_identity(it2s(brand)) &&
        property_key_kind(it2s(brand)) == NAME_KEY_PRIVATE) {
        return brand;
    }
    NameRef brand_key = name_pool_create_unique_private(context->name_pool,
        {"<private brand>", 15});
    if (!brand_key) return ItemNull;
    RootFrame roots(3);
    Rooted<Item> class_root(roots, class_item);
    Rooted<Item> key_root(roots,
        (Item){.item = s2it(heap_create_name("__pk_brand__", 12))});
    Rooted<Item> brand_root(roots, (Item){.item = s2it(brand_key)});
    if (!roots.valid()) return ItemNull;
    // The brand belongs to the evaluated class, never to a diagnostic member spelling.
    JS_ASSIGN_OR_RETURN(set_result, js_set_key_default(class_root.get(), key_root.get(), brand_root.get()));
    js_mark_non_enumerable(class_root.get(), key_root.get());
    return brand_root.get();
}

static Item js_private_brand_key_for_class_existing(Item class_item) {
    if (get_type_id(class_item) != LMD_TYPE_MAP) return ItemNull;
    bool found = false;
    Item brand = js_map_shape_lookup(class_item.map, "__pk_brand__", 12, &found);
    if (!found || get_type_id(brand) != LMD_TYPE_STRING ||
        !property_key_requires_identity(it2s(brand)) ||
        property_key_kind(it2s(brand)) != NAME_KEY_PRIVATE) return ItemNull;
    return brand;
}

static bool js_private_brand_storage_has_own(Item object, Item class_item) {
    Item brand_key = js_private_brand_key_for_class(class_item);
    return brand_key.item != ItemNull.item && js_private_storage_has_own(object, brand_key);
}

// Brand-check bypass scoped to private-field *definition* only. Distinct from
// js_private_field_initializing (which stays on for the whole field-init phase so
// eval inside an initializer still sees the field-initializer early-error
// context). On only while a field's own declaration is being added, so a private
// access inside an initializer *expression* is brand-checked normally and throws
// for a not-yet-installed private member (ES PrivateFieldSet ordering).
#define js_private_define_active (js_runtime_state.operations.private_define_active)

extern "C" void js_init_class_instance_field_metadata(Item class_item, int count) {
    if (get_type_id(class_item) != LMD_TYPE_MAP || count <= 0) {
        return;
    }
    RootFrame roots(6);
    Rooted<Item> class_root(roots, class_item);
    Rooted<Item> keys_root(roots, js_array_new(count));
    Rooted<Item> values_root(roots, js_array_new(count));
    Rooted<Item> kinds_root(roots, js_array_new(count));
    Rooted<Item> initializers_root(roots, js_array_new(count));
    Rooted<Item> key_root(roots, ItemNull);
    if (!roots.valid()) return;

    for (int i = 0; i < count; i++) {
        keys_root.get().array->items[i] = make_js_undefined();
        values_root.get().array->items[i] = make_js_undefined();
        kinds_root.get().array->items[i] = (Item){.item = i2it(0)};
        initializers_root.get().array->items[i] = make_js_undefined();
    }

    const char* property_names[] = {
        "__if_keys__", "__if_values__", "__if_kinds__", "__if_inits__"
    };
    Item property_values[] = {
        keys_root.get(), values_root.get(), kinds_root.get(), initializers_root.get()
    };
    for (int i = 0; i < 4; i++) {
        key_root.set((Item){.item = s2it(heap_create_name(
            property_names[i], (int)strlen(property_names[i])))});
        Item set_result = js_set_key_default(class_root.get(), key_root.get(), property_values[i]);
        if (item_is_error(set_result)) return;
        js_mark_non_enumerable(class_root.get(), key_root.get());
    }
}

extern "C" void js_set_class_instance_field_metadata_name_id_range(
    Item class_item, int index, uint32_t module_name_base, int count,
    uint64_t method_mask) {
    if (get_type_id(class_item) != LMD_TYPE_MAP || index < 0 || count <= 0 ||
            !context || !context->active_js_module_state) return;
    LambdaModuleState* state = context->active_js_module_state;
    if (!state->property_keys || module_name_base > state->property_key_count ||
            (uint32_t)count > state->property_key_count - module_name_base) return;
    RootFrame roots(4);
    Rooted<Item> class_root(roots, class_item);
    Rooted<Item> environment_root(roots, ItemNull);
    if (!roots.valid()) return;

    bool keys_found = false;
    bool kinds_found = false;
    Item keys = js_map_shape_lookup(class_root.get().map, "__if_keys__", 11, &keys_found);
    Item kinds = js_map_shape_lookup(class_root.get().map, "__if_kinds__", 12, &kinds_found);
    if (!keys_found || get_type_id(keys) != LMD_TYPE_ARRAY ||
            index + count > keys.array->length) return;
    for (int offset = 0; offset < count; offset++) {
        NameId source_name_id = state->property_keys[module_name_base + (uint32_t)offset];
        NameRef source_name = name_pool_resolve_id(context->name_pool, source_name_id);
        if (!source_name) return;
        bool private_source = js_private_source_name((Item){.item = s2it(source_name)});
        if (private_source && get_type_id(environment_root.get()) != LMD_TYPE_MAP) {
            environment_root.set(js_private_environment_for_class(class_root.get(), true));
            if (get_type_id(environment_root.get()) != LMD_TYPE_MAP) return;
        }
        Item key = private_source
            ? js_private_key_for_class_environment(environment_root.get(), source_name)
            : (Item){.item = s2it(source_name)};
        if (item_is_error(key) || key.item == ItemNull.item) return;
        keys.array->items[index + offset] = key;
        if (kinds_found && get_type_id(kinds) == LMD_TYPE_ARRAY &&
                index + offset < kinds.array->length) {
            kinds.array->items[index + offset] = (Item){.item = i2it(
                (method_mask >> offset) & 1u)};
        }
    }
}

extern "C" void js_set_class_instance_field_metadata_value(
    Item class_item, int index, Item value) {
    if (get_type_id(class_item) != LMD_TYPE_MAP || index < 0) return;
    bool found = false;
    Item values = js_map_shape_lookup(class_item.map, "__if_values__", 13, &found);
    if (!found || get_type_id(values) != LMD_TYPE_ARRAY ||
        index >= values.array->length) {
        return;
    }
    values.array->items[index] = value;
}

extern "C" void js_set_class_instance_field_metadata_initializer(
    Item class_item, int index, Item initializer) {
    if (get_type_id(class_item) != LMD_TYPE_MAP || index < 0 ||
        !js_is_callable(initializer)) return;
    bool found = false;
    Item initializers = js_map_shape_lookup(class_item.map, "__if_inits__", 12,
        &found);
    if (!found || get_type_id(initializers) != LMD_TYPE_ARRAY ||
        index >= initializers.array->length) return;
    initializers.array->items[index] = initializer;
}

extern "C" void js_set_class_instance_field_metadata_key(
    Item class_item, int index, Item key) {
    if (get_type_id(class_item) != LMD_TYPE_MAP || index < 0) return;
    bool found = false;
    Item keys = js_map_shape_lookup(class_item.map, "__if_keys__", 11, &found);
    if (!found || get_type_id(keys) != LMD_TYPE_ARRAY || index >= keys.array->length) {
        return;
    }
    keys.array->items[index] = key;
}

static Item js_init_class_instance_field(Item callee, Item object, Item field_key,
    bool value_found, Item field_value, bool brand_only) {
    RootFrame roots(4);
    Rooted<Item> callee_root(roots, callee);
    Rooted<Item> object_root(roots, object);
    Rooted<Item> key_root(roots, field_key);
    Rooted<Item> value_root(roots, field_value);
    if (!roots.valid()) return js_status_ok();

    bool private_key = get_type_id(key_root.get()) == LMD_TYPE_STRING &&
        property_key_requires_identity(it2s(key_root.get())) &&
        property_key_kind(it2s(key_root.get())) == NAME_KEY_PRIVATE;
    if (private_key) {
        bool duplicate_private = brand_only ?
            js_private_brand_storage_has_own(object_root.get(), callee_root.get()) :
            js_private_storage_has_own(object_root.get(), key_root.get());
        if (duplicate_private) {
            if (brand_only) {
                // Derived public field initializers install their private-method
                // brand immediately after `super()`; metadata finalization must
                // treat that same class brand as already established.
                return js_status_ok();
            }
            return js_throw_type_error("Cannot initialize private member twice on the same object");
        }
    }
    if (!brand_only) {
        if (!value_found) value_root.set(make_js_undefined());
        if (private_key) {
            ScopedPrivateDefineActive define_guard;
            JS_ASSIGN_OR_RETURN(set_result, js_set_key_default(object_root.get(), key_root.get(), value_root.get()));
        } else {
            // Each public field record performs DefineField in source order;
            // duplicate spellings intentionally replace the earlier own value.
            JS_ASSIGN_OR_RETURN(create_result, js_create_data_property(object_root.get(), key_root.get(), value_root.get()));
        }
    }
    if (private_key) {
        key_root.set(js_private_brand_key_for_class(callee_root.get()));
        if (key_root.get().item == ItemNull.item) return js_status_ok();
        ScopedPrivateDefineActive define_guard;
        JS_ASSIGN_OR_RETURN(set_result, js_set_key_default(object_root.get(), key_root.get(), callee_root.get()));
    }
    return js_status_ok();
}

static Item js_init_class_instance_fields_inner(Item callee, Item object) {
    if (get_type_id(callee) != LMD_TYPE_MAP) return js_status_ok();
    if (!js_can_host_private_slots(object)) return js_status_ok();

    RootFrame roots(2);
    Rooted<Item> callee_root(roots, callee);
    Rooted<Item> object_root(roots, object);
    if (!roots.valid()) return js_status_ok();

    bool keys_found = false;
    Item field_keys = js_map_shape_lookup(callee_root.get().map, "__if_keys__", 11,
        &keys_found);
    if (keys_found && get_type_id(field_keys) == LMD_TYPE_ARRAY) {
        bool values_found = false;
        bool kinds_found = false;
        bool initializers_found = false;
        Item field_values = js_map_shape_lookup(callee_root.get().map,
            "__if_values__", 13, &values_found);
        Item field_kinds = js_map_shape_lookup(callee_root.get().map,
            "__if_kinds__", 12, &kinds_found);
        Item field_initializers = js_map_shape_lookup(callee_root.get().map,
            "__if_inits__", 12, &initializers_found);
        int64_t field_count = field_keys.array->length;
        bool has_private_method_brand = false;
        for (int64_t field_index = 0; field_index < field_count; field_index++) {
            if (kinds_found && get_type_id(field_kinds) == LMD_TYPE_ARRAY &&
                    field_index < field_kinds.array->length &&
                    get_type_id(field_kinds.array->items[field_index]) == LMD_TYPE_INT &&
                    it2i(field_kinds.array->items[field_index]) == 1) {
                has_private_method_brand = true;
                break;
            }
        }
        if (has_private_method_brand && js_private_brand_storage_has_own(
                object_root.get(), callee_root.get())) {
            // A class installs one brand for all of its private methods. Seeing
            // it before this initialization pass means the same receiver is
            // being initialized by the class for a second time.
            return js_throw_type_error(
                "Cannot initialize private member twice on the same object");
        }
        // Private methods/accessors are installed before any instance field
        // initializer runs. Delaying the brand-only records until their source
        // position made an earlier `this.#method()` initializer fail (D6.2.2v2).
        for (int64_t field_index = 0; field_index < field_count; field_index++) {
            bool brand_only = kinds_found &&
                get_type_id(field_kinds) == LMD_TYPE_ARRAY &&
                field_index < field_kinds.array->length &&
                get_type_id(field_kinds.array->items[field_index]) == LMD_TYPE_INT &&
                it2i(field_kinds.array->items[field_index]) == 1;
            if (!brand_only) continue;
            Item field_key = field_keys.array->items[field_index];
            if (get_type_id(field_key) != LMD_TYPE_STRING &&
                get_type_id(field_key) != LMD_TYPE_SYMBOL) continue;
            JS_RETURN_IF_ERROR(js_init_class_instance_field(
                callee_root.get(), object_root.get(), field_key, false,
                make_js_undefined(), true));
        }
        for (int64_t field_index = 0; field_index < field_count; field_index++) {
            Item field_key = field_keys.array->items[field_index];
            if (get_type_id(field_key) != LMD_TYPE_STRING &&
                get_type_id(field_key) != LMD_TYPE_SYMBOL) break;
            bool value_found = values_found && get_type_id(field_values) == LMD_TYPE_ARRAY &&
                field_index < field_values.array->length;
            Item field_value = value_found ?
                field_values.array->items[field_index] : make_js_undefined();
            bool brand_only = kinds_found && get_type_id(field_kinds) == LMD_TYPE_ARRAY &&
                field_index < field_kinds.array->length &&
                get_type_id(field_kinds.array->items[field_index]) == LMD_TYPE_INT &&
                it2i(field_kinds.array->items[field_index]) == 1;
            if (brand_only) continue;
            if (initializers_found &&
                get_type_id(field_initializers) == LMD_TYPE_ARRAY &&
                field_index < field_initializers.array->length &&
                js_is_callable(field_initializers.array->items[field_index])) {
                JS_ASSIGN_OR_RETURN(initialized_value,
                    js_call_function(field_initializers.array->items[field_index],
                        object_root.get(), NULL, 0));
                field_value = initialized_value;
                value_found = true;
                js_set_function_name_if_anonymous(field_value, field_key);
            }
            JS_RETURN_IF_ERROR(js_init_class_instance_field(
                callee_root.get(), object_root.get(), field_key, value_found,
                field_value, false));
        }
        return js_status_ok();
    }

    bool field_count_found = false;
    Item field_count_item = js_map_shape_lookup(callee.map, "__if_count__", 12, &field_count_found);
    if (!field_count_found || get_type_id(field_count_item) != LMD_TYPE_INT) return js_status_ok();
    int64_t field_count = it2i(field_count_item);
    if (field_count <= 0) return js_status_ok();
    for (int64_t field_index = 0; field_index < field_count; field_index++) {
        char key_slot[32];
        int key_slot_len = snprintf(key_slot, sizeof(key_slot), "__if_key_%lld", (long long)field_index);
        bool key_found = false;
        Item field_key = js_map_shape_lookup(callee.map, key_slot, key_slot_len, &key_found);
        if (!key_found || get_type_id(field_key) != LMD_TYPE_STRING) {
            // Generated field metadata is dense; stopping on a gap prevents tampered
            // counts from turning the retired 32-field cap into an unbounded scan.
            break;
        }

        bool brand_only = false;
        char kind_slot[32];
        int kind_slot_len = snprintf(kind_slot, sizeof(kind_slot), "__if_kind_%lld", (long long)field_index);
        bool kind_found = false;
        Item kind_item = js_map_shape_lookup(callee.map, kind_slot, kind_slot_len, &kind_found);
        if (kind_found && get_type_id(kind_item) == LMD_TYPE_INT && it2i(kind_item) == 1) {
            brand_only = true;
        }

        char val_slot[32];
        int val_slot_len = snprintf(val_slot, sizeof(val_slot), "__if_val_%lld", (long long)field_index);
        bool val_found = false;
        Item field_val = js_map_shape_lookup(callee.map, val_slot, val_slot_len, &val_found);
        JS_RETURN_IF_ERROR(js_init_class_instance_field(
            callee, object, field_key, val_found, field_val, brand_only));
    }
    return js_status_ok();
}

static bool js_deferred_instance_field_class_contains(Item callee) {
    // Deferral is owned by one class capability. Treating its ancestors as
    // deferred skipped parent fields during super(), even though only the
    // derived class evaluates its fields at the post-super point (D6.2.2v2).
    return js_deferred_instance_field_class.item == callee.item;
}

extern "C" Item js_init_class_instance_fields(Item callee, Item object) {
    if (js_deferred_instance_field_class_contains(callee)) {
        // A compiler-known default-derived construct emits every default
        // class's source initializers after runtime super-dispatch. Metadata
        // cannot reproduce expression values or private-field timing.
        return js_status_ok();
    }
    bool saved_private_init = js_private_field_initializing;
    js_private_field_initializing = true;
    // Each [[Construct]] initializes only its own class fields; its parent
    // already did so while executing super(). Rewalking parents duplicates
    // private brands when a derived class is constructed dynamically.
    Item result = js_init_class_instance_fields_inner(callee, object);
    js_private_field_initializing = saved_private_init;
    return result;
}

extern "C" Item js_init_class_instance_fields_after_super(Item callee,
        Item object) {
    // The derived constructor owns this exact post-super point. It must bypass
    // only its own deferred marker; parent construction remains responsible for
    // parent fields, preserving the D6.2.2v2 construct capability boundary.
    bool saved_private_init = js_private_field_initializing;
    js_private_field_initializing = true;
    Item result = js_init_class_instance_fields_inner(callee, object);
    js_private_field_initializing = saved_private_init;
    return result;
}

extern "C" Item js_private_brand_add(Item object, Item private_key, Item callee) {
    if (!js_can_host_private_slots(object)) return js_status_ok();
    if (get_type_id(private_key) != LMD_TYPE_STRING ||
        !property_key_requires_identity(it2s(private_key)) ||
        property_key_kind(it2s(private_key)) != NAME_KEY_PRIVATE) return js_status_ok();
    if (object.item == callee.item) {
        // Static private members are found as own slots on the constructor;
        // giving it the instance brand would expose prototype-private methods.
        return js_status_ok();
    }
    if (js_private_brand_storage_has_own(object, callee)) {
        if (!js_private_storage_has_own(object, private_key)) {
            // Instance methods have no own member slot; seeing their class
            // brand again means construction is trying to initialize them twice.
            return js_throw_type_error("Cannot initialize private member twice on the same object");
        }
        return js_status_ok();
    }
    Item brand_key_item = js_private_brand_key_for_class(callee);
    if (brand_key_item.item == ItemNull.item) return js_status_ok();
    // Brand installation is the declaration step for a class-owned identity
    // key; ordinary private writes must remain subject to the brand check.
    bool saved_define = js_private_define_active;
    js_private_define_active = true;
    Item set_result = js_set_key_default(object, brand_key_item, callee);
    js_private_define_active = saved_define;
    if (item_is_error(set_result)) return set_result;
    return js_status_ok();
}

// Define (add) a private field's value on the instance, bypassing the brand
// check for THIS write only (ES PrivateFieldAdd at the field's definition).
extern "C" Item js_private_field_define(Item object, Item private_key, Item value) {
    if (js_private_storage_has_own(object, private_key)) {
        // PrivateFieldAdd is distinct from assignment: an existing private
        // slot means this receiver was already initialized by the class.
        return js_throw_type_error("Cannot initialize private member twice on the same object");
    }
    bool saved = js_private_define_active;
    js_private_define_active = true;
    Item set_result = js_set_key_default(object, private_key, value);
    js_private_define_active = saved;
    if (item_is_error(set_result)) return set_result;
    return value;
}

enum JsIntrinsicConstructPolicy {
    JS_INTRINSIC_CONSTRUCT_OBJECT = 1,
    JS_INTRINSIC_CONSTRUCT_ARRAY,
    JS_INTRINSIC_CONSTRUCT_FUNCTION,
    JS_INTRINSIC_CONSTRUCT_STRING,
    JS_INTRINSIC_CONSTRUCT_NUMBER,
    JS_INTRINSIC_CONSTRUCT_BOOLEAN,
    JS_INTRINSIC_CONSTRUCT_ERROR,
    JS_INTRINSIC_CONSTRUCT_TYPE_ERROR,
    JS_INTRINSIC_CONSTRUCT_RANGE_ERROR,
    JS_INTRINSIC_CONSTRUCT_REFERENCE_ERROR,
    JS_INTRINSIC_CONSTRUCT_SYNTAX_ERROR,
    JS_INTRINSIC_CONSTRUCT_URI_ERROR,
    JS_INTRINSIC_CONSTRUCT_EVAL_ERROR,
    JS_INTRINSIC_CONSTRUCT_AGGREGATE_ERROR,
    JS_INTRINSIC_CONSTRUCT_REGEXP,
    JS_INTRINSIC_CONSTRUCT_DATE,
    JS_INTRINSIC_CONSTRUCT_PROMISE,
    JS_INTRINSIC_CONSTRUCT_MAP,
    JS_INTRINSIC_CONSTRUCT_SET,
    JS_INTRINSIC_CONSTRUCT_WEAKMAP,
    JS_INTRINSIC_CONSTRUCT_WEAKSET,
    JS_INTRINSIC_CONSTRUCT_WEAKREF,
    JS_INTRINSIC_CONSTRUCT_FINALIZATION_REGISTRY,
    JS_INTRINSIC_CONSTRUCT_ARRAY_BUFFER,
    JS_INTRINSIC_CONSTRUCT_SHARED_ARRAY_BUFFER,
    JS_INTRINSIC_CONSTRUCT_DATA_VIEW,
    JS_INTRINSIC_CONSTRUCT_INT8_ARRAY,
    JS_INTRINSIC_CONSTRUCT_UINT8_ARRAY,
    JS_INTRINSIC_CONSTRUCT_UINT8_CLAMPED_ARRAY,
    JS_INTRINSIC_CONSTRUCT_INT16_ARRAY,
    JS_INTRINSIC_CONSTRUCT_UINT16_ARRAY,
    JS_INTRINSIC_CONSTRUCT_INT32_ARRAY,
    JS_INTRINSIC_CONSTRUCT_UINT32_ARRAY,
    JS_INTRINSIC_CONSTRUCT_FLOAT16_ARRAY,
    JS_INTRINSIC_CONSTRUCT_FLOAT32_ARRAY,
    JS_INTRINSIC_CONSTRUCT_FLOAT64_ARRAY,
    JS_INTRINSIC_CONSTRUCT_BIGINT64_ARRAY,
    JS_INTRINSIC_CONSTRUCT_BIGUINT64_ARRAY,
    JS_INTRINSIC_CONSTRUCT_PROXY,
};

static bool js_construct_result_is_object(Item value) {
    TypeId type = get_type_id(value);
    return type == LMD_TYPE_MAP || type == LMD_TYPE_FUNC ||
        js_is_js_array(value) || type == LMD_TYPE_ELEMENT ||
        type == LMD_TYPE_OBJECT || type == LMD_TYPE_VMAP;
}

static int js_intrinsic_construct_typed_array_type(
        JsIntrinsicConstructPolicy policy) {
    switch (policy) {
    case JS_INTRINSIC_CONSTRUCT_INT8_ARRAY: return JS_TYPED_INT8;
    case JS_INTRINSIC_CONSTRUCT_UINT8_ARRAY: return JS_TYPED_UINT8;
    case JS_INTRINSIC_CONSTRUCT_UINT8_CLAMPED_ARRAY: return JS_TYPED_UINT8_CLAMPED;
    case JS_INTRINSIC_CONSTRUCT_INT16_ARRAY: return JS_TYPED_INT16;
    case JS_INTRINSIC_CONSTRUCT_UINT16_ARRAY: return JS_TYPED_UINT16;
    case JS_INTRINSIC_CONSTRUCT_INT32_ARRAY: return JS_TYPED_INT32;
    case JS_INTRINSIC_CONSTRUCT_UINT32_ARRAY: return JS_TYPED_UINT32;
    case JS_INTRINSIC_CONSTRUCT_FLOAT16_ARRAY: return JS_TYPED_FLOAT16;
    case JS_INTRINSIC_CONSTRUCT_FLOAT32_ARRAY: return JS_TYPED_FLOAT32;
    case JS_INTRINSIC_CONSTRUCT_FLOAT64_ARRAY: return JS_TYPED_FLOAT64;
    case JS_INTRINSIC_CONSTRUCT_BIGINT64_ARRAY: return JS_TYPED_BIGINT64;
    case JS_INTRINSIC_CONSTRUCT_BIGUINT64_ARRAY: return JS_TYPED_BIGUINT64;
    default: return -1;
    }
}

static int js_intrinsic_construct_default_class(
        JsIntrinsicConstructPolicy policy) {
    switch (policy) {
    case JS_INTRINSIC_CONSTRUCT_OBJECT: return JS_CLASS_OBJECT;
    case JS_INTRINSIC_CONSTRUCT_ARRAY: return JS_CLASS_ARRAY;
    case JS_INTRINSIC_CONSTRUCT_FUNCTION: return JS_CLASS_FUNCTION;
    case JS_INTRINSIC_CONSTRUCT_STRING: return JS_CLASS_STRING;
    case JS_INTRINSIC_CONSTRUCT_NUMBER: return JS_CLASS_NUMBER;
    case JS_INTRINSIC_CONSTRUCT_BOOLEAN: return JS_CLASS_BOOLEAN;
    case JS_INTRINSIC_CONSTRUCT_ERROR: return JS_CLASS_ERROR;
    case JS_INTRINSIC_CONSTRUCT_TYPE_ERROR: return JS_CLASS_TYPE_ERROR;
    case JS_INTRINSIC_CONSTRUCT_RANGE_ERROR: return JS_CLASS_RANGE_ERROR;
    case JS_INTRINSIC_CONSTRUCT_REFERENCE_ERROR: return JS_CLASS_REFERENCE_ERROR;
    case JS_INTRINSIC_CONSTRUCT_SYNTAX_ERROR: return JS_CLASS_SYNTAX_ERROR;
    case JS_INTRINSIC_CONSTRUCT_URI_ERROR: return JS_CLASS_URI_ERROR;
    case JS_INTRINSIC_CONSTRUCT_EVAL_ERROR: return JS_CLASS_EVAL_ERROR;
    case JS_INTRINSIC_CONSTRUCT_AGGREGATE_ERROR: return JS_CLASS_AGGREGATE_ERROR;
    case JS_INTRINSIC_CONSTRUCT_REGEXP: return JS_CLASS_REGEXP;
    case JS_INTRINSIC_CONSTRUCT_DATE: return JS_CLASS_DATE;
    case JS_INTRINSIC_CONSTRUCT_PROMISE: return JS_CLASS_PROMISE;
    case JS_INTRINSIC_CONSTRUCT_MAP: return JS_CLASS_MAP;
    case JS_INTRINSIC_CONSTRUCT_SET: return JS_CLASS_SET;
    case JS_INTRINSIC_CONSTRUCT_WEAKMAP: return JS_CLASS_WEAK_MAP;
    case JS_INTRINSIC_CONSTRUCT_WEAKSET: return JS_CLASS_WEAK_SET;
    case JS_INTRINSIC_CONSTRUCT_WEAKREF: return JS_CLASS_WEAK_REF;
    case JS_INTRINSIC_CONSTRUCT_FINALIZATION_REGISTRY:
        return JS_CLASS_FINALIZATION_REGISTRY;
    case JS_INTRINSIC_CONSTRUCT_ARRAY_BUFFER: return JS_CLASS_ARRAY_BUFFER;
    case JS_INTRINSIC_CONSTRUCT_SHARED_ARRAY_BUFFER:
        return JS_CLASS_SHARED_ARRAY_BUFFER;
    case JS_INTRINSIC_CONSTRUCT_DATA_VIEW: return JS_CLASS_DATA_VIEW;
    default:
        return js_intrinsic_construct_typed_array_type(policy) >= 0
            ? JS_CLASS_TYPED_ARRAY : JS_CLASS_OBJECT;
    }
}

extern "C" Item js_get_prototype_from_constructor_default(Item new_target,
        int default_class, int typed_array_type) {
    RootFrame roots(2);
    Rooted<Item> target_root(roots, new_target);
    Rooted<Item> prototype_root(roots, ItemNull);
    NameId prototype_name_id = js_runtime_state.well_known.prototype;
    JsPropertyDescriptor descriptor = {};
    bool own_data_prototype = get_type_id(target_root.get()) == LMD_TYPE_FUNC &&
        prototype_name_id != NAME_ID_NONE &&
        js_get_own_property_descriptor_name_id(target_root.get(),
            prototype_name_id, &descriptor) &&
        !js_pd_is_accessor(&descriptor);
    if (own_data_prototype) {
        // Canonical constructors keep `prototype` in a real data slot. The
        // old path re-interned its name and entered generic Get for every
        // allocation; reading the exact NameId slot preserves replacement
        // semantics without charging that unrelated lookup machinery to each
        // explicit [[Construct]] (D6.2.2v2).
        prototype_root.set((descriptor.flags & JS_PD_HAS_VALUE)
            ? descriptor.value : make_js_undefined());
    } else {
        NameRef prototype_name = name_pool_resolve_id(
            context ? context->name_pool : NULL, prototype_name_id);
        Item prototype_key = prototype_name
            ? (Item){.item = s2it(prototype_name)}
            : (Item){.item = s2it(heap_create_name("prototype", 9))};
        prototype_root.set(js_get_key_default(target_root.get(), prototype_key));
    }
    if (item_is_error(prototype_root.get())) return prototype_root.get();
    if (!js_construct_result_is_object(prototype_root.get())) {
        prototype_root.set(typed_array_type >= 0
            ? js_get_typed_array_per_type_proto(typed_array_type)
            : js_get_intrinsic_prototype_for_class(default_class));
    }
    return prototype_root.get();
}

static Item js_get_prototype_from_constructor(Item new_target,
        JsIntrinsicConstructPolicy policy) {
    return js_get_prototype_from_constructor_default(new_target,
        js_intrinsic_construct_default_class(policy),
        js_intrinsic_construct_typed_array_type(policy));
}

static Item js_apply_constructed_default_prototype(Item result,
        Item new_target, int default_class) {
    if (!js_construct_result_is_object(result)) return result;
    RootFrame roots(3);
    Rooted<Item> result_root(roots, result);
    Rooted<Item> target_root(roots, new_target);
    Rooted<Item> prototype_root(roots,
        js_get_prototype_from_constructor_default(target_root.get(),
            default_class, -1));
    if (item_is_error(prototype_root.get())) return prototype_root.get();
    if (js_construct_result_is_object(prototype_root.get())) {
        js_set_prototype(result_root.get(), prototype_root.get());
    }
    return result_root.get();
}

static Item js_apply_constructed_intrinsic_prototype(Item result,
        Item new_target, JsIntrinsicConstructPolicy policy) {
    if (!js_construct_result_is_object(result)) return result;
    RootFrame roots(4);
    Rooted<Item> result_root(roots, result);
    Rooted<Item> target_root(roots, new_target);
    Rooted<Item> prototype_root(roots,
        js_get_prototype_from_constructor(target_root.get(), policy));
    Rooted<Item> metadata_key_root(roots, ItemNull);
    if (item_is_error(prototype_root.get())) return prototype_root.get();
    // GetPrototypeFromConstructor is observable even for the canonical
    // intrinsic: skipping it made a replaced `.prototype` affect classes but
    // not direct `new` calls (D6.2.2v2).
    if (js_construct_result_is_object(prototype_root.get())) {
        js_set_prototype(result_root.get(), prototype_root.get());
    }
    if (policy == JS_INTRINSIC_CONSTRUCT_PROMISE) {
        // D6.2.2v2: Promise's wrapper factory publishes an own constructor
        // cache, so forwarded newTarget must replace the base-realm value.
        metadata_key_root.set((Item){.item = s2it(heap_create_name(
            "constructor", 11))});
        JS_RETURN_IF_ERROR(js_set_key_default(result_root.get(),
            metadata_key_root.get(), target_root.get()));
        js_mark_non_enumerable(result_root.get(), metadata_key_root.get());
    }
    return result_root.get();
}

static const char* js_intrinsic_error_name(JsIntrinsicConstructPolicy policy,
        int* length) {
    const char* name = "Error";
    switch (policy) {
    case JS_INTRINSIC_CONSTRUCT_TYPE_ERROR: name = "TypeError"; break;
    case JS_INTRINSIC_CONSTRUCT_RANGE_ERROR: name = "RangeError"; break;
    case JS_INTRINSIC_CONSTRUCT_REFERENCE_ERROR: name = "ReferenceError"; break;
    case JS_INTRINSIC_CONSTRUCT_SYNTAX_ERROR: name = "SyntaxError"; break;
    case JS_INTRINSIC_CONSTRUCT_URI_ERROR: name = "URIError"; break;
    case JS_INTRINSIC_CONSTRUCT_EVAL_ERROR: name = "EvalError"; break;
    default: break;
    }
    *length = (int)strlen(name);
    return name;
}

static Item js_intrinsic_error_allocate(JsIntrinsicConstructPolicy policy,
        Item* args, int argc) {
    if (policy == JS_INTRINSIC_CONSTRUCT_AGGREGATE_ERROR) {
        // A missing required `errors` argument is undefined, not an empty
        // iterable. Synthesizing [] bypassed AggregateError's mandatory
        // GetIterator TypeError and changed observable constructor behavior.
        Item errors = argc > 0 && args ? args[0] : make_js_undefined();
        Item message = argc > 1 && args ? args[1] : make_js_undefined();
        Item result = js_new_aggregate_error(errors, message);
        if (argc > 2 && args) JS_RETURN_IF_ERROR(js_error_set_cause(result, args[2]));
        return result;
    }
    int name_length = 0;
    const char* name = js_intrinsic_error_name(policy, &name_length);
    Item name_item = (Item){.item = s2it(heap_create_name(name, name_length))};
    Item message = argc > 0 && args ? args[0] : make_js_undefined();
    Item result = js_new_error_with_name(name_item, message);
    if (argc > 1 && args) JS_RETURN_IF_ERROR(js_error_set_cause(result, args[1]));
    return result;
}

static Item js_intrinsic_construct_allocate(JsIntrinsicConstructPolicy policy,
        Item callee, Item* args, int argc) {
    Item first = argc > 0 && args ? args[0] : make_js_undefined();
    Item second = argc > 1 && args ? args[1] : make_js_undefined();
    Item third = argc > 2 && args ? args[2] : make_js_undefined();
    int typed_array_type = js_intrinsic_construct_typed_array_type(policy);
    if (typed_array_type >= 0) {
        return js_typed_array_construct(typed_array_type, first, second, third,
            argc);
    }
    switch (policy) {
    case JS_INTRINSIC_CONSTRUCT_OBJECT:
        return argc > 0 && get_type_id(first) != LMD_TYPE_NULL &&
            get_type_id(first) != LMD_TYPE_UNDEFINED
            ? js_to_object(first) : js_new_object();
    case JS_INTRINSIC_CONSTRUCT_ARRAY: {
        if (argc == 0) return js_array_new(0);
        if (argc == 1) return js_array_new_from_item(first);
        Item result = js_array_new(0);
        for (int i = 0; i < argc; i++) js_array_push(result, args[i]);
        return result;
    }
    case JS_INTRINSIC_CONSTRUCT_FUNCTION:
        return js_new_function_from_string(args, argc);
    case JS_INTRINSIC_CONSTRUCT_STRING:
        return js_new_string_wrapper(argc > 0 ? first :
            (Item){.item = s2it(heap_create_name("", 0))});
    case JS_INTRINSIC_CONSTRUCT_NUMBER:
        return js_new_number_checked(argc > 0 ? first : (Item){.item = i2it(0)});
    case JS_INTRINSIC_CONSTRUCT_BOOLEAN:
        return js_new_boolean_wrapper(argc > 0 ? first : (Item){.item = ITEM_FALSE});
    case JS_INTRINSIC_CONSTRUCT_ERROR:
    case JS_INTRINSIC_CONSTRUCT_TYPE_ERROR:
    case JS_INTRINSIC_CONSTRUCT_RANGE_ERROR:
    case JS_INTRINSIC_CONSTRUCT_REFERENCE_ERROR:
    case JS_INTRINSIC_CONSTRUCT_SYNTAX_ERROR:
    case JS_INTRINSIC_CONSTRUCT_URI_ERROR:
    case JS_INTRINSIC_CONSTRUCT_EVAL_ERROR:
    case JS_INTRINSIC_CONSTRUCT_AGGREGATE_ERROR:
        return js_intrinsic_error_allocate(policy, args, argc);
    case JS_INTRINSIC_CONSTRUCT_REGEXP:
        return js_regexp_construct(first, second);
    case JS_INTRINSIC_CONSTRUCT_DATE:
        if (argc == 0) return js_date_new();
        if (argc == 1) return js_date_new_from(first);
        else {
            Item packed = js_array_new(0);
            for (int i = 0; i < argc; i++) js_array_push(packed, args[i]);
            return js_date_new_multi(packed);
        }
    case JS_INTRINSIC_CONSTRUCT_PROMISE:
        return js_promise_create(argc > 0 ? first : ItemNull);
    case JS_INTRINSIC_CONSTRUCT_MAP:
        return argc > 0 ? js_map_collection_new_from(first) :
            js_map_collection_new();
    case JS_INTRINSIC_CONSTRUCT_SET:
        return argc > 0 ? js_set_collection_new_from(first) :
            js_set_collection_new();
    case JS_INTRINSIC_CONSTRUCT_WEAKMAP:
        return js_weakmap_new_with_iter(first);
    case JS_INTRINSIC_CONSTRUCT_WEAKSET:
        return js_weakset_new_with_iter(first);
    case JS_INTRINSIC_CONSTRUCT_WEAKREF:
        return js_weakref_new(first);
    case JS_INTRINSIC_CONSTRUCT_FINALIZATION_REGISTRY:
        return js_finalization_registry_new(first);
    case JS_INTRINSIC_CONSTRUCT_ARRAY_BUFFER:
        return js_arraybuffer_construct_resizable(first, second);
    case JS_INTRINSIC_CONSTRUCT_SHARED_ARRAY_BUFFER:
        return js_sharedarraybuffer_construct_with_options(first, second);
    case JS_INTRINSIC_CONSTRUCT_DATA_VIEW:
        return js_dataview_new(first, second, third);
    case JS_INTRINSIC_CONSTRUCT_PROXY:
        return js_proxy_new(first, second);
    default:
        (void)callee;
        return ItemError;
    }
}

static Item js_intrinsic_construct_with_policy(
        JsIntrinsicConstructPolicy policy, Item callee, Item* args, int argc,
        Item new_target) {
    RootFrame roots(4);
    Rooted<Item> callee_root(roots, callee);
    Rooted<Item> target_root(roots, new_target);
    Rooted<Item> prototype_root(roots, ItemNull);
    Rooted<Item> result_root(roots, ItemNull);
    if (policy == JS_INTRINSIC_CONSTRUCT_PROMISE) {
        Item executor = argc > 0 && args ? args[0] : make_js_undefined();
        // Promise validates IsCallable before OrdinaryCreateFromConstructor;
        // otherwise an exotic newTarget.prototype getter masks the required
        // missing/non-callable executor TypeError.
        if (!js_is_callable(executor)) {
            return js_throw_type_error("Promise resolver is not a function");
        }
    }
    if (js_intrinsic_construct_typed_array_type(policy) >= 0) {
        Item first = argc > 0 && args ? args[0] : make_js_undefined();
        JS_ASSIGN_OR_RETURN(validation,
            js_typed_array_validate_constructor_argument(first, argc));
    }
    if (policy == JS_INTRINSIC_CONSTRUCT_DATA_VIEW) {
        Item first = argc > 0 && args ? args[0] : make_js_undefined();
        Item second = argc > 1 && args ? args[1] : make_js_undefined();
        Item third = argc > 2 && args ? args[2] : make_js_undefined();
        return js_dataview_construct(first, second, third,
            target_root.get());
    }
    if (policy == JS_INTRINSIC_CONSTRUCT_ARRAY_BUFFER ||
            policy == JS_INTRINSIC_CONSTRUCT_SHARED_ARRAY_BUFFER) {
        Item first = argc > 0 && args ? args[0] : make_js_undefined();
        Item second = argc > 1 && args ? args[1] : make_js_undefined();
        return policy == JS_INTRINSIC_CONSTRUCT_ARRAY_BUFFER
            ? js_arraybuffer_construct_resizable_target(
                first, second, target_root.get())
            : js_sharedarraybuffer_construct_with_options_target(
                first, second, target_root.get());
    }
    if (policy == JS_INTRINSIC_CONSTRUCT_OBJECT &&
            target_root.get().item == callee_root.get().item) {
        // D6.2.2v2: canonical Object construction has the call behavior and
        // returns an existing object or its type-specific wrapper unchanged;
        // applying Object.prototype afterwards destroyed both identity and
        // the wrapper's Number/String/Boolean prototype.
        return js_intrinsic_construct_allocate(policy, callee_root.get(),
            args, argc);
    }
    if (policy == JS_INTRINSIC_CONSTRUCT_OBJECT) {
        // A derived Object constructor ignores the value argument and creates
        // from newTarget, rather than wrapping/returning the supplied value.
        prototype_root.set(js_get_prototype_from_constructor(
            target_root.get(), policy));
        if (item_is_error(prototype_root.get())) return prototype_root.get();
        result_root.set(js_new_object());
        if (js_construct_result_is_object(prototype_root.get())) {
            js_set_prototype(result_root.get(), prototype_root.get());
        }
        return result_root.get();
    }
    if (policy != JS_INTRINSIC_CONSTRUCT_PROXY) {
        // GetPrototypeFromConstructor precedes allocation for the intrinsic
        // constructors. Delaying it made invalid ArrayBuffer/DataView lengths
        // throw before an observable newTarget.prototype getter (D6.2.2v2).
        prototype_root.set(js_get_prototype_from_constructor(
            target_root.get(), policy));
        if (item_is_error(prototype_root.get())) return prototype_root.get();
    }
    result_root.set(js_intrinsic_construct_allocate(
        policy, callee_root.get(), args, argc));
    if (item_is_error(result_root.get())) return result_root.get();
    if (policy == JS_INTRINSIC_CONSTRUCT_PROXY) return result_root.get();
    if (js_construct_result_is_object(prototype_root.get())) {
        js_set_prototype(result_root.get(), prototype_root.get());
    }
    if (policy == JS_INTRINSIC_CONSTRUCT_PROMISE) {
        Item constructor_key = (Item){.item = s2it(heap_create_name(
            "constructor", 11))};
        JS_RETURN_IF_ERROR(js_set_key_default(result_root.get(), constructor_key,
            target_root.get()));
        js_mark_non_enumerable(result_root.get(), constructor_key);
    }
    return result_root.get();
}

Item js_intrinsic_ctor_requires_new_call_body(Item callee, Item this_value,
        Item* args, int argc, uint64_t* result_home) {
    (void)callee; (void)this_value; (void)args; (void)argc; (void)result_home;
    return js_throw_type_error("Constructor requires 'new'");
}

Item js_intrinsic_ctor_forbidden_construct_body(Item callee, Item* args,
        int argc, Item new_target, uint64_t* result_home) {
    (void)callee; (void)args; (void)argc; (void)new_target; (void)result_home;
    // Symbol/BigInt remain construct-capable for IsConstructor and `extends`,
    // but their [[Construct]] invariant rejects before argument conversion.
    return js_throw_type_error("Constructor does not support 'new'");
}

