                    int gi = str_key->chars[1] - '1'; // $1 → index 0
                    String* gs = js_regexp_last_match.groups[gi];
                    return gs ? (Item){.item = s2it(gs)} : (Item){.item = s2it(heap_create_name("", 0))};
