    Item arg0 = argc > 0 ? args[0] : make_js_undefined();
    Item arg1 = argc > 1 ? args[1] : make_js_undefined();
    Item first = operation == 4 ? ItemNull : arg0;
    Item second = ItemNull;
    if ((is_map && (operation == 0 || operation == 5)) ||
        (!is_map && operation == 5)) {
        second = arg1;
    }
