                if (js_is_arraybuffer(this_val))
                    return (Item){.item = s2it(heap_create_name("[object ArrayBuffer]", 20))};
                if (js_is_dataview(this_val))
                    return (Item){.item = s2it(heap_create_name("[object DataView]", 17))};
