#undef JS_MATH_INTRINSIC_BODY

// array slice from index to end — used for rest destructuring
extern "C" Item js_array_slice_from(Item arr, Item start_item) {
    TypeId tid = get_type_id(arr);
    if (tid != LMD_TYPE_ARRAY) return js_array_new(0);
    Array* src = arr.array;
    int start = (int)js_get_number(start_item);
    if (start < 0) start = src->length + start;
    if (start < 0) start = 0;
    if (start >= src->length) return js_array_new(0);
    Item result = js_array_new(0);
    Array* dst = result.array;
    for (int i = start; i < src->length; i++) {
        js_array_push_item_direct(dst, src->items[i]);
    }
    return result;
}

// =============================================================================
// Prototype chain support
// =============================================================================

static const char PROTO_KEY[] = "__proto__";
static const int PROTO_KEY_LEN = 9;
extern "C" const char JS_INTERNAL_PROTO_KEY[] = "__internal_proto__";
extern "C" const int JS_INTERNAL_PROTO_KEY_LEN = 18;

enum {
    JS_PROTO_CACHE_INTERNAL = 1u << 0,
    JS_PROTO_CACHE_PUBLIC = 1u << 1,
    JS_PROTO_CACHE_JSON_OWN = 1u << 2,
};

typedef struct JsProtoEntryCache {
    ShapeEntry* internal_proto;
    ShapeEntry* public_proto;
    ShapeEntry* json_own_proto;
    uint8_t mask;
} JsProtoEntryCache;

static ShapeEntry* js_proto_shape_entry(TypeMap* tm, const char* name,
        int name_len, uint8_t cache_bit) {
    if (!tm || !name) return NULL;
    if (!typemap_is_shared_shape(tm)) {
        return typemap_hash_lookup(tm, name, name_len);
    }
    JsProtoEntryCache* cache = tm->js_proto_entry_cache;
    if (!cache) {
        if (!js_input || !js_input->pool) {
            return typemap_hash_lookup(tm, name, name_len);
        }
        cache = (JsProtoEntryCache*)pool_calloc(
            js_input->pool, sizeof(JsProtoEntryCache));
        if (!cache) return typemap_hash_lookup(tm, name, name_len);
        tm->js_proto_entry_cache = cache;
    }
    ShapeEntry** cache_slot = cache_bit == JS_PROTO_CACHE_INTERNAL
        ? &cache->internal_proto
        : (cache_bit == JS_PROTO_CACHE_PUBLIC
            ? &cache->public_proto : &cache->json_own_proto);
    if (cache->mask & cache_bit) return *cache_slot;
    // Shared constructor/transition shapes detach before structural or
    // descriptor mutation, so both positive and negative entry caches remain
    // valid for the lifetime of this TypeMap.
    *cache_slot = typemap_hash_lookup(tm, name, name_len);
    cache->mask |= cache_bit;
    return *cache_slot;
}

static JsShapeSlotStatus js_proto_shape_slot_status(Map* m, ShapeEntry* se,
        Item* out_slot) {
    if (out_slot) *out_slot = ItemNull;
    if (!m || !se || !m->data || !shape_entry_storage_fits_data(se, m->data_cap)) {
        return JS_SHAPE_SLOT_ABSENT;
    }
    if (map_ctor_offset_is_reserved(m, se->byte_offset)) {
        return JS_SHAPE_SLOT_ABSENT;
    }
    Item slot = _map_read_field(se, m->data);
    if (out_slot) *out_slot = slot;
    if (jspd_is_deleted(se) || js_is_deleted_sentinel(slot)) {
        return JS_SHAPE_SLOT_DELETED;
    }
    return jspd_is_accessor(se) ? JS_SHAPE_SLOT_ACCESSOR : JS_SHAPE_SLOT_DATA;
}

// J39-7: ES B.3.7 PropertyDefinitionEvaluation for `__proto__: expr` in
// object initializers. Spec: if propValue is Object or Null, perform
// [[SetPrototypeOf]]; otherwise NO-OP (do NOT create an own property).
// This must NOT be invoked for computed keys (`["__proto__"]:`) or shorthand
// (`{__proto__}`) — those are regular property definitions.
extern "C" void js_object_proto_setter(Item object, Item value) {
    TypeId vt = get_type_id(value);
    bool is_null = (value.item == ItemNull.item || vt == LMD_TYPE_NULL);
    bool is_obj =
        (vt == LMD_TYPE_MAP || vt == LMD_TYPE_FUNC ||
         vt == LMD_TYPE_ARRAY || vt == LMD_TYPE_ELEMENT);
    if (!is_null && !is_obj) return;
    if (is_null) {
        // Match Object.create(null): write ITEM_JS_UNDEFINED sentinel so
        // `js_get_prototype_of` distinguishes "explicit null proto" from
        // "no __proto__ slot set".
        TypeId ot = get_type_id(object);
        if (ot == LMD_TYPE_MAP) {
            Item key = (Item){.item = s2it(heap_create_name("__proto__", 9))};
            Item undef = (Item){.item = ((uint64_t)LMD_TYPE_UNDEFINED << 56)};
            js_define_own_key_storage(object, key, undef);
            // Prototype-link stores must invalidate the clean intrinsic-chain
            // guard at the commit point; callers may bypass Object/Reflect.
            js_intrinsic_note_prototype_mutation(object);
            return;
        }
    }
    js_set_prototype(object, value);
}

// Set the prototype of an object (stores as __proto__ property on Map)
extern "C" void js_set_prototype(Item object, Item prototype) {
    if (get_type_id(object) == LMD_TYPE_MAP && get_type_id(prototype) == LMD_TYPE_MAP) {
    }
    // Proxy [[SetPrototypeOf]] trap
    if (js_is_proxy(object)) {
        js_proxy_trap_set_prototype_of(object, prototype);
        return;
    }
    TypeId ot = get_type_id(object);
    // Encode explicit-null prototype as ITEM_JS_UNDEFINED sentinel for storage.
    Item proto_to_store = (prototype.item == ItemNull.item)
        ? (Item){.item = ITEM_JS_UNDEFINED}
        : prototype;
    // Functions keep [[Prototype]] in their side map, but under an internal
    // key. Using the public `__proto__` spelling made prototype walks mistake
    // the internal link for an own data property and shadow Object.prototype's
    // inherited accessor.
    if (ot == LMD_TYPE_FUNC) {
        if (get_type_id(prototype) != LMD_TYPE_MAP && get_type_id(prototype) != LMD_TYPE_FUNC &&
            prototype.item != ItemNull.item) return;
        JsFunction* fn = (JsFunction*)object.function;
        if (fn->properties_map.item == 0) {
            fn->properties_map = js_new_object();
            js_function_root_item_if_needed(fn, &fn->properties_map);
        }
        Item key = (Item){.item = s2it(heap_create_name(
            JS_INTERNAL_PROTO_KEY, JS_INTERNAL_PROTO_KEY_LEN))};
        js_define_own_key_storage(fn->properties_map, key, proto_to_store);
        // The function's internal link is the actual [[Prototype]] slot; note
        // it here so direct runtime construction cannot leave a stale guard.
        js_intrinsic_note_prototype_mutation(object);
        return;
    }
    // Handle arrays: store __proto__ in the companion map.
    if (ot == LMD_TYPE_ARRAY || js_is_ordinary_numeric_array(object)) {
        if (!js_array_has_props(object.array)) {
            Item props = js_new_object();
            props.map->map_kind = MAP_KIND_ARRAY_PROPS;
            js_elements_set_props(object.array, props.map);
        }
        Item props = (Item){.map = js_array_props(object.array)};
        Item key = js_get_proto_key();
        js_define_own_key_storage(props, key, proto_to_store);
        // Array prototype writes do not pass through the public property setter.
        js_intrinsic_note_prototype_mutation(object);
        return;
    }
    if (ot != LMD_TYPE_MAP) return;
    TypeId proto_type = get_type_id(prototype);
    // ES spec: prototype must be an object (MAP/FUNC/ARRAY/ELEMENT) or null
    if (proto_type != LMD_TYPE_MAP && proto_type != LMD_TYPE_FUNC &&
        proto_type != LMD_TYPE_ARRAY && proto_type != LMD_TYPE_ELEMENT &&
        prototype.item != ItemNull.item) return;
    // v16: Prevent circular prototype chains (ES spec §9.1.2)
    if (get_type_id(prototype) == LMD_TYPE_MAP) {
        Item p = prototype;
        int depth = 0;
        while (p.item != ItemNull.item && get_type_id(p) == LMD_TYPE_MAP && depth < 32) {
            if (p.map == object.map) {
                log_error("js_set_prototype: circular prototype chain detected, rejecting");
                return;
            }
            p = js_get_prototype(p);
            depth++;
        }
    }
    bool owns_proto_data = false;
    Item owns_proto_data_val = js_map_shape_lookup_ext(object.map, "__json_own_proto__", 18, &owns_proto_data);
    if (owns_proto_data && js_is_truthy(owns_proto_data_val)) {
        js_define_own_key_storage(object, (Item){.item = s2it(heap_create_name(JS_INTERNAL_PROTO_KEY, JS_INTERNAL_PROTO_KEY_LEN))},
            proto_to_store);
        // JSON-own-proto objects use the same internal link and still affect
        // prototype-dependent intrinsic assumptions.
        js_intrinsic_note_prototype_mutation(object);
        return;
    }
    // P10d: use interned __proto__ key.
    Item key = js_get_proto_key();
    js_define_own_key_storage(object, (Item){.item = s2it(heap_create_name("__json_own_proto__", 18))},
        (Item){.item = ITEM_FALSE});
    js_define_own_key_storage(object, key, proto_to_store);
    // Notify only after the validated link has been stored; rejected and
    // cyclic prototype updates leave the intrinsic epoch untouched.
    js_intrinsic_note_prototype_mutation(object);
}

extern "C" void js_mark_own_proto_property(Item object) {
    if (get_type_id(object) != LMD_TYPE_MAP) return;
    Map* m = object.map;
    bool marker_found = false;
    Item marker_val = js_map_shape_lookup_ext(m, "__json_own_proto__", 18, &marker_found);
    Item raw_proto = ItemNull;
    JsShapeSlotStatus proto_status = js_own_shape_slot_status(
        object, PROTO_KEY, PROTO_KEY_LEN, &raw_proto, NULL);
    if ((!marker_found || !js_is_truthy(marker_val)) &&
        (proto_status == JS_SHAPE_SLOT_DATA || proto_status == JS_SHAPE_SLOT_ACCESSOR)) {
        js_define_own_key_storage(object, (Item){.item = s2it(heap_create_name(JS_INTERNAL_PROTO_KEY, JS_INTERNAL_PROTO_KEY_LEN))},
            raw_proto);
    } else if (!marker_found || !js_is_truthy(marker_val)) {
        // plain objects synthesize Object.prototype until an explicit slot exists;
        // preserve that effective prototype before exposing __proto__ as data.
        Item effective_proto = js_get_prototype_of(object);
        js_define_own_key_storage(object, (Item){.item = s2it(heap_create_name(JS_INTERNAL_PROTO_KEY, JS_INTERNAL_PROTO_KEY_LEN))},
            effective_proto.item == ItemNull.item ?
                (Item){.item = ITEM_JS_UNDEFINED} : effective_proto);
    }
    js_define_own_key_storage(object, (Item){.item = s2it(heap_create_name("__json_own_proto__", 18))},
        (Item){.item = ITEM_TRUE});
}

// Check if a function has a custom [[Prototype]] set via Object.setPrototypeOf.
extern "C" Item js_func_get_custom_proto(Item func) {
    if (get_type_id(func) != LMD_TYPE_FUNC) return ItemNull;
    JsFunction* fn = (JsFunction*)func.function;
    if (fn->properties_map.item != 0 && get_type_id(fn->properties_map) == LMD_TYPE_MAP) {
        Item pk = (Item){.item = s2it(heap_create_name(
            JS_INTERNAL_PROTO_KEY, JS_INTERNAL_PROTO_KEY_LEN))};
        String* pks = it2s(pk);
        Item result = ItemNull;
        JsShapeSlotStatus status = js_own_shape_slot_status(
            fn->properties_map, pks->chars, (int)pks->len, &result, NULL);
        if (status == JS_SHAPE_SLOT_DATA || status == JS_SHAPE_SLOT_ACCESSOR) return result;
    }
    return ItemNull;
}

// Check if an array has a custom __proto__ set via Object.setPrototypeOf
extern "C" Item js_elements_get_custom_proto(Item arr) {
    if (get_type_id(arr) != LMD_TYPE_ARRAY &&
            !js_is_ordinary_numeric_array(arr)) return ItemNull;
    if (!js_array_has_props(arr.array)) return ItemNull;
    Map* pm = js_array_props(arr.array);
    Item pk = js_get_proto_key();
    String* pks = it2s(pk);
    Item pm_item = (Item){.map = pm};
    Item result = ItemNull;
    JsShapeSlotStatus status = js_own_shape_slot_status(
        pm_item, pks->chars, (int)pks->len, &result, NULL);
    if (status == JS_SHAPE_SLOT_DATA || status == JS_SHAPE_SLOT_ACCESSOR) return result;
    return ItemNull;
}

// helper: set __proto__ on a wrapper object to the constructor's prototype
static void js_wrapper_set_proto(Item obj, const char* ctor_name, int ctor_len) {
    Item cn = (Item){.item = s2it(heap_create_name(ctor_name, ctor_len))};
    Item ctor = js_get_constructor(cn);
    if (get_type_id(ctor) == LMD_TYPE_FUNC) {
        Item pk = (Item){.item = s2it(heap_create_name("prototype", 9))};
        Item proto = js_get_key_default(ctor, pk);
        if (get_type_id(proto) == LMD_TYPE_MAP) {
            js_set_prototype(obj, proto);
        }
    }
}

// Create a Number wrapper object with [[NumberData]] in __primitiveValue__.
extern "C" Item js_new_number_wrapper(Item arg) {
    // Every step here allocates (class stamp clones the typemap, heap_create_name,
    // js_to_number, js_set_key_default can grow the map, wrapper_set_proto reads the
    // constructor). The half-built wrapper is referenced only by this local, so
    // it must stay exact-rooted or a collection mid-construction frees it.
    RootFrame roots(4);
    Rooted<Item> arg_root(roots, arg);
    Rooted<Item> obj_root(roots, js_new_object());
    Rooted<Item> pv_key_root(roots, (Item){.item = s2it(heap_create_name("__primitiveValue__", 18))});
    Rooted<Item> number_root(roots, js_to_number(arg_root.get()));
    if (item_is_error(number_root.get())) return number_root.get();
    js_class_stamp(obj_root.get(), JS_CLASS_NUMBER);
    js_set_key_default(obj_root.get(), pv_key_root.get(), number_root.get());
    js_wrapper_set_proto(obj_root.get(), "Number", 6);
    return obj_root.get();
}

// ES spec: new Number(arg) — checks symbol before creating wrapper
extern "C" Item js_new_number_checked(Item arg) {
    if (get_type_id(arg) == LMD_TYPE_INT && it2i(arg) <= -(int64_t)JS_SYMBOL_BASE) {
        return js_throw_type_error("Cannot convert a Symbol value to a number");
    }
    // BigInt → Number conversion (ES2020: ToNumeric then BigInt::numberValue)
    if (js_is_bigint_egress(arg)) {
        arg = js_number_function(arg);
    }
    return js_new_number_wrapper(arg);
}

// Create a Boolean wrapper object
extern "C" Item js_new_boolean_wrapper(Item arg) {
    // See js_new_number_wrapper: keep the unfinished wrapper exact-rooted across
    // every allocating construction step.
    RootFrame roots(3);
    Rooted<Item> arg_root(roots, arg);
    Rooted<Item> obj_root(roots, js_new_object());
    Rooted<Item> pv_key_root(roots, (Item){.item = s2it(heap_create_name("__primitiveValue__", 18))});
    js_class_stamp(obj_root.get(), JS_CLASS_BOOLEAN);
    js_set_key_default(obj_root.get(), pv_key_root.get(), js_to_boolean(arg_root.get()));
    js_wrapper_set_proto(obj_root.get(), "Boolean", 7);
    return obj_root.get();
}

// Create a String wrapper object
extern "C" Item js_new_string_wrapper(Item arg) {
    // See js_new_number_wrapper: the wrapper is built across many allocating
    // calls (class stamp, two heap_create_name keys, js_to_string, two
    // js_set_key_default, wrapper_set_proto, three attr marks) while referenced only
    // by these locals — all must stay exact-rooted so a mid-construction
    // collection cannot free the half-built map or the wrapped string.
    RootFrame roots(5);
    Rooted<Item> arg_root(roots, arg);
    Rooted<Item> obj_root(roots, js_new_object());
    Rooted<Item> pv_key_root(roots, (Item){.item = s2it(heap_create_name("__primitiveValue__", 18))});
    Rooted<Item> str_val_root(roots, js_to_string(arg_root.get()));
    if (item_is_error(str_val_root.get())) return str_val_root.get();
    js_class_stamp(obj_root.get(), JS_CLASS_STRING);
    js_set_key_default(obj_root.get(), pv_key_root.get(), str_val_root.get());
    // Also set length property
    String* s = it2s(str_val_root.get());
    int len = s ? (int)js_utf16_len(s->chars, (int)s->len, (bool)s->is_ascii) : 0;
    Rooted<Item> len_key_root(roots, (Item){.item = s2it(heap_create_name("length", 6))});
    Item len_val = (Item){.item = i2it(len)};
    js_set_key_default(obj_root.get(), len_key_root.get(), len_val);
    js_wrapper_set_proto(obj_root.get(), "String", 6);
    js_mark_non_writable(obj_root.get(), len_key_root.get());
    js_mark_non_enumerable(obj_root.get(), len_key_root.get());
    js_mark_non_configurable(obj_root.get(), len_key_root.get());
    return obj_root.get();
}

// ToObject conversion: wraps primitives into their corresponding wrapper objects
// ES spec 7.1.13 ToObject
extern "C" Item js_to_object(Item value) {
    TypeId type = get_type_id(value);
    if (type == LMD_TYPE_MAP || type == LMD_TYPE_ARRAY ||
        js_is_ordinary_numeric_array(value) ||
        type == LMD_TYPE_FUNC || type == LMD_TYPE_ELEMENT ||
        type == LMD_TYPE_OBJECT || type == LMD_TYPE_VMAP) return value;
    if (type == LMD_TYPE_BOOL) return js_new_boolean_wrapper(value);
    // Symbol wrapper must be checked before number (symbols are encoded as negative ints)
    if (type == LMD_TYPE_INT && it2i(value) <= -(int64_t)JS_SYMBOL_BASE) {
        // exact-root the half-built wrapper across the allocating steps (see
        // js_new_number_wrapper) — an unrooted obj is freed by a mid-build GC.
        RootFrame roots(3);
        Rooted<Item> value_root(roots, value);
        Rooted<Item> obj_root(roots, js_new_object());
        Rooted<Item> pv_key_root(roots, (Item){.item = s2it(heap_create_name("__primitiveValue__", 18))});
        js_class_stamp(obj_root.get(), JS_CLASS_SYMBOL);
        js_set_key_default(obj_root.get(), pv_key_root.get(), value_root.get());
        js_wrapper_set_proto(obj_root.get(), "Symbol", 6);
        return obj_root.get();
    }
    if (type == LMD_TYPE_INT || type == LMD_TYPE_FLOAT) return js_new_number_wrapper(value);
    if (type == LMD_TYPE_STRING) return js_new_string_wrapper(value);
    if (js_is_bigint_egress(value)) {
        // BigInt wrapper object with __primitiveValue__; exact-root as above.
        RootFrame roots(4);
        Rooted<Item> value_root(roots, value);
        Rooted<Item> obj_root(roots, js_new_object());
        Rooted<Item> pv_key_root(roots, (Item){.item = s2it(heap_create_name("__primitiveValue__", 18))});
        js_class_stamp(obj_root.get(), JS_CLASS_BIGINT);
        // native int64/uint64 egress as BigInt, but wrapper methods require the
        // canonical mpdec-unlimited representation in [[BigIntData]].
        Rooted<Item> pv_root(roots, js_is_native_bigint_egress(value_root.get())
            ? js_native_bigint_to_bigint(value_root.get()) : value_root.get());
        js_set_key_default(obj_root.get(), pv_key_root.get(), pv_root.get());
        js_wrapper_set_proto(obj_root.get(), "BigInt", 6);
        return obj_root.get();
    }
    // null and undefined throw TypeError in spec, but return empty object here for safety
    return js_new_object();
}

// Mark a property as non-enumerable through ShapeEntry flags.
extern "C" void js_mark_non_enumerable(Item object, Item name) {
    TypeId tid = get_type_id(object);
    if (tid != LMD_TYPE_MAP && tid != LMD_TYPE_FUNC && tid != LMD_TYPE_ARRAY) return;
    if (get_type_id(name) != LMD_TYPE_STRING) return;
    String* str = it2s(name);
    if (property_key_requires_identity(str)) {
        js_shape_entry_update_flags_name_id(object, property_key_id(str),
            JSPD_NON_ENUMERABLE, 0);
    } else {
        js_attr_set_enumerable(object, str->chars, (int)str->len, /*enumerable=*/false);
    }
}

// Mark a property as non-writable through ShapeEntry flags.
extern "C" void js_mark_non_writable(Item object, Item name) {
    TypeId tid = get_type_id(object);
    if (tid != LMD_TYPE_MAP && tid != LMD_TYPE_FUNC && tid != LMD_TYPE_ARRAY) return;
    if (get_type_id(name) != LMD_TYPE_STRING) return;
    String* str = it2s(name);
    if (property_key_requires_identity(str)) {
        js_shape_entry_update_flags_name_id(object, property_key_id(str),
            JSPD_NON_WRITABLE, 0);
    } else {
        js_attr_set_writable(object, str->chars, (int)str->len, /*writable=*/false);
    }
}

extern "C" void js_mark_private_method_non_writable(Item object, Item name) {
    if (get_type_id(name) != LMD_TYPE_STRING) return;
    String* str = it2s(name);
    if (!str || !property_key_requires_identity(str) ||
        property_key_kind(str) != NAME_KEY_PRIVATE) return;
    js_mark_non_writable(object, name);
}

// Mark a property as non-configurable through ShapeEntry flags.
extern "C" void js_mark_non_configurable(Item object, Item name) {
    TypeId tid = get_type_id(object);
    if (tid != LMD_TYPE_MAP && tid != LMD_TYPE_FUNC && tid != LMD_TYPE_ARRAY) return;
    if (get_type_id(name) != LMD_TYPE_STRING) return;
    String* str = it2s(name);
    if (property_key_requires_identity(str)) {
        js_shape_entry_update_flags_name_id(object, property_key_id(str),
            JSPD_NON_CONFIGURABLE, 0);
    } else {
        js_attr_set_configurable(object, str->chars, (int)str->len, /*configurable=*/false);
    }
}

// Mark all user-visible properties on an object as non-enumerable (used for class prototypes)
extern "C" void js_mark_all_non_enumerable(Item object) {
    if (get_type_id(object) != LMD_TYPE_MAP) return;
    Map* m = object.map;
    if (!m || !m->type) return;
    TypeMap* tm = (TypeMap*)m->type;
    ShapeEntry* entry = tm->shape;
    while (entry) {
        if (!entry->name) { entry = entry->next; continue; }
        const char* name = entry->name->str;
        int name_len = (int)entry->name->length;
        if (entry->key_kind != NAME_KEY_STRING) {
            js_shape_entry_update_flags_name_id(object, entry->name_id,
                JSPD_NON_ENUMERABLE, 0);
            entry = entry->next;
            continue;
        }
        // skip internal properties
        if (name_len >= 2 && name[0] == '_' && name[1] == '_') {
            entry = entry->next;
            continue;
        }
        js_attr_set_enumerable(object, name, name_len, /*enumerable=*/false);
        entry = entry->next;
    }
}

// v12: Link a proto marker to the base constructor's .prototype object
// so that inherited properties (e.g. Error.stack) are accessible through __proto__ chain.
// proto_marker is the __proto__ node created for instanceof resolution.
// base_ctor is the runtime value of the base constructor function.
extern "C" void js_link_base_prototype(Item proto_marker, Item base_ctor) {
    if (get_type_id(proto_marker) != LMD_TYPE_MAP) return;
    // Look up base_ctor.prototype
    Item proto_key = (Item){.item = s2it(heap_create_name("prototype", 9))};
    Item base_proto = js_get_key_default(base_ctor, proto_key);
    if (base_proto.item != ItemNull.item && get_type_id(base_proto) == LMD_TYPE_MAP) {
        js_set_prototype(proto_marker, base_proto);
    }
}

// Get the prototype of an object (read __proto__ property)
// P10d: uses interned key + first-match lookup (no heap allocation per call)
extern "C" Item js_get_prototype(Item object) {
    if (get_type_id(object) == LMD_TYPE_ERROR || js_is_resting_error(object)) {
        // LambdaError stores ordinary properties in a side map. A custom
        // NewTarget prototype must win over the intrinsic class fallback;
        // reading only the carrier Map would otherwise discard it.
        Item properties = js_error_properties_map(object, false);
        if (get_type_id(properties) == LMD_TYPE_MAP) {
            Item raw = ItemNull;
            JsShapeSlotStatus status = js_own_shape_slot_status(
                properties, "__proto__", 9, &raw, NULL);
            if (status == JS_SHAPE_SLOT_DATA || status == JS_SHAPE_SLOT_ACCESSOR) {
                return raw.item == ITEM_JS_UNDEFINED ? ItemNull : raw;
            }
        }
        return js_get_intrinsic_prototype_for_class(js_error_class_id(object));
    }
    if (get_type_id(object) == LMD_TYPE_VMAP) {
        Item host_proto = ItemNull;
        if (js_host_object_prototype(object, &host_proto)) {
            if (get_type_id(host_proto) == LMD_TYPE_MAP) return host_proto;
            return ItemNull;
        }
    }
    if (get_type_id(object) != LMD_TYPE_MAP) return ItemNull;
    Map* m = object.map;
    // Synthetic fast iterators use a 1-byte sentinel as `type`, not a real
    // TypeMap — never walk their (non-existent) shape for a __proto__ slot.
    if (m && m->map_kind == MAP_KIND_ITERATOR) return ItemNull;
    bool own_proto_marker = false;
    Item own_proto_value = js_map_shape_lookup_ext(
        m, "__json_own_proto__", 18, &own_proto_marker);
    if (own_proto_marker && js_is_truthy(own_proto_value)) {
        // defining a public __proto__ can transition the shape after a negative
        // cache entry was recorded; read the preserved internal slot directly.
        Item internal_proto = ItemNull;
        JsShapeSlotStatus internal_status = js_own_shape_slot_status(
            object, JS_INTERNAL_PROTO_KEY, JS_INTERNAL_PROTO_KEY_LEN, &internal_proto, NULL);
        return (internal_status == JS_SHAPE_SLOT_DATA ||
                internal_status == JS_SHAPE_SLOT_ACCESSOR) ? internal_proto : ItemNull;
    }
    // Ordinary map headers publish their TypeMap before this lookup; a
    // plausibility fallback here would turn a corrupted header into a silent
    // prototype miss instead of exposing the invariant violation.
    TypeMap* tm = m ? (TypeMap*)m->type : NULL;
#ifndef NDEBUG
    assert(!tm || typemap_ptr_is_plausible(tm));
#endif
    Item internal_proto = ItemNull;
    ShapeEntry* internal_se = js_proto_shape_entry(tm,
        JS_INTERNAL_PROTO_KEY, JS_INTERNAL_PROTO_KEY_LEN, JS_PROTO_CACHE_INTERNAL);
    JsShapeSlotStatus internal_status = js_proto_shape_slot_status(
        m, internal_se, &internal_proto);
    if (internal_status == JS_SHAPE_SLOT_DATA || internal_status == JS_SHAPE_SLOT_ACCESSOR)
        return internal_proto;
    ShapeEntry* json_own_se = js_proto_shape_entry(tm,
        "__json_own_proto__", 18, JS_PROTO_CACHE_JSON_OWN);
    Item json_own_proto_val = ItemNull;
    JsShapeSlotStatus json_own_status = js_proto_shape_slot_status(
        m, json_own_se, &json_own_proto_val);
    if ((json_own_status == JS_SHAPE_SLOT_DATA ||
            json_own_status == JS_SHAPE_SLOT_ACCESSOR) &&
            js_is_truthy(json_own_proto_val)) {
        return ItemNull;
    }
    // ES [[GetPrototypeOf]] is an internal slot — independent of any user-
    // defined __proto__ accessor on Object.prototype. If the own __proto__
    // slot has been redefined via Object.defineProperty as an accessor (e.g.
    // `Object.defineProperty(Object.prototype, '__proto__', { set: ... })`),
    // the slot now holds a `JsAccessorPair*` raw pointer; treating it as a
    // prototype Item causes a bus error during chain walks. Detect this and
    // skip — the [[Prototype]] internal slot is conceptually unaffected by
    // the user's accessor redefinition. See test/js_props/proto_accessor_redef_safe.js.
    ShapeEntry* proto_se = js_proto_shape_entry(tm,
        PROTO_KEY, PROTO_KEY_LEN, JS_PROTO_CACHE_PUBLIC);
    if (proto_se && jspd_is_accessor(proto_se)) {
        // Accessor on __proto__ — internal [[Prototype]] is unknown via this
        // slot. For the special case of Object.prototype itself, the parent
        // is null (top of chain). For other objects we can't recover the
        // hidden prototype; returning ItemNull is the safe fallback that
        // preserves [[GetPrototypeOf]] semantics for the proto-walk consumers.
        return ItemNull;
    }
    // P10f+P10d: direct first-match lookup with interned key
    Item proto = ItemNull;
    JsShapeSlotStatus proto_status = js_proto_shape_slot_status(m, proto_se, &proto);
    if (proto_status == JS_SHAPE_SLOT_DELETED) return ItemNull;
    // TypedArray instances don't store __proto__; use per-type prototype
    if (proto.item == ITEM_NULL && m->map_kind == MAP_KIND_TYPED_ARRAY) {
        JsTypedArray* ta = js_get_typed_array_ptr(m);
        if (ta) {
            extern Item js_get_typed_array_per_type_proto(int element_type);
            return js_get_typed_array_per_type_proto((int)ta->element_type);
        }
    }
    return proto;
}

// Resolve the effective prototype of `object` for property-chain walking.
// If `object` has an own `__proto__` slot, return it. Otherwise synthesize the
// implicit prototype from the stamped built-in class byte. This unifies behavior
// with `Object.getPrototypeOf` so that user-added properties on built-in
// prototypes are visible during property lookup.
//
// Returns ItemNull only at the top of the chain (Object.prototype itself, or
// when the explicit `__proto__` slot holds the null sentinel).
static Item js_get_implicit_proto(Item object) {
    TypeId object_type = get_type_id(object);
    if (object_type == LMD_TYPE_VMAP && js_host_object_type(object)) {
        // Host VMaps have no ordinary __proto__ slot; prototype-chain reads
        // must start from the module-supplied host prototype instead of stopping.
        return js_get_prototype(object);
    }
    if (object_type == LMD_TYPE_FUNC) {
        // Callable public properties live in a side map, so the generic map-only
        // chain entry skipped the function's actual [[Prototype]]. Start at the
        // canonical GetPrototypeOf result to expose Function.prototype and its
        // Object.prototype tail exactly once.
        return js_get_prototype_of(object);
    }
    if (object_type != LMD_TYPE_MAP) return ItemNull;
    Map* m = object.map;
    if (m->map_kind == MAP_KIND_ITERATOR) {
        return js_iterator_prototype_for_object(object);
    }
    Item raw = js_get_prototype(object);
    if (raw.item != ItemNull.item) {
        // Object.create(null) sentinel → end of chain
        if (raw.item == ITEM_JS_UNDEFINED) return ItemNull;
        return raw;
    }
    // Class constructor maps are callable objects. They do not carry a public
    // class-name marker, so route their implicit prototype through Function.
    bool own_instance_proto = false;
    js_map_shape_lookup_ext(m, "__instance_proto__", 18, &own_instance_proto);
    if (own_instance_proto) {
        Item func_proto = js_get_intrinsic_prototype_for_class(JS_CLASS_FUNCTION);
        // %Function.prototype% is itself callable, so its runtime carrier is
        // FUNC rather than MAP. Rejecting it here severed every class-map
        // constructor from the Function/Object prototype chain.
        TypeId func_proto_type = get_type_id(func_proto);
        if (func_proto_type != LMD_TYPE_MAP &&
                func_proto_type != LMD_TYPE_FUNC) return ItemNull;
        return func_proto;
    }
    // No own __proto__ slot — synthesize from class identity.
    JsClass jc = js_class_id(object);
    JsClass proto_class = jc != JS_CLASS_NONE ? jc : JS_CLASS_OBJECT;
    Item proto = js_get_intrinsic_prototype_for_class(proto_class);
    if (get_type_id(proto) != LMD_TYPE_MAP) return ItemNull;
    if (proto.map == m) {
        // `object` IS the constructor's prototype object itself.
        // For Object.prototype → top of chain. For Date.prototype, RegExp.prototype,
        // etc. → continue walking to Object.prototype.
        if (proto_class == JS_CLASS_OBJECT) return ItemNull;
        Item op = js_get_intrinsic_prototype_for_class(JS_CLASS_OBJECT);
        if (get_type_id(op) != LMD_TYPE_MAP || op.map == m) return ItemNull;
        return op;
    }
    return proto;
}

// Walk the prototype chain to find a property
// P10f: uses first-match lookup on each prototype level
extern "C" Item js_prototype_lookup_ex_with_receiver(
        Item object, Item property, Item receiver, bool* out_found) {
    if (out_found) *out_found = false;
    RootFrame roots(4);
    Rooted<Item> object_root(roots, object);
    Rooted<Item> property_root(roots, property);
    Rooted<Item> receiver_root(roots, receiver.item == 0 ? object : receiver);
    Rooted<Item> proto_root(roots, ItemNull);
    if (!roots.valid()) return ItemError;
    // Prototype creation, Proxy traps, and accessors can all collect. Keeping
    // only native copies here changed the original Receiver mid-walk (notably
    // class-map `__proto__`) and could retain stale callable/prototype pointers.
    // first check own properties (skip — caller already checked)
    bool string_key = get_type_id(property_root.get()) == LMD_TYPE_STRING;
    // walk up the chain via implicit __proto__
    proto_root.set(js_get_implicit_proto(object_root.get()));
    int depth = 0;
    while (proto_root.get().item != ItemNull.item && depth < 32) {
        Item proto = proto_root.get();
        TypeId pt = get_type_id(proto);
        if (pt == LMD_TYPE_FUNC) {
            JsFunction* proto_fn = (JsFunction*)proto.function;
            if (proto_fn->properties_map.item != 0 && get_type_id(proto_fn->properties_map) == LMD_TYPE_MAP) {
                Item ord_val = ItemNull;
                JsOwnGetStatus st = js_ordinary_get_own(proto_fn->properties_map,
                    property_root.get(), receiver_root.get(), &ord_val);
                if (st == JS_OWN_READY) {
                    if (out_found) *out_found = true;
                    return ord_val;
                }
                // A deleted own slot exposes the next callable prototype.
                // Treating the tombstone as a found undefined value made
                // class constructors lose Object.prototype methods through
                // Function.prototype's side-map shape.
            }
            proto_root.set(js_get_prototype_of(proto_root.get()));
            depth++;
            continue;
        }
        if (pt == LMD_TYPE_ARRAY || pt == LMD_TYPE_ELEMENT) {
            // ES: an Array can be a prototype object (e.g. `Foo.prototype = [1,2,3]`).
            // Delegate property lookup through js_get_key_default on the array.
            Item r = js_get_key_core(
                proto_root.get(), property_root.get(), receiver_root.get());
            if (r.item != ItemNull.item && get_type_id(r) != LMD_TYPE_UNDEFINED) {
                if (out_found) *out_found = true;
                return r;
            }
            proto_root.set(js_get_prototype_of(proto_root.get()));
            depth++;
            continue;
        }
        if (pt != LMD_TYPE_MAP) break;
        // Proxy in prototype chain: forward through proxy [[Get]] trap
        // Pass the original receiver so getter this-binding is correct.
        if (js_is_proxy(proto)) {
            Item result = js_proxy_trap_get(proto_root.get(),
                                            property_root.get(),
                                            receiver_root.get());
            if (out_found) *out_found = true;
            return result;
        }
        Item result = ItemNull;
        JsOwnGetStatus own_get_status = JS_OWN_NOT_FOUND;
        if (string_key) {
            own_get_status = js_ordinary_get_own(proto_root.get(),
                property_root.get(), receiver_root.get(), &result);
        } else {
            result = map_get(proto_root.get().map, property_root.get());
            own_get_status = (result.item != ItemNull.item && !js_is_deleted_sentinel(result)) ?
                JS_OWN_READY : JS_OWN_NOT_FOUND;
        }
        // Stage A1.3b: own-property + IS_ACCESSOR dispatch on this proto
        // level routed through js_ordinary_get_own. Receiver is the original
        // object (or the active proxy_receiver) — NOT the proto.
        if (own_get_status == JS_OWN_READY) {
            if (out_found) *out_found = true;
            return result;
        }

        proto_root.set(js_get_implicit_proto(proto_root.get()));
        depth++;
    }
    return ItemNull;
}

extern "C" Item js_prototype_lookup_ex(Item object, Item property,
                                        bool* out_found) {
    return js_prototype_lookup_ex_with_receiver(object, property, object,
                                                 out_found);
}

extern "C" Item js_prototype_lookup(Item object, Item property) {
    bool _f;
    return js_prototype_lookup_ex_with_receiver(object, property, object, &_f);
}

// =============================================================================
// v12: Object rest destructuring
// =============================================================================

static Item js_object_rest_key_excluded(Item key, Item* exclude_keys, int exclude_count,
        bool* out_excluded) {
    *out_excluded = false;
    JS_ASSIGN_OR_RETURN(prop_key, js_to_property_key(key));
    for (int i = 0; i < exclude_count; i++) {
        JS_ASSIGN_OR_RETURN(exclude_key, js_to_property_key(exclude_keys[i]));
        if (js_key_is_symbol(prop_key) || js_key_is_symbol(exclude_key)) {
            if (prop_key.item == exclude_key.item) *out_excluded = true;
            continue;
        }
        if (get_type_id(prop_key) == LMD_TYPE_STRING && get_type_id(exclude_key) == LMD_TYPE_STRING) {
            String* pk = it2s(prop_key);
            String* ek = it2s(exclude_key);
            if (pk && ek && pk->len == ek->len && memcmp(pk->chars, ek->chars, pk->len) == 0) {
                *out_excluded = true;
            }
        }
    }
    return ItemNull;
}

extern "C" Item js_object_rest(Item src, Item* exclude_keys, int exclude_count) {
    Item rest = js_new_object();

    if (get_type_id(src) == LMD_TYPE_STRING) {
        String* str = it2s(src);
        int slen = str ? (int)str->len : 0;
        for (int i = 0; i < slen; i++) {
            Item key = js_property_index_key(i);
            bool excluded = false;
            JS_ASSIGN_OR_RETURN(exclude_status, js_object_rest_key_excluded(key, exclude_keys, exclude_count,
                &excluded));
            if (excluded) continue;
            JS_ASSIGN_OR_RETURN(val, js_get_key_default(src, key));
            JS_ASSIGN_OR_RETURN(set_result, js_set_key_default(rest, key, val));
        }
        return rest;
    }

    TypeId src_type = get_type_id(src);
    if (src_type != LMD_TYPE_MAP && src_type != LMD_TYPE_ARRAY && src_type != LMD_TYPE_FUNC) return rest;

    JS_ASSIGN_OR_RETURN(keys, js_reflect_own_keys(src));
    if (get_type_id(keys) != LMD_TYPE_ARRAY) return rest;
    Array* key_arr = keys.array;
    for (int i = 0; i < key_arr->length; i++) {
        Item key = key_arr->items[i];
        bool excluded = false;
        JS_ASSIGN_OR_RETURN(exclude_status, js_object_rest_key_excluded(key, exclude_keys, exclude_count,
            &excluded));
        if (excluded) continue;
        JS_ASSIGN_OR_RETURN(desc, js_object_get_own_property_descriptor(src, key));
        if (get_type_id(desc) != LMD_TYPE_MAP) continue;
        bool enum_found = false;
        Item enum_val = js_map_shape_lookup_ext(desc.map, "enumerable", 10, &enum_found);
        if (!enum_found || !js_is_truthy(enum_val)) continue;
        JS_ASSIGN_OR_RETURN(val, js_get_key_default(src, key));
        if (!js_is_deleted_sentinel(val)) {
            JS_ASSIGN_OR_RETURN(set_result, js_set_key_default(rest, key, val));
        }
    }
    return rest;
}

// =============================================================================
// v15: Generator Runtime
// =============================================================================

// Generator state: the MIR-compiled state machine function takes
// (Item* env, Item input, int64_t state) and returns a 2-element array
// [value, next_state] where next_state == -1 means done.
using JsGenerator = JsGeneratorStateRecord;
#define js_generators (js_runtime_state.generators)
#define js_generator_count (js_runtime_state.generator_count)

static bool js_hidden_own_int_index(Item object, const char* name,
                                    int name_len, int64_t* out_index) {
    if (get_type_id(object) != LMD_TYPE_MAP || !object.map) return false;
    bool found = false;
    Item value = js_map_shape_lookup_ext(object.map, name, name_len, &found);
    if (!found || get_type_id(value) != LMD_TYPE_INT) return false;
    if (out_index) *out_index = it2i(value);
    return true;
}

extern "C" void js_generator_map_gc_trace(Map* map, gc_heap_t* gc) {
    if (!map || !gc) return;
    int64_t idx = -1;
    if (!js_hidden_own_int_index((Item){.map = map},
            "__gen_idx", 9, &idx)) return;
    if (idx < 0 || idx >= js_generator_count) return;
    if (js_generators[idx].env) gc_mark_object_ptr(gc, js_generators[idx].env);
    gc_mark_item(gc, js_generators[idx].private_home_class.item);
    gc_mark_item(gc, js_generators[idx].delegate.item);
}

// Helper: create {value, done} iterator result object
static Item js_make_iter_result(Item value, bool done) {
    RootFrame roots(2);
    Rooted<Item> value_root(roots, value);
    Rooted<Item> result_root(roots, js_new_object());
    String* val_key = heap_create_name("value", 5);
    String* done_key = heap_create_name("done", 4);
    // Property insertion may collect; retain both the fresh result map and a
    // scalar payload still owned by the generator state-result container.
    JS_ASSIGN_OR_RETURN(value_result, js_set_key_default(result_root.get(), (Item){.item = s2it(val_key)}, value_root.get()));
    JS_ASSIGN_OR_RETURN(done_result, js_set_key_default(result_root.get(), (Item){.item = s2it(done_key)},
        (Item){.item = b2it(done)}));
    return result_root.get();
}

static Item js_async_generator_wrap_yield_value(Item value) {
    return js_make_iter_result(value, false);
}

static Item js_async_generator_yield_result(Item value) {
    Item promise = js_promise_resolve(value);
    if (item_is_error(promise)) return js_promise_reject(js_error_lane_payload(promise));
    Item wrap_fn = js_new_native_function(js_async_generator_wrap_yield_value);
    return js_promise_then(promise, wrap_fn, make_js_undefined());
}

// v15: Create a 2-element array [value, next_state] for state machine returns
extern "C" Item js_gen_yield_result(Item value, int64_t next_state) {
    // D5.3/D5.4.3: building the state-result array can collect before its
    // payload store, so keep the yielded scalar and fresh result container
    // rooted across that allocation boundary.
    RootFrame roots(2);
    Rooted<Item> value_root(roots, value);
    Rooted<Item> result_root(roots, js_array_new(2));
    js_array_store_owned(result_root.get().array, 0, value_root.get());
    result_root.get().array->items[1] = (Item){.item = i2it(next_state)};
    return result_root.get();
}

// yield* delegation: create 3-element array [iterable, resume_state, 1(flag)]
extern "C" Item js_gen_yield_delegate_result(Item iterable, int64_t resume_state) {
    RootFrame roots(2);
    Rooted<Item> iterable_root(roots, iterable);
    Rooted<Item> result_root(roots, js_array_new(3));
    js_array_store_owned(result_root.get().array, 0, iterable_root.get());
    result_root.get().array->items[1] = (Item){.item = i2it(resume_state)};
    result_root.get().array->items[2] = (Item){.item = i2it(1)};  // delegation flag
    return result_root.get();
}

extern "C" Item js_gen_await_result(Item value, int64_t next_state) {
    RootFrame roots(2);
    Rooted<Item> value_root(roots, value);
    Rooted<Item> result_root(roots, js_array_new(3));
    js_array_store_owned(result_root.get().array, 0, value_root.get());
    result_root.get().array->items[1] = (Item){.item = i2it(next_state)};
    result_root.get().array->items[2] = (Item){.item = i2it(2)};  // async-generator await flag
    return result_root.get();
}


// Static prototype caches for Generator and AsyncGenerator instances.
// Per ES spec, the prototype chain for generator instances is:
//   gen → %GeneratorFunction%.prototype.prototype → %GeneratorPrototype% → %IteratorPrototype% → Object.prototype
// The test262 test does Object.getPrototypeOf(Object.getPrototypeOf(gen)) to get %GeneratorPrototype%.
// We implement two shared levels: a direct proto (depth 1) and the shared prototype (depth 2, has toStringTag).
#define js_generator_proto_depth1_cache (js_runtime_state.iterators.generator_proto_depth1)
#define js_async_generator_proto_depth1_cache (js_runtime_state.iterators.async_generator_proto_depth1)
#define js_generator_proto_depth2_cache (js_runtime_state.iterators.generator_proto_depth2)
#define js_async_generator_proto_depth2_cache (js_runtime_state.iterators.async_generator_proto_depth2)
#define js_async_iterator_proto_cache (js_runtime_state.iterators.async_iterator_prototype)

static Item js_get_async_iterator_proto() {
    if (!js_iterator_state_ensure_roots()) return ItemNull;
    if (js_async_iterator_proto_cache.item != 0 &&
        get_type_id(js_async_iterator_proto_cache) == LMD_TYPE_MAP) {
        return js_async_iterator_proto_cache;
    }
    RootFrame roots(3);
    Rooted<Item> proto_root(roots, js_new_object());
    Rooted<Item> obj_proto_root(roots, ItemNull);
    Rooted<Item> si_fn_root(roots, ItemNull);
    // D5.4.3: the realm cache cannot own this prototype until initialization
    // completes, and each constructor/property lookup below may collect.
    {
        Item obj_ctor = js_get_constructor((Item){.item = s2it(heap_create_name("Object", 6))});
        if (get_type_id(obj_ctor) == LMD_TYPE_FUNC) {
            Item proto_key = (Item){.item = s2it(heap_create_name("prototype", 9))};
            obj_proto_root.set(js_get_key_default(obj_ctor, proto_key));
            if (get_type_id(obj_proto_root.get()) == LMD_TYPE_MAP) {
                js_set_prototype(proto_root.get(), obj_proto_root.get());
            }
        }
    }
    Item si_key = js_well_known_symbol_key(5);
    si_fn_root.set(js_intrinsic_binding_get(
        JS_BUILTIN_OWNER_ASYNC_ITERATOR_INTERNAL,
        "[Symbol.asyncIterator]", 22));
    js_set_key_default(proto_root.get(), si_key, si_fn_root.get());
    js_mark_non_enumerable(proto_root.get(), si_key);
    js_async_iterator_proto_cache = proto_root.get();
    return proto_root.get();
}

// Returns the shared depth-2 prototype (%AsyncGeneratorPrototype%) with Symbol.toStringTag.
extern "C" Item js_get_generator_shared_proto(bool is_async) {
    if (!js_iterator_state_ensure_roots()) return ItemNull;
    Item* cache = is_async ? &js_async_generator_proto_depth2_cache : &js_generator_proto_depth2_cache;
    if (cache->item != 0 && get_type_id(*cache) == LMD_TYPE_MAP) return *cache;
    RootFrame roots(4);
    Rooted<Item> proto_root(roots, js_new_object());
    Rooted<Item> parent_root(roots, ItemNull);
    Rooted<Item> fn_root(roots, ItemNull);
    Rooted<Item> tag_val_root(roots, ItemNull);
    // D5.4.3: forced collection can run while intrinsic callables are created;
    // keep the unpublished shared prototype owned until its realm cache store.
    parent_root.set(is_async ? js_get_async_iterator_proto() : js_get_iterator_proto());
    js_set_prototype(proto_root.get(), parent_root.get());
    struct { const char* name; int len; } methods[] = {
        {"next", 4}, {"return", 6}, {"throw", 5}, {NULL, 0}
    };
    JsBuiltinOwner method_owner = is_async
        ? JS_BUILTIN_OWNER_ASYNC_GENERATOR_INTERNAL
        : JS_BUILTIN_OWNER_GENERATOR_INTERNAL;
    for (int i = 0; methods[i].name; i++) {
        Item key = (Item){.item = s2it(heap_create_name(methods[i].name, methods[i].len))};
        fn_root.set(js_intrinsic_binding_get(
            method_owner, methods[i].name, methods[i].len));
        js_set_key_default(proto_root.get(), key, fn_root.get());
        js_mark_non_enumerable(proto_root.get(), key);
    }
    // Symbol.toStringTag = "AsyncGenerator" | "Generator" (non-writable, non-enum, configurable)
    Item tag_key = js_well_known_symbol_key(4);
    tag_val_root.set((Item){.item = s2it(heap_create_name(
        is_async ? "AsyncGenerator" : "Generator", is_async ? 14 : 9))});
    js_set_key_default(proto_root.get(), tag_key, tag_val_root.get());
    js_mark_non_writable(proto_root.get(), tag_key);
    js_mark_non_enumerable(proto_root.get(), tag_key);
    // configurable: true is the default (don't set __nc_)
    *cache = proto_root.get();
    return proto_root.get();
}

static Item js_generator_create_current(void* func_ptr, Item* env, int env_size,
        int is_async) {
    Context* runtime = (Context*)context;
    if (!runtime) {
        log_error("js-generator: state machine missing context owner");
        return ItemError;
    }
    if (!js_mir_owner_is_current(runtime, "js-generator-create")) return ItemError;
    // Generator construction performs several allocating property/prototype
    // operations after creating the owning map. Keep that fresh map in an
    // exact native home so its GC tracer continuously owns the raw env.
    RootFrame roots(4);
    Rooted<Item> obj_root(roots, ItemNull);
    Rooted<Item> proto_root(roots, ItemNull);
    Rooted<Item> result_root(roots, ItemNull);
    Rooted<Item> private_home_root(roots, js_current_private_home_class);

    // Allocate a new generator slot (no recycling — old generator objects may still
    // hold __gen_idx references to completed slots, causing index collisions)
    int idx = -1;
    if (js_generator_count >= JS_MAX_GENERATORS) {
        // Last resort: recycle oldest completed slot
        for (int i = 0; i < js_generator_count; i++) {
            if (js_generators[i].done) {
                idx = i;
                break;
            }
        }
        if (idx < 0) {
            log_error("generator: exceeded max generators (%d)", JS_MAX_GENERATORS);
            return ItemNull;
        }
    } else {
        idx = js_generator_count++;
    }
    JsGenerator* gen = &js_generators[idx];
    gen->type_id = LMD_TYPE_MAP;
    gen->runtime_context = runtime;
    gen->state_fn = func_ptr;
    js_env_rehome_scalars(env);
    gen->env = env;
    gen->env_size = env_size;
    gen->state = 0;
    gen->done = false;
    gen->started = false;
    gen->executing = false;
    gen->is_async = (is_async != 0);
    // A generator resumes after its creating method has returned, so retain
    // the lexical class home instead of resolving private names from stale
    // ambient call state on a later next().
    gen->private_home_class = private_home_root.get();
    gen->delegate = ItemNull;
    gen->delegate_resume = -1;
    gen->delegate_idx = 0;

    // Create a map object that references this generator via a hidden index
    obj_root.set(js_new_object());
    String* gen_key = heap_create_name("__gen_idx", 9);
    js_set_key_default(obj_root.get(), (Item){.item = s2it(gen_key)},
        (Item){.item = i2it(idx)});
    // Set prototype: use the generator function's current .prototype if it's an
    // object (OrdinaryCreateFromConstructor).  Default parameter evaluation can
    // mutate g.prototype before the generator object is created, so read the
    // pending callee now instead of relying only on the pre-call snapshot.
    {
        Item callee_proto = (Item){0};
        if (get_type_id(js_pending_args_callee) == LMD_TYPE_FUNC) {
            Item proto_key = (Item){.item = s2it(heap_create_name("prototype", 9))};
            callee_proto = js_get_key_default(js_pending_args_callee, proto_key);
        }
        if (callee_proto.item == 0) callee_proto = js_generator_callee_proto;
        proto_root.set(callee_proto);
        js_generator_callee_proto = (Item){0}; // reset
        if (proto_root.get().item != 0 &&
                get_type_id(proto_root.get()) == LMD_TYPE_MAP) {
            js_set_prototype(obj_root.get(), proto_root.get());
        } else {
            // Fallback: use %AsyncGeneratorPrototype% / %GeneratorPrototype% (depth-2)
            proto_root.set(js_get_generator_shared_proto((bool)(is_async != 0)));
            js_set_prototype(obj_root.get(), proto_root.get());
        }
    }
    // ES spec: Eagerly execute state 0 (parameter binding / FunctionDeclarationInstantiation).
    // The state machine emits an implicit yield after param destructuring. Running state 0
    // here ensures destructuring errors throw synchronously at call time, not on .next().
    {
        gen->executing = true;
        result_root.set(js_invoke_mir_state(func_ptr, env,
            make_js_undefined(), 0));
        gen->executing = false;

        // If param destructuring threw, propagate the exception
        if (item_is_error(result_root.get())) {
            gen->done = true;
            gen->state = -1;
            return result_root.get();
        }

        // Update state from implicit yield result
        if (get_type_id(result_root.get()) == LMD_TYPE_ARRAY) {
            Array* arr = result_root.get().array;
            if (arr->length > 1 && get_type_id(arr->items[1]) == LMD_TYPE_INT) {
                gen->state = (int)it2i(arr->items[1]);
            }
        }
    }

    return obj_root.get();
}

extern "C" Item js_generator_create_mir(void* func_ptr, Item* env,
        int env_size, int is_async) {
    Context* runtime = (Context*)context;
    if (!runtime) {
        log_error("js-generator: state machine missing context owner");
        return ItemError;
    }
    return js_generator_create_current(func_ptr, env, env_size, is_async);
}

extern "C" Item js_generator_create(void* func_ptr, Item* env, int env_size,
        int is_async) {
    return js_generator_create_current(func_ptr, env, env_size, is_async);
}

static JsGenerator* js_get_generator(Item gen_obj) {
    int64_t idx = -1;
    if (!js_hidden_own_int_index(gen_obj, "__gen_idx", 9, &idx)) return NULL;
    if (idx < 0 || idx >= js_generator_count) return NULL;
    return &js_generators[idx];
}

#define js_gen_return_signal_marker (js_runtime_state.iterators.generator_return_marker)
#define js_gen_throw_signal_marker (js_runtime_state.iterators.generator_throw_marker)

static bool js_iterator_state_ensure_roots(void) {
    return js_active_runtime_state &&
        js_root_range_ensure_registered(&js_runtime_state.iterators.roots);
}

static Item js_get_gen_return_signal_marker() {
    if (js_gen_return_signal_marker.item == 0) {
        if (!js_iterator_state_ensure_roots()) return ItemNull;
        js_gen_return_signal_marker = js_new_object();
    }
    return js_gen_return_signal_marker;
}

extern "C" Item js_gen_return_signal(Item value) {
    Item signal = js_array_new(2);
    js_array_store_owned(signal.array, 0, value);
    signal.array->items[1] = js_get_gen_return_signal_marker();
    return signal;
}

extern "C" int64_t js_gen_is_return_signal(Item value) {
    if (get_type_id(value) != LMD_TYPE_ARRAY || value.array->length < 2) return 0;
    Item tag = value.array->items[1];
    return (tag.item == js_get_gen_return_signal_marker().item) ? 1 : 0;
}

extern "C" Item js_gen_return_signal_value(Item value) {
    if (get_type_id(value) != LMD_TYPE_ARRAY || value.array->length < 1) return make_js_undefined();
    return value.array->items[0];
}

// A thrown-into-generator value must cross a suspension as ordinary input;
// publishing it directly into the ERROR lane would make the state machine
// terminate before the suspended try/finally can run.
static Item js_get_gen_throw_signal_marker() {
    if (js_gen_throw_signal_marker.item == 0) {
        if (!js_iterator_state_ensure_roots()) return ItemNull;
        js_gen_throw_signal_marker = js_new_object();
    }
    return js_gen_throw_signal_marker;
}

extern "C" Item js_gen_throw_signal(Item value) {
    RootFrame roots(3);
    Rooted<Item> value_root(roots, value);
    Rooted<Item> signal_root(roots, js_array_new(2));
    if (get_type_id(signal_root.get()) != LMD_TYPE_ARRAY) return ItemError;
    js_array_store_owned(signal_root.get().array, 0, value_root.get());
    signal_root.get().array->items[1] = js_get_gen_throw_signal_marker();
    return signal_root.get();
}

extern "C" int64_t js_gen_is_throw_signal(Item value) {
    if (get_type_id(value) != LMD_TYPE_ARRAY || value.array->length < 2) return 0;
    Item tag = value.array->items[1];
    return (tag.item == js_get_gen_throw_signal_marker().item) ? 1 : 0;
}

extern "C" Item js_gen_throw_signal_value(Item value) {
    if (get_type_id(value) != LMD_TYPE_ARRAY || value.array->length < 1) return make_js_undefined();
    return value.array->items[0];
}

static Item js_iter_result_is_done(Item result) {
    TypeId tid = get_type_id(result);
    if (tid != LMD_TYPE_MAP && tid != LMD_TYPE_ELEMENT && tid != LMD_TYPE_ARRAY) {
        return js_throw_type_error("iterator result is not an object");
    }
    Item done_key = (Item){.item = s2it(heap_create_name("done", 4))};
    JS_ASSIGN_OR_RETURN(done_item, js_get_key_default(result, done_key));
    return js_to_boolean(done_item);
}

static Item js_iter_result_value(Item result) {
    Item val_key = (Item){.item = s2it(heap_create_name("value", 5))};
    return js_get_key_default(result, val_key);
}

extern "C" Item js_iterator_result_done(Item result) {
    return js_iter_result_is_done(result);
}

extern "C" Item js_iterator_result_value(Item result) {
    return js_iter_result_value(result);
}

extern "C" Item js_async_iterator_step_result(Item iterator) {
    if (js_is_generator(iterator) && !js_is_async_generator(iterator)) {
        return js_generator_next(iterator, make_js_undefined());
    }

    if (get_type_id(iterator) == LMD_TYPE_MAP && iterator.map->map_kind == MAP_KIND_ITERATOR) {
        JS_ASSIGN_OR_RETURN(value, js_iterator_step(iterator));
        if (value.item == JS_ITER_DONE_SENTINEL) return js_make_iter_result(make_js_undefined(), true);
        return js_make_iter_result(value, false);
    }

    TypeId tid = get_type_id(iterator);
    if (tid != LMD_TYPE_MAP && tid != LMD_TYPE_ELEMENT && tid != LMD_TYPE_ARRAY) {
        return js_throw_type_error("iterator next is not a function");
    }

    JS_ASSIGN_OR_RETURN(next_fn, js_get_key_default(iterator,
        (Item){.item = s2it(heap_create_name("next", 4))}));
    if (!js_is_callable(next_fn)) {
        return js_throw_type_error("iterator next is not a function");
    }
    Item result = js_call_function(next_fn, iterator, NULL, 0);
    return result;
}

static Item js_yield_delegate_next_result(Item iterator, Item input) {
    if (js_is_generator(iterator)) {
        return js_generator_next(iterator, input);
    }

    if (get_type_id(iterator) == LMD_TYPE_MAP && iterator.map->map_kind == MAP_KIND_ITERATOR) {
        JS_ASSIGN_OR_RETURN(value, js_iterator_step(iterator));
        if (value.item == JS_ITER_DONE_SENTINEL) return js_make_iter_result(make_js_undefined(), true);
        return js_make_iter_result(value, false);
    }

    TypeId tid = get_type_id(iterator);
    if (tid == LMD_TYPE_MAP || tid == LMD_TYPE_ELEMENT) {
        Item next_key = (Item){.item = s2it(heap_create_name("next", 4))};
        JS_ASSIGN_OR_RETURN(next_fn, js_get_key_default(iterator, next_key));
        if (!js_is_callable(next_fn)) {
            return js_throw_type_error("iterator next is not a function");
        }
        Item args[1];
        args[0] = input;
        JS_ASSIGN_OR_RETURN(result, js_call_function(next_fn, iterator, args, 1));
        TypeId result_tid = get_type_id(result);
        if (result_tid != LMD_TYPE_MAP && result_tid != LMD_TYPE_ELEMENT && result_tid != LMD_TYPE_ARRAY) {
            return js_throw_type_error("iterator result is not an object");
        }
        return result;
    }

    return js_throw_type_error("iterator result is not an object");
}

static Item js_generator_resume_after_delegate_error(Item generator, JsGenerator* gen,
        Item error_lane) {
    Item caught_value = js_error_lane_payload(error_lane);
    gen->delegate = ItemNull;
    gen->state = gen->delegate_resume;
    gen->delegate_resume = -1;
    gen->delegate_idx = 0;
    // A delegate protocol error is an abrupt completion of yield*, so inject
    // its original thrown value into the suspended outer generator.
    return js_generator_next(generator, js_gen_throw_signal(caught_value));
}

static Item js_async_generator_await_resume(Item generator, Item resolved) {
    return js_generator_next(generator, resolved);
}

static Item js_async_generator_await_reject(Item generator, Item reason) {
    return js_generator_throw(generator, reason);
}

extern "C" Item js_generator_next(Item generator, Item input) {
    JsGenerator* gen = js_get_generator(generator);
    if (!gen) {
        log_error("generator_next: invalid generator object");
        Item result = js_make_iter_result(make_js_undefined(), true);
        return result;
    }
    if (!js_mir_owner_is_current(gen->runtime_context,
            "js-generator-next")) return ItemError;
    RootFrame roots(6);
    Rooted<Item> generator_root(roots, generator);
    Rooted<Item> input_root(roots, input);
    Rooted<Item> result_root(roots, ItemNull);
    Rooted<Item> value_root(roots, ItemNull);
    Rooted<Item> saved_private_home_root(roots, js_current_private_home_class);
    Rooted<Item> generator_private_home_root(roots, gen->private_home_class);

    bool is_async = gen->is_async;

    if (gen->done) {
        Item result = js_make_iter_result(make_js_undefined(), true);
        return is_async ? js_promise_resolve(result) : result;
    }

    // ES spec: throw TypeError if called while generator is already executing
    if (gen->executing) {
        return js_throw_type_error("Generator is already running");
    }

    gen->started = true;
    gen->executing = true;

    // If we have an active delegate (from yield*), advance it by one
    // iterator result. Delegates can be infinite; do not drain them here.
    if (get_type_id(gen->delegate) != LMD_TYPE_NULL) {
        Item del_result = js_yield_delegate_next_result(gen->delegate, input);
        if (item_is_error(del_result)) {
            gen->delegate = ItemNull;
            gen->state = gen->delegate_resume;
            gen->delegate_resume = -1;
            gen->delegate_idx = 0;
            gen->executing = false;
            return js_generator_throw(generator_root.get(), js_error_lane_payload(del_result));
        }
        Item del_done_item = js_iter_result_is_done(del_result);
        if (item_is_error(del_done_item)) {
            gen->executing = false;
            return js_generator_resume_after_delegate_error(
                generator_root.get(), gen, del_done_item);
        }
        if (js_is_truthy(del_done_item)) {
            Item return_val = js_iter_result_value(del_result);
            if (item_is_error(return_val)) {
                gen->executing = false;
                return js_generator_resume_after_delegate_error(
                    generator_root.get(), gen, return_val);
            }
            // Delegate exhausted — clear it and resume our state machine
            gen->delegate = ItemNull;
            gen->state = gen->delegate_resume;
            gen->delegate_resume = -1;
            gen->delegate_idx = 0;
            input = return_val;
            input_root.set(input);
            // Fall through to call state machine at resumed state
        } else {
            gen->executing = false;
            if (is_async) {
                Item del_value = js_iter_result_value(del_result);
                if (item_is_error(del_value)) return js_promise_reject(del_value);
                return js_async_generator_yield_result(del_value);
            }
            return del_result;
        }
    }

    // Call the state machine: fn(env, input, state) -> [value, next_state]
    // The state machine returns {value, next_state} as a 2-element array
    // If next_state == -1, the generator is done
    // If next_state == -3, this is yield* delegation: value is the iterable
    int saved_private_home_index = js_current_private_home_class_index;
    Item generator_private_home = generator_private_home_root.get();
    if (generator_private_home.item != ItemNull.item &&
        generator_private_home.item != 0 &&
        get_type_id(generator_private_home) != LMD_TYPE_UNDEFINED) {
        js_current_private_home_class = generator_private_home;
        js_current_private_home_class_index = js_class_private_index(generator_private_home);
    }
    result_root.set(js_invoke_mir_state(gen->state_fn,
        gen->env, input_root.get(), gen->state));
    js_current_private_home_class = saved_private_home_root.get();
    js_current_private_home_class_index = saved_private_home_index;
    Item result = result_root.get();
    if (item_is_error(result)) {
        gen->done = true;
        gen->state = -1;
        gen->executing = false;
        return is_async ? js_promise_reject(js_error_lane_payload(result)) : result;
    }

    if (get_type_id(result) == LMD_TYPE_ARRAY) {
        Array* arr = result.array;
        Item value = (arr->length > 0) ? arr->items[0] : ItemNull;
        value_root.set(value);
        // D5.3/D5.4.3: the state-result array owns wide scalar tails, but the
        // iterator-result map may allocate and compact that array before it
        // consumes the value; re-home the scalar while the source is rooted.
        value_root.set(scalar_storage_read(value_root.get(), false));
        value = value_root.get();
        int64_t next_state = -1;
        if (arr->length > 1 && get_type_id(arr->items[1]) == LMD_TYPE_INT) {
            next_state = it2i(arr->items[1]);
        }

        // Check for yield* delegation marker (3-element array with flag)
        if (arr->length > 2 && get_type_id(arr->items[2]) == LMD_TYPE_INT && it2i(arr->items[2]) == 1) {
            // value is the iterable to delegate to, next_state is the resume state
            Item iterator = js_get_iterator(value);
            if (item_is_error(iterator)) {
                gen->delegate = ItemNull;
                gen->state = next_state;
                gen->delegate_resume = -1;
                gen->delegate_idx = 0;
                input = make_js_undefined();
                input_root.set(input);
                gen->executing = false;
                return js_generator_throw(generator_root.get(), js_error_lane_payload(iterator));
            }
            gen->delegate = iterator;
            gen->delegate_resume = next_state;
            gen->delegate_idx = 0;
            // Immediately take the first delegated step.
            gen->executing = false;
            return js_generator_next(generator, make_js_undefined());
        }

        if (arr->length > 2 && get_type_id(arr->items[2]) == LMD_TYPE_INT && it2i(arr->items[2]) == 2) {
            gen->state = next_state;
            gen->executing = false;
            if (!is_async) return js_generator_next(generator, value);
            Item promise = js_promise_resolve(value);
            Item on_fulfilled = js_bind_function(
                js_new_native_function(js_async_generator_await_resume),
                make_js_undefined(), &generator, 1);
            Item on_rejected = js_bind_function(
                js_new_native_function(js_async_generator_await_reject),
                make_js_undefined(), &generator, 1);
            return js_promise_then(promise, on_fulfilled, on_rejected);
        }

        if (next_state < 0) {
            gen->done = true;
            gen->state = -1;
            gen->executing = false;
            Item iter_result = js_make_iter_result(value, true);
            return is_async ? js_promise_resolve(iter_result) : iter_result;
        } else {
            gen->state = next_state;
            gen->executing = false;
            if (is_async) return js_async_generator_yield_result(value);
            return js_make_iter_result(value, false);
        }
    }

    // Fallback: function returned a plain value (final return)
    gen->done = true;
    gen->state = -1;
    gen->executing = false;
    Item iter_result = js_make_iter_result(result, true);
    return is_async ? js_promise_resolve(iter_result) : iter_result;
}

static Item js_generator_resume_return_signal(JsGenerator* gen, bool is_async,
        Item value) {
    if (!gen || gen->done) {
        Item done_result = js_make_iter_result(value, true);
        return is_async ? js_promise_resolve(done_result) : done_result;
    }
    if (gen->executing) {
        return js_throw_type_error("Generator is already running");
    }
    gen->executing = true;
    Item signal = js_gen_return_signal(value);
    Item result = js_invoke_mir_state(gen->state_fn, gen->env, signal, gen->state);
    gen->executing = false;
    if (item_is_error(result)) {
        gen->done = true;
        gen->state = -1;
        return result;
    }
    if (get_type_id(result) == LMD_TYPE_ARRAY) {
        Array* arr = result.array;
        Item out_value = (arr->length > 0) ? arr->items[0] : make_js_undefined();
        int64_t next_state = -1;
        if (arr->length > 1 && get_type_id(arr->items[1]) == LMD_TYPE_INT) {
            next_state = it2i(arr->items[1]);
        }
        if (next_state < 0) {
            gen->done = true;
            gen->state = -1;
            if (js_gen_is_return_signal(out_value)) {
                out_value = js_gen_return_signal_value(out_value);
            }
            Item done_result = js_make_iter_result(out_value, true);
            return is_async ? js_promise_resolve(done_result) : done_result;
        }
        gen->state = next_state;
        if (is_async) return js_async_generator_yield_result(out_value);
        return js_make_iter_result(out_value, false);
    }
    gen->done = true;
    gen->state = -1;
    Item done_result = js_make_iter_result(result, true);
    return is_async ? js_promise_resolve(done_result) : done_result;
}

static Item js_generator_delegate_abrupt_call(Item generator, JsGenerator* gen,
        Item delegate_fn, Item value, bool is_return, bool is_async) {
    Item args[1] = { value };
    Item inner = js_call_function(delegate_fn, gen->delegate, args, 1);
    if (item_is_error(inner)) {
        return js_generator_resume_after_delegate_error(generator, gen, inner);
    }
    TypeId itid = get_type_id(inner);
    if (itid != LMD_TYPE_MAP && itid != LMD_TYPE_ELEMENT && itid != LMD_TYPE_ARRAY) {
        Item error = js_new_error_with_name(
            (Item){.item = s2it(heap_create_name("TypeError", 9))},
            (Item){.item = s2it(heap_create_name("iterator result is not an object", 31))});
        return js_generator_resume_after_delegate_error(
            generator, gen, js_throw_value(error));
    }
    Item done_item = js_iter_result_is_done(inner);
    if (item_is_error(done_item)) {
        return js_generator_resume_after_delegate_error(generator, gen, done_item);
    }
    if (!js_is_truthy(done_item)) {
        if (is_async) {
            Item inner_yield_value = js_iter_result_value(inner);
            if (item_is_error(inner_yield_value)) return js_promise_reject(inner_yield_value);
            return js_async_generator_yield_result(inner_yield_value);
        }
        return inner;
    }
    Item inner_value = js_iter_result_value(inner);
    if (item_is_error(inner_value)) {
        return js_generator_resume_after_delegate_error(generator, gen, inner_value);
    }
    gen->state = gen->delegate_resume;
    gen->delegate = ItemNull;
    gen->delegate_resume = -1;
    gen->delegate_idx = 0;
    if (is_return) return js_generator_resume_return_signal(gen, is_async, inner_value);
    return js_generator_next(generator, inner_value);
}

extern "C" Item js_generator_return(Item generator, Item value) {
    JsGenerator* gen = js_get_generator(generator);
    bool is_async = gen && gen->is_async;
    if (gen) {
        if (!js_mir_owner_is_current(gen->runtime_context,
                "js-generator-return")) return ItemError;
        if (!gen->done && !gen->started) {
            gen->done = true;
            gen->state = -1;
            Item result = js_make_iter_result(value, true);
            return is_async ? js_promise_resolve(result) : result;
        }
        if (gen->env && gen->env_size > 0) {
            int active_slot = gen->env_size - 1;
            Item active_iterator = gen->env[active_slot];
            TypeId active_tid = get_type_id(active_iterator);
            if (active_iterator.item != 0 &&
                active_tid != LMD_TYPE_NULL &&
                active_tid != LMD_TYPE_UNDEFINED) {
                gen->env[active_slot] = ItemNull;
                Item close_result = js_iterator_close(active_iterator);
                if (item_is_error(close_result)) {
                    gen->delegate = ItemNull;
                    gen->done = true;
                    gen->state = -1;
                    return close_result;
                }
            }
        }
        if (get_type_id(gen->delegate) != LMD_TYPE_NULL) {
            Item return_fn = js_get_key_default(gen->delegate,
                (Item){.item = s2it(heap_create_name("return", 6))});
            if (item_is_error(return_fn)) {
                return js_generator_resume_after_delegate_error(generator, gen, return_fn);
            }
            if (js_is_callable(return_fn)) {
                return js_generator_delegate_abrupt_call(generator, gen, return_fn,
                    value, true, is_async);
            } else {
                TypeId rtid = get_type_id(return_fn);
                if (rtid != LMD_TYPE_UNDEFINED && rtid != LMD_TYPE_NULL && return_fn.item != ITEM_JS_UNDEFINED) {
                    Item error = js_new_error_with_name(
                        (Item){.item = s2it(heap_create_name("TypeError", 9))},
                        (Item){.item = s2it(heap_create_name("iterator return is not a function", 33))});
                    return js_generator_resume_after_delegate_error(
                        generator, gen, js_throw_value(error));
                }
            }
            gen->state = gen->delegate_resume;
            gen->delegate = ItemNull;
            gen->delegate_resume = -1;
            gen->delegate_idx = 0;
        }
        if (!gen->done) {
            return js_generator_resume_return_signal(gen, is_async, value);
        }
    }
    Item result = js_make_iter_result(value, true);
    return is_async ? js_promise_resolve(result) : result;
}

extern "C" Item js_generator_throw(Item generator, Item error) {
    JsGenerator* gen = js_get_generator(generator);
    bool is_async = gen && gen->is_async;
    if (gen) {
        if (!js_mir_owner_is_current(gen->runtime_context,
                "js-generator-throw")) return ItemError;
        if (!gen->done && !gen->started) {
            gen->done = true;
            gen->state = -1;
            Item throw_result = js_throw_value(error);
            if (item_is_error(throw_result)) {
                // Async-generator throw() is promise-based even when the
                // generator has not started; expose the rejection instead of
                // leaking the internal ERROR lane to the caller.
                return is_async ? js_promise_reject(js_error_lane_payload(throw_result)) : throw_result;
            }
            Item result = js_make_iter_result(make_js_undefined(), true);
            return is_async ? js_promise_resolve(result) : result;
        }
        if (get_type_id(gen->delegate) != LMD_TYPE_NULL) {
            Item throw_fn = js_get_key_default(gen->delegate,
                (Item){.item = s2it(heap_create_name("throw", 5))});
            if (item_is_error(throw_fn)) {
                return js_generator_resume_after_delegate_error(generator, gen, throw_fn);
            }
            if (js_is_callable(throw_fn)) {
                return js_generator_delegate_abrupt_call(generator, gen, throw_fn,
                    error, false, is_async);
            }
            TypeId ttid = get_type_id(throw_fn);
            if (ttid != LMD_TYPE_UNDEFINED && ttid != LMD_TYPE_NULL && throw_fn.item != ITEM_JS_UNDEFINED) {
                Item error = js_new_error_with_name(
                    (Item){.item = s2it(heap_create_name("TypeError", 9))},
                    (Item){.item = s2it(heap_create_name("iterator throw is not a function", 33))});
                return js_generator_resume_after_delegate_error(
                    generator, gen, js_throw_value(error));
            }
            Item delegate_iterator = gen->delegate;
            gen->delegate = ItemNull;
            gen->state = gen->delegate_resume;
            Item close_result = js_iterator_close(delegate_iterator);
            if (item_is_error(close_result)) {
                return js_generator_resume_after_delegate_error(generator, gen, close_result);
            }
            gen->delegate_resume = -1;
            gen->delegate_idx = 0;
                    Item error = js_new_error_with_name(
                        (Item){.item = s2it(heap_create_name("TypeError", 9))},
                        (Item){.item = s2it(heap_create_name("The iterator does not provide a 'throw' method", 46))});
            return js_generator_next(generator, js_gen_throw_signal(error));
        }
        if (!gen->done) {
            if (gen->executing) {
                return js_throw_type_error("Generator is already running");
            }
            // Resume at the suspended yield so its surrounding finally/catch
            // receives the injected throw instead of bypassing the generator.
            return js_generator_next(generator, js_gen_throw_signal(error));
        }
    }
    // Throw the error via the JS exception mechanism
    return js_throw_value(error);
}

// v15: Check if an object is a generator (has __gen_idx property)
extern "C" bool js_is_generator(Item obj) {
    // Synthetic fast iterators (MAP_KIND_ITERATOR) are never generators and have
    // no real shape — a property lookup on them reads their sentinel type out of
    // bounds, so short-circuit here.
    if (get_type_id(obj) != LMD_TYPE_MAP || !obj.map ||
        obj.map->map_kind == MAP_KIND_ITERATOR) return false;
    // generator identity is an internal own slot; inherited lookups can invoke
    // unrelated accessors and must never brand an ordinary object.
    return js_hidden_own_int_index(obj, "__gen_idx", 9, NULL);
}

extern "C" bool js_is_async_generator(Item obj) {
    JsGenerator* gen = js_get_generator(obj);
    return gen && gen->is_async;
}

// =============================================================================
// v29: Lazy iteration protocol for for-of
// GetIterator(iterable) → returns the iterator object.
// For arrays: returns a synthetic array iterator (lightweight wrapper).
// For generators: returns the generator itself.
// For objects with [Symbol.iterator]: calls it and returns the result.
// =============================================================================

// v28: Iterator sub-type sentinel markers (for MAP_KIND_ITERATOR dispatch)
static char js_array_iter_marker;
static char js_string_iter_marker;
static char js_typed_array_iter_marker;

#define js_iterator_proto_cache (js_runtime_state.iterators.iterator_prototype)
#define js_array_iterator_proto_cache (js_runtime_state.iterators.array_iterator_prototype)
#define js_string_iterator_proto_cache (js_runtime_state.iterators.string_iterator_prototype)
#define js_map_iterator_proto_cache (js_runtime_state.iterators.map_iterator_prototype)
#define js_set_iterator_proto_cache (js_runtime_state.iterators.set_iterator_prototype)
#define js_regexp_string_iterator_proto_cache (js_runtime_state.iterators.regexp_string_iterator_prototype)

extern "C" void js_iterator_proto_cache_reset(void) {
    js_iterator_proto_cache = (Item){0};
    js_array_iterator_proto_cache = (Item){0};
    js_string_iterator_proto_cache = (Item){0};
    js_map_iterator_proto_cache = (Item){0};
    js_set_iterator_proto_cache = (Item){0};
    js_regexp_string_iterator_proto_cache = (Item){0};
}

static Item js_make_iterator_proto(Item* cache, JsBuiltinOwner next_owner,
                                   const char* tag, int tag_len) {
    if (!js_iterator_state_ensure_roots()) return ItemNull;
    if (cache->item != 0 && get_type_id(*cache) == LMD_TYPE_MAP) {
        if (next_owner == JS_BUILTIN_OWNER_NONE) return *cache;
        bool has_next = false;
        js_map_shape_lookup(cache->map, "next", 4, &has_next);
        if (has_next) return *cache;
        // A genuine user-visible deletion leaves a deleted own slot, so only
        // a missing builtin slot is treated as stale cache state and recreated.
        *cache = (Item){0};
    }

    RootFrame roots(3);
    Rooted<Item> proto_root(roots, js_new_object());
    Rooted<Item> next_fn_root(roots, ItemNull);
    Rooted<Item> tag_val_root(roots, ItemNull);
    // The persistent cache is not published until initialization completes;
    // own the prototype and its unpublished values across allocating setters.
    if (next_owner != JS_BUILTIN_OWNER_NONE) {
        Item next_key = (Item){.item = s2it(heap_create_name("next", 4))};
        next_fn_root.set(js_intrinsic_binding_get(next_owner, "next", 4));
        js_set_key_default(proto_root.get(), next_key, next_fn_root.get());
        js_mark_non_enumerable(proto_root.get(), next_key);
    }

    Item tag_key = js_well_known_symbol_key(4);
    tag_val_root.set((Item){.item = s2it(heap_create_name(tag, tag_len))});
    js_set_key_default(proto_root.get(), tag_key, tag_val_root.get());
    js_mark_non_writable(proto_root.get(), tag_key);
    js_mark_non_enumerable(proto_root.get(), tag_key);
    *cache = proto_root.get();
    return proto_root.get();
}

static Item js_get_iterator_proto() {
    if (!js_iterator_state_ensure_roots()) return ItemNull;
    if (js_iterator_proto_cache.item != 0 &&
        get_type_id(js_iterator_proto_cache) == LMD_TYPE_MAP) {
        return js_iterator_proto_cache;
    }
    RootFrame roots(2);
    Rooted<Item> proto_root(roots, js_new_object());
    Rooted<Item> si_fn_root(roots, ItemNull);
    // The cache becomes the persistent owner only after the prototype is
    // complete, so construction needs exact temporary ownership.
    Item si_key = js_well_known_symbol_key(1);
    si_fn_root.set(js_intrinsic_binding_get(
        JS_BUILTIN_OWNER_ITERATOR_INTERNAL, "[Symbol.iterator]", 17));
    js_set_key_default(proto_root.get(), si_key, si_fn_root.get());
    js_mark_non_enumerable(proto_root.get(), si_key);
    js_iterator_proto_cache = proto_root.get();
    return proto_root.get();
}

static Item js_get_array_iterator_proto() {
    Item proto = js_make_iterator_proto(&js_array_iterator_proto_cache,
        JS_BUILTIN_OWNER_ARRAY_ITERATOR_INTERNAL, "Array Iterator", 14);
    js_set_prototype(proto, js_get_iterator_proto());
    return proto;
}

static bool js_array_iterator_next_is_default() {
    Item proto = js_get_array_iterator_proto();
    Item next = js_get_key_default(proto, (Item){.item = s2it(heap_create_name("next", 4))});
    if (item_is_error(next)) return false;
    if (!js_is_callable(next)) return false;
    Item expected = js_intrinsic_binding_get(
        JS_BUILTIN_OWNER_ARRAY_ITERATOR_INTERNAL, "next", 4);
    return next.item == expected.item;
}

static Item js_array_iterator_source_length(Item source) {
    if (!js_is_js_array(source)) return (Item){.item = i2it(0)};
    if (get_type_id(source) == LMD_TYPE_ARRAY_NUM) {
        return (Item){.item = i2it(js_array_length(source))};
    }
    if (!js_is_arguments_exotic_array(source)) return (Item){.item = i2it(source.array->length)};
    Item len_key = (Item){.item = s2it(heap_create_name("length", 6))};
    JS_ASSIGN_OR_RETURN(length, js_get_key_default(source, len_key));
    return (Item){.item = i2it(js_array_to_length(length))};
}

static Item js_get_string_iterator_proto() {
    Item proto = js_make_iterator_proto(&js_string_iterator_proto_cache,
        JS_BUILTIN_OWNER_STRING_ITERATOR_INTERNAL, "String Iterator", 15);
    js_set_prototype(proto, js_get_iterator_proto());
    return proto;
}

Item js_iterator_prototype_for_object(Item object) {
    if (get_type_id(object) != LMD_TYPE_MAP || !object.map ||
        object.map->map_kind != MAP_KIND_ITERATOR) return ItemNull;
    return object.map->type == (void*)&js_string_iter_marker
        ? js_get_string_iterator_proto()
        : js_get_array_iterator_proto();
}

static Item js_get_map_iterator_proto() {
    Item proto = js_make_iterator_proto(&js_map_iterator_proto_cache,
        JS_BUILTIN_OWNER_COLLECTION_ITERATOR_INTERNAL, "Map Iterator", 12);
    js_set_prototype(proto, js_get_iterator_proto());
    return proto;
}

static Item js_get_set_iterator_proto() {
    Item proto = js_make_iterator_proto(&js_set_iterator_proto_cache,
        JS_BUILTIN_OWNER_COLLECTION_ITERATOR_INTERNAL, "Set Iterator", 12);
    js_set_prototype(proto, js_get_iterator_proto());
    return proto;
}

static Item js_get_regexp_string_iterator_proto() {
    Item proto = js_make_iterator_proto(&js_regexp_string_iterator_proto_cache,
        JS_BUILTIN_OWNER_REGEXP_ITERATOR_INTERNAL, "RegExp String Iterator", 22);
    js_set_prototype(proto, js_get_iterator_proto());
    return proto;
}

// v28: Fixed-layout iterator data (16 bytes, 2 slots)
// Slot 0 (offset 0): source Item (array, string, or typed array)
// Slot 1 (offset 8): current index (int64_t)
struct JsIterData {
    Item source;     // the iterable being iterated
    int64_t index;   // current position
    int64_t length;  // v28: snapshot of source length at creation (prevents infinite loops)
};

// v28: Create lightweight fixed-layout array iterator (MAP_KIND_ITERATOR)
static Item js_create_array_iterator(Item source) {
    RootFrame roots(1);
    Rooted<Item> source_root(roots, source);
    Map* m = (Map*)heap_calloc_class(sizeof(Map), LMD_TYPE_MAP, JS_MAP_SIZE_CLASS);
    m->type_id = LMD_TYPE_MAP;
    m->map_kind = MAP_KIND_ITERATOR;
    m->type = (void*)&js_array_iter_marker;
    JsIterData* data = (JsIterData*)mem_alloc(sizeof(JsIterData), MEM_CAT_JS_RUNTIME);
    data->source = source_root.get();
    data->index = 0;
    data->length = -1;
    m->data = data;
    m->data_cap = sizeof(JsIterData);
    return (Item){.map = m};
}

static Item js_create_array_iterator_object(Item source, int kind) {
    RootFrame roots(2);
    Rooted<Item> source_root(roots, source);
    Rooted<Item> iter_root(roots, js_new_object());
    // The iterator is unpublished while its prototype and private fields are
    // allocated, so native-stack visibility cannot be its precise GC owner.
    js_set_prototype(iter_root.get(), js_get_array_iterator_proto());
    js_set_key_default(iter_root.get(), (Item){.item = s2it(heap_create_name("__array__", 9))}, source_root.get());
    js_set_key_default(iter_root.get(), (Item){.item = s2it(heap_create_name("__index__", 9))}, (Item){.item = i2it(0)});
    js_set_key_default(iter_root.get(), (Item){.item = s2it(heap_create_name("__kind__", 8))}, (Item){.item = i2it(kind)});
    return iter_root.get();
}

// v28: Create lightweight fixed-layout string iterator
static Item js_create_string_iterator(Item source) {
    RootFrame roots(1);
    Rooted<Item> source_root(roots, source);
    Map* m = (Map*)heap_calloc_class(sizeof(Map), LMD_TYPE_MAP, JS_MAP_SIZE_CLASS);
    m->type_id = LMD_TYPE_MAP;
    m->map_kind = MAP_KIND_ITERATOR;
    m->type = (void*)&js_string_iter_marker;
    JsIterData* data = (JsIterData*)mem_alloc(sizeof(JsIterData), MEM_CAT_JS_RUNTIME);
    data->source = source_root.get();
    data->index = 0;
    m->data = data;
    m->data_cap = sizeof(JsIterData);
    return (Item){.map = m};
}

// v28: Create lightweight fixed-layout typed array iterator
static Item js_create_typed_array_iterator(Item source) {
    RootFrame roots(1);
    Rooted<Item> source_root(roots, source);
    Map* m = (Map*)heap_calloc_class(sizeof(Map), LMD_TYPE_MAP, JS_MAP_SIZE_CLASS);
    m->type_id = LMD_TYPE_MAP;
    m->map_kind = MAP_KIND_ITERATOR;
    m->type = (void*)&js_typed_array_iter_marker;
    JsIterData* data = (JsIterData*)mem_alloc(sizeof(JsIterData), MEM_CAT_JS_RUNTIME);
    data->source = source_root.get();
    data->index = 0;
    m->data = data;
    m->data_cap = sizeof(JsIterData);
    return (Item){.map = m};
}

extern "C" void js_iterator_map_gc_trace(Map* map, gc_heap_t* gc) {
    if (!map || !gc || map->type_id != LMD_TYPE_MAP ||
            map->map_kind != MAP_KIND_ITERATOR || !map->data) return;
    JsIterData* data = (JsIterData*)map->data;
    // Lightweight iterator state is native side storage; retain its iterable
    // for the lifetime of the managed iterator wrapper.
    gc_mark_item(gc, data->source.item);
}

// v95: Check if Array.prototype[Symbol.iterator] has been overridden or deleted.
// Returns: user-defined Item if overridden, ITEM_JS_UNDEFINED if deleted, ItemNull if still default.
Item js_check_array_sym_iterator() {
    Item array_proto = js_get_intrinsic_prototype_for_class(JS_CLASS_ARRAY);
    if (get_type_id(array_proto) != LMD_TYPE_MAP) return ItemNull;
    Item sym_iter = ItemNull;
    String* symbol_key = it2s(js_well_known_symbol_key(1));
    JsShapeSlotStatus status = symbol_key
        ? js_own_shape_slot_status_name_id(array_proto, property_key_id(symbol_key),
            &sym_iter, NULL)
        : JS_SHAPE_SLOT_ABSENT;
    if (status == JS_SHAPE_SLOT_ABSENT) return ItemNull;  // not present on Array.prototype — use default
    if (status == JS_SHAPE_SLOT_DELETED) return make_js_undefined();  // deleted
    Item default_iterator = js_intrinsic_binding_get(
        JS_BUILTIN_OWNER_ARRAY_ITERATOR_INTERNAL, "[Symbol.iterator]", 17);
    return sym_iter.item == default_iterator.item
        ? ItemNull : sym_iter;
}

// Get the iterator for an iterable (GetIterator, ES spec §7.4.1)
static Item js_iterator_cache_next_method(Item iterator) {
    RootFrame roots(2);
    Rooted<Item> iterator_root(roots, iterator);
    Rooted<Item> next_root(roots, ItemNull);
    // A freshly returned iterator may have no published owner yet; keep it
    // exact while property lookup and cache publication can trigger GC.
    iterator = iterator_root.get();
    TypeId it_tid = get_type_id(iterator);
    if (it_tid != LMD_TYPE_MAP && it_tid != LMD_TYPE_ELEMENT && !js_is_js_array(iterator)) {
        return js_throw_type_error("iterator is not an object");
    }
    if (it_tid == LMD_TYPE_MAP && iterator.map->map_kind == MAP_KIND_ITERATOR) {
        // Lightweight built-in iterators intentionally do not materialize a
        // public `next` property.  js_iterator_step dispatches them by
        // MAP_KIND_ITERATOR, so caching a property here would reject valid
        // iterators returned from user @@iterator wrappers, which shows up in
        // hot-reload test262 batches as TypedArray construction failures.
        return ItemNull;
    }
    next_root.set(js_get_key_default(iterator_root.get(),
        (Item){.item = s2it(heap_create_name("next", 4))}));
    if (item_is_error(next_root.get())) return next_root.get();
    if (!js_is_callable(next_root.get())) {
        return js_throw_type_error("iterator next is not a function");
    }
    Item cache_key = (Item){.item = s2it(heap_create_name("__iter_next__", 13))};
    Item set_result = js_set_key_default(iterator_root.get(), cache_key, next_root.get());
    return item_is_error(set_result) ? set_result : ItemNull;
}

static Item js_get_iterator_impl(Item iterable, bool cache_next) {
    TypeId tid = get_type_id(iterable);

    // null and undefined are never iterable — throw TypeError immediately
    if (tid == LMD_TYPE_NULL || iterable.item == ITEM_JS_UNDEFINED) {
        char msg[128];
        snprintf(msg, sizeof(msg), "%s is not iterable",
                 tid == LMD_TYPE_NULL ? "null" : "undefined");
        return js_throw_type_error(msg);
    }

    // Arrays: wrap in lightweight array iterator (v28: MAP_KIND_ITERATOR)
    // v95: But first check if Array.prototype[Symbol.iterator] has been overridden or deleted
    if (js_is_js_array(iterable)) {
        if (g_array_sym_iter_ever_set) {
            Item sym_override = js_check_array_sym_iterator();
            if (sym_override.item == ITEM_JS_UNDEFINED) {
                // Symbol.iterator was deleted — array is not iterable
                return js_throw_type_error("[object Array] is not iterable");
            }
            if (sym_override.item != ItemNull.item) {
                // User-defined Symbol.iterator — call it with the array as 'this'
                JS_ASSIGN_OR_RETURN(iterator, js_call_function(sym_override, iterable, NULL, 0));
                TypeId it_tid = get_type_id(iterator);
                if (it_tid != LMD_TYPE_MAP && it_tid != LMD_TYPE_ELEMENT &&
                        !js_is_js_array(iterator)) {
                    return js_throw_type_error("iterator is not an object");
                }
                if (cache_next) {
                    JS_ASSIGN_OR_RETURN(cache_status, js_iterator_cache_next_method(iterator));
                }
                return iterator;
            }
        }
        if (!js_array_iterator_next_is_default()) {
            Item iterator = js_create_array_iterator_object(iterable, 1);
            if (cache_next) {
                JS_ASSIGN_OR_RETURN(cache_status, js_iterator_cache_next_method(iterator));
            }
            return iterator;
        }
        return js_create_array_iterator(iterable);
    }

    // Strings: wrap in lightweight string iterator (v28: MAP_KIND_ITERATOR)
    if (tid == LMD_TYPE_STRING) {
        return js_create_string_iterator(iterable);
    }

    // Generators: return as-is (they implement iterator protocol natively)
    if (js_is_generator(iterable)) {
        return iterable;
    }

    // Typed arrays: wrap in lightweight typed array iterator (v28: MAP_KIND_ITERATOR)
    if (js_is_typed_array(iterable)) {
        return js_create_typed_array_iterator(iterable);
    }

    // Map/Set collections and ordinary objects with an own/prototype iterator
    // share the same property-based fallback; omitting OBJECT skipped custom
    // Symbol.iterator methods and converted their abrupt completion to a value.
    if (tid == LMD_TYPE_MAP || tid == LMD_TYPE_OBJECT) {
        // Check for [Symbol.iterator]()
        JS_ASSIGN_OR_RETURN(iter_factory, js_get_key_default(iterable, js_well_known_symbol_key(1)));
        if (js_is_callable(iter_factory)) {
            JS_ASSIGN_OR_RETURN(iterator, js_call_function(iter_factory, iterable, NULL, 0));
            TypeId it_tid = get_type_id(iterator);
            if (it_tid != LMD_TYPE_MAP && it_tid != LMD_TYPE_ELEMENT && !js_is_js_array(iterator)) {
                return js_throw_type_error("iterator is not an object");
            }
            if (cache_next) {
                JS_ASSIGN_OR_RETURN(cache_status, js_iterator_cache_next_method(iterator));
            }
            return iterator;
        }

        // Check for .next() method (already an iterator)
        String* next_key = heap_create_name("next", 4);
        Item next_fn = js_get_key_default(iterable, (Item){.item = s2it(next_key)});
        if (js_is_callable(next_fn)) {
            if (cache_next) {
                Item cache_key = (Item){.item = s2it(heap_create_name("__iter_next__", 13))};
                JS_ASSIGN_OR_RETURN(set_result, js_set_key_default(iterable, cache_key, next_fn));
            }
            return iterable;
        }
    }
    if (tid == LMD_TYPE_ELEMENT) {
        // Check for [Symbol.iterator]()
        JS_ASSIGN_OR_RETURN(iter_factory, js_get_key_default(iterable, js_well_known_symbol_key(1)));
        if (js_is_callable(iter_factory)) {
            JS_ASSIGN_OR_RETURN(iterator, js_call_function(iter_factory, iterable, NULL, 0));
            TypeId it_tid = get_type_id(iterator);
            if (it_tid != LMD_TYPE_MAP && it_tid != LMD_TYPE_ELEMENT && !js_is_js_array(iterator)) {
                return js_throw_type_error("iterator is not an object");
            }
            if (cache_next) {
                JS_ASSIGN_OR_RETURN(cache_status, js_iterator_cache_next_method(iterator));
            }
            return iterator;
        }
    }

    if (tid == LMD_TYPE_BOOL || tid == LMD_TYPE_INT ||
        tid == LMD_TYPE_FLOAT || tid == LMD_TYPE_SYMBOL ||
        js_is_bigint_egress(iterable)) {
        JS_ASSIGN_OR_RETURN(wrapped, js_to_object(iterable));
        JS_ASSIGN_OR_RETURN(iter_factory, js_get_key_default(wrapped, js_well_known_symbol_key(1)));
        if (js_is_callable(iter_factory)) {
            JS_ASSIGN_OR_RETURN(iterator, js_call_function(iter_factory, wrapped, NULL, 0));
            TypeId it_tid = get_type_id(iterator);
            if (it_tid != LMD_TYPE_MAP && it_tid != LMD_TYPE_ELEMENT && !js_is_js_array(iterator)) {
                return js_throw_type_error("iterator is not an object");
            }
            if (cache_next) {
                JS_ASSIGN_OR_RETURN(cache_status, js_iterator_cache_next_method(iterator));
            }
            return iterator;
        }
    }

    // Non-iterable value — throw TypeError
    {
        char msg[128];
        const char* type_str = "object";
        if (tid == LMD_TYPE_INT || tid == LMD_TYPE_FLOAT)
            type_str = "number";
        else if (js_is_bigint_egress(iterable))
            type_str = "bigint";
        else if (tid == LMD_TYPE_BOOL)
            type_str = "boolean";
        else if (tid == LMD_TYPE_SYMBOL)
            type_str = "symbol";
        snprintf(msg, sizeof(msg), "%s is not iterable", type_str);
        return js_throw_type_error(msg);
    }
}

extern "C" Item js_get_iterator(Item iterable) {
    return js_get_iterator_impl(iterable, true);
}

extern "C" Item js_get_async_iterator(Item iterable) {
    TypeId tid = get_type_id(iterable);
    if (tid == LMD_TYPE_MAP || tid == LMD_TYPE_ELEMENT || js_is_js_array(iterable)) {
        JS_ASSIGN_OR_RETURN(iter_factory, js_get_key_default(iterable, js_well_known_symbol_key(5)));
        if (js_is_callable(iter_factory)) {
            JS_ASSIGN_OR_RETURN(iterator, js_call_function(iter_factory, iterable, NULL, 0));
            TypeId it_tid = get_type_id(iterator);
            if (it_tid != LMD_TYPE_MAP && it_tid != LMD_TYPE_ELEMENT && !js_is_js_array(iterator)) {
                return js_throw_type_error("async iterator is not an object");
            }
            return iterator;
        }
    }
    return js_get_iterator(iterable);
}

extern "C" Item js_get_iterator_lazy(Item iterable) {
    return js_get_iterator_impl(iterable, false);
}

// IteratorStep: call iterator.next(), return result {done, value}
// Returns JS_ITER_DONE_SENTINEL on completion (done=true) or the value on success.
// The sentinel is a unique bit pattern (type tag 0x7F) that cannot collide with
// any valid JS value including null, undefined, false, 0, or empty string.
extern "C" Item js_iterator_step(Item iterator) {
    RootFrame roots(5);
    Rooted<Item> iterator_root(roots, iterator);
    Rooted<Item> source_root(roots, ItemNull);
    Rooted<Item> next_fn_root(roots, ItemNull);
    Rooted<Item> result_root(roots, ItemNull);
    Rooted<Item> temp_root(roots, ItemNull);
    // Iterator protocol calls are allocation points. Keep the iterator, source,
    // callback and result in precise roots until the returned value is published.
    // Safety: if iterator is null (e.g. from a failed js_get_iterator), return done
    if (get_type_id(iterator_root.get()) == LMD_TYPE_NULL || iterator_root.get().item == ITEM_JS_UNDEFINED)
        return (Item){.item = JS_ITER_DONE_SENTINEL};

    // v28: MAP_KIND_ITERATOR fast path — direct memory access, zero property lookups
    if (get_type_id(iterator_root.get()) == LMD_TYPE_MAP && iterator_root.get().map->map_kind == MAP_KIND_ITERATOR) {
        Map* m = iterator_root.get().map;
        JsIterData* d = (JsIterData*)m->data;
        int64_t idx = d->index;

        if (m->type == (void*)&js_array_iter_marker) {
            // Array iterator: read live observable length, then direct index get.
            source_root.set(d->source);
            JS_ASSIGN_OR_RETURN(len_item, js_array_iterator_source_length(source_root.get()));
            int64_t len = it2i(len_item);
            if (idx >= len) return (Item){.item = JS_ITER_DONE_SENTINEL};
            result_root.set(js_get_reference(source_root.get(), (Item){.item = i2it((int)idx)}));
            d->index = idx + 1;
            return result_root.get();
        }
        if (m->type == (void*)&js_string_iter_marker) {
            // String iterator: UTF-8 code point advance
            source_root.set(d->source);
            String* str = it2s(source_root.get());
            if (idx >= (int64_t)str->len) return (Item){.item = JS_ITER_DONE_SENTINEL};
            unsigned char lead = (unsigned char)str->chars[idx];
            int cp_len = 1;
            if (lead >= 0xF0 && idx + 4 <= (int64_t)str->len)      cp_len = 4;
            else if (lead >= 0xE0 && idx + 3 <= (int64_t)str->len)  cp_len = 3;
            else if (lead >= 0xC0 && idx + 2 <= (int64_t)str->len)  cp_len = 2;
            int total_len = cp_len;
            // combine WTF-8/CESU-8 surrogate pairs
            if (cp_len == 3 && lead == 0xED && idx + 1 < (int64_t)str->len) {
                unsigned char second = (unsigned char)str->chars[idx + 1];
                if (second >= 0xA0 && second <= 0xAF) {
                    int next = (int)idx + 3;
                    if (next + 2 < (int)str->len &&
                        (unsigned char)str->chars[next] == 0xED) {
                        unsigned char ns = (unsigned char)str->chars[next + 1];
                        if (ns >= 0xB0 && ns <= 0xBF) {
                            total_len = 6;
                        }
                    }
                }
            }
            temp_root.set((Item){.item = s2it(heap_create_name(str->chars + idx, total_len))});
            d->index = idx + total_len;
            return temp_root.get();
        }
        if (m->type == (void*)&js_typed_array_iter_marker) {
            // Typed array iterator: direct index read + increment
            source_root.set(d->source);
            if (js_typed_array_is_out_of_bounds_item(source_root.get())) {
                return js_throw_type_error("Cannot perform %TypedArray%.prototype iterator on an out-of-bounds ArrayBuffer");
            }
            int len = js_typed_array_length(source_root.get());
            if (idx >= len) return (Item){.item = JS_ITER_DONE_SENTINEL};
            result_root.set(js_typed_array_get(source_root.get(), (Item){.item = i2it((int)idx)}));
            if (item_is_error(result_root.get())) return result_root.get();
            d->index = idx + 1;
            return result_root.get();
        }
    }

    TypeId iterator_tid = get_type_id(iterator_root.get());
    if (iterator_tid != LMD_TYPE_MAP && iterator_tid != LMD_TYPE_ELEMENT && !js_is_generator(iterator_root.get())) {
        return js_throw_type_error("iterator next is not a function");
    }

    if (iterator_tid == LMD_TYPE_MAP) {
        // Legacy synthetic array iterator (property-based, for backwards compatibility)
        bool has_arr = false;
        Item arr_val = js_map_shape_lookup(iterator_root.get().map, "__arr__", 7, &has_arr);
        if (has_arr) {
            bool has_idx = false;
            Item idx_val = js_map_shape_lookup(iterator_root.get().map, "__idx__", 7, &has_idx);
            int idx = has_idx ? (int)it2i(idx_val) : 0;
            source_root.set(arr_val);
            JS_ASSIGN_OR_RETURN(len_item, js_array_iterator_source_length(source_root.get()));
            int64_t len = it2i(len_item);
            if (idx >= len) return (Item){.item = JS_ITER_DONE_SENTINEL};  // done
            result_root.set(js_get_reference(source_root.get(), (Item){.item = i2it(idx)}));
            source_root.set((Item){.item = s2it(heap_create_name("__idx__", 7))});
            JS_ASSIGN_OR_RETURN(set_result, js_set_key_default(iterator_root.get(), source_root.get(),
                (Item){.item = i2it(idx + 1)}));
            return result_root.get();
        }

        // Synthetic string iterator
        bool has_str = false;
        Item str_val = js_map_shape_lookup(iterator_root.get().map, "__str__", 7, &has_str);
        if (has_str && get_type_id(str_val) == LMD_TYPE_STRING) {
            bool has_idx = false;
            Item idx_val = js_map_shape_lookup(iterator_root.get().map, "__idx__", 7, &has_idx);
            int idx = has_idx ? (int)it2i(idx_val) : 0;
            source_root.set(str_val);
            String* str = it2s(source_root.get());
            if (idx >= (int)str->len) return (Item){.item = JS_ITER_DONE_SENTINEL};  // done
            // advance by full UTF-8 code point (1-4 bytes)
            unsigned char lead = (unsigned char)str->chars[idx];
            int cp_len = 1;
            if (lead >= 0xF0 && idx + 4 <= (int)str->len)      cp_len = 4;
            else if (lead >= 0xE0 && idx + 3 <= (int)str->len)  cp_len = 3;
            else if (lead >= 0xC0 && idx + 2 <= (int)str->len)  cp_len = 2;
            int total_len = cp_len;
            // combine WTF-8/CESU-8 surrogate pairs: high surrogate (ED A0-AF xx) + low surrogate (ED B0-BF xx)
            if (cp_len == 3 && lead == 0xED && idx + 1 < (int)str->len) {
                unsigned char second = (unsigned char)str->chars[idx + 1];
                if (second >= 0xA0 && second <= 0xAF) {
                    // high surrogate — check for following low surrogate
                    int next = idx + 3;
                    if (next + 2 < (int)str->len &&
                        (unsigned char)str->chars[next] == 0xED) {
                        unsigned char ns = (unsigned char)str->chars[next + 1];
                        if (ns >= 0xB0 && ns <= 0xBF) {
                            total_len = 6;  // combine both surrogates
                        }
                    }
                }
            }
            temp_root.set((Item){.item = s2it(heap_create_name(str->chars + idx, total_len))});
            source_root.set((Item){.item = s2it(heap_create_name("__idx__", 7))});
            JS_ASSIGN_OR_RETURN(set_result, js_set_key_default(iterator_root.get(), source_root.get(),
                (Item){.item = i2it(idx + total_len)}));
            return temp_root.get();
        }

        // Synthetic typed array iterator
        bool has_tarr = false;
        Item tarr_val = js_map_shape_lookup(iterator_root.get().map, "__tarr__", 8, &has_tarr);
        if (has_tarr) {
            bool has_done = false;
            Item done_val = js_map_shape_lookup(iterator_root.get().map, "__done__", 8, &has_done);
            if (has_done && get_type_id(done_val) == LMD_TYPE_BOOL && it2b(done_val)) {
                return (Item){.item = JS_ITER_DONE_SENTINEL};
            }
            source_root.set(tarr_val);
            if (js_typed_array_is_out_of_bounds_item(source_root.get())) {
                return js_throw_type_error("Cannot perform %TypedArray%.prototype iterator on an out-of-bounds ArrayBuffer");
            }
            bool has_index = false;
            Item idx_val = js_map_shape_lookup(iterator_root.get().map, "__index__", 9, &has_index);
            if (!has_index) idx_val = js_map_shape_lookup(iterator_root.get().map, "__idx__", 7, &has_index);
            int idx = has_index ? (int)it2i(idx_val) : 0;
            bool has_kind = false;
            Item kind_val = js_map_shape_lookup(iterator_root.get().map, "__kind__", 8, &has_kind);
            int kind = has_kind ? (int)it2i(kind_val) : 1;
            int len = js_typed_array_length(source_root.get());
            if (idx >= len) {
                next_fn_root.set((Item){.item = s2it(heap_create_name("__done__", 8))});
                JS_ASSIGN_OR_RETURN(set_result, js_set_key_default(iterator_root.get(), next_fn_root.get(),
                    (Item){.item = b2it(true)}));
                return (Item){.item = JS_ITER_DONE_SENTINEL};
            }
            next_fn_root.set((Item){.item = s2it(heap_create_name("__index__", 9))});
            JS_ASSIGN_OR_RETURN(set_result, js_set_key_default(iterator_root.get(), next_fn_root.get(),
                (Item){.item = i2it(idx + 1)}));
            if (kind == 0) {
                return (Item){.item = i2it(idx)};
            }
            result_root.set(js_typed_array_get(source_root.get(), (Item){.item = i2it(idx)}));
            if (item_is_error(result_root.get())) return result_root.get();
            if (result_root.get().item == ITEM_NULL) result_root.set(make_js_undefined());
            if (kind == 2) {
                temp_root.set(js_array_new(2));
                temp_root.get().array->items[0] = (Item){.item = i2it(idx)};
                js_array_store_owned(temp_root.get().array, 1, result_root.get());
                return temp_root.get();
            }
            return result_root.get();
        }
    }

    // Generator: call js_generator_next
    if (js_is_generator(iterator_root.get())) {
        result_root.set(js_generator_next(iterator_root.get(), make_js_undefined()));
        if (item_is_error(result_root.get())) return result_root.get();
        source_root.set((Item){.item = s2it(heap_create_name("done", 4))});
        temp_root.set(js_get_key_default(result_root.get(), source_root.get()));
        if (item_is_error(temp_root.get())) return temp_root.get();
        if (js_is_truthy(temp_root.get())) return (Item){.item = JS_ITER_DONE_SENTINEL};
        source_root.set((Item){.item = s2it(heap_create_name("value", 5))});
        return js_get_key_default(result_root.get(), source_root.get());
    }

    // Generic iterator: call .next()
    if (get_type_id(iterator_root.get()) == LMD_TYPE_MAP || get_type_id(iterator_root.get()) == LMD_TYPE_ELEMENT) {
        bool found_cached = false;
        if (get_type_id(iterator_root.get()) == LMD_TYPE_MAP) {
            next_fn_root.set(js_map_shape_lookup(iterator_root.get().map, "__iter_next__", 13, &found_cached));
        }
        if (!found_cached) {
            source_root.set((Item){.item = s2it(heap_create_name("next", 4))});
            next_fn_root.set(js_get_key_default(iterator_root.get(), source_root.get()));
            if (item_is_error(next_fn_root.get())) return next_fn_root.get();
        }
        if (js_is_callable(next_fn_root.get())) {
            result_root.set(js_call_function(next_fn_root.get(), iterator_root.get(), NULL, 0));
            if (item_is_error(result_root.get())) return result_root.get();
            TypeId result_tid = get_type_id(result_root.get());
            if (result_tid != LMD_TYPE_MAP && result_tid != LMD_TYPE_ELEMENT &&
                result_tid != LMD_TYPE_ARRAY && result_tid != LMD_TYPE_FUNC &&
                result_tid != LMD_TYPE_OBJECT && result_tid != LMD_TYPE_VMAP) {
                return js_throw_type_error("iterator result is not an object");
            }
            source_root.set((Item){.item = s2it(heap_create_name("done", 4))});
            temp_root.set(js_get_key_default(result_root.get(), source_root.get()));
            if (item_is_error(temp_root.get())) return temp_root.get();
            if (js_is_truthy(temp_root.get())) return (Item){.item = JS_ITER_DONE_SENTINEL};
            source_root.set((Item){.item = s2it(heap_create_name("value", 5))});
            return js_get_key_default(result_root.get(), source_root.get());
        }
        if (js_is_diagnose_enabled()) {
            bool has_array = false, has_index = false, has_kind = false;
            if (get_type_id(iterator_root.get()) == LMD_TYPE_MAP) {
                js_map_shape_lookup_ext(iterator_root.get().map, "__array__", 9, &has_array);
                js_map_shape_lookup_ext(iterator_root.get().map, "__index__", 9, &has_index);
                js_map_shape_lookup_ext(iterator_root.get().map, "__kind__", 8, &has_kind);
            }
            log_warn("js-diagnose: iterator-step-missing-next tid=%d map_kind=%d next_tid=%d has_array=%d has_index=%d has_kind=%d",
                (int)iterator_tid,
                get_type_id(iterator_root.get()) == LMD_TYPE_MAP ? (int)iterator_root.get().map->map_kind : -1,
                (int)get_type_id(next_fn_root.get()),
                has_array ? 1 : 0, has_index ? 1 : 0, has_kind ? 1 : 0);
        }
    }

    return js_throw_type_error("iterator next is not a function");
}

// IteratorClose: call iterator.return() if it exists (ES spec §7.4.6)
extern "C" Item js_iterator_close(Item iterator) {
    RootFrame roots(3);
    Rooted<Item> iterator_root(roots, iterator);
    Rooted<Item> return_fn_root(roots, ItemNull);
    Rooted<Item> result_root(roots, ItemNull);
    // A custom .return() may collect before its result is validated.
    // Generators: call js_generator_return
    if (js_is_generator(iterator_root.get())) {
        // Send a return signal to the generator
        js_generator_return(iterator_root.get(), make_js_undefined());
        return make_js_undefined();
    }

    // Generic iterator: call .return() if available
    TypeId tid = get_type_id(iterator_root.get());

    // Built-in fast Array/String/TypedArray iterators (MAP_KIND_ITERATOR) use a
    // 1-byte sentinel as their Map `type` (not a real TypeMap), so a generic
    // property lookup would read it out of bounds. These iterators have no
    // `return` method, so per spec IteratorClose completes without doing anything.
    if (iterator_root.get().map &&
        (tid == LMD_TYPE_MAP || tid == LMD_TYPE_ELEMENT || tid == LMD_TYPE_VMAP || tid == LMD_TYPE_OBJECT) &&
        iterator_root.get().map->map_kind == MAP_KIND_ITERATOR) {
        return make_js_undefined();
    }

    if (tid == LMD_TYPE_MAP || tid == LMD_TYPE_ELEMENT || tid == LMD_TYPE_VMAP || tid == LMD_TYPE_OBJECT) {
        return_fn_root.set((Item){.item = s2it(heap_create_name("return", 6))});
        return_fn_root.set(js_get_key_default(iterator_root.get(), return_fn_root.get()));
        if (item_is_error(return_fn_root.get())) return return_fn_root.get();
        if (js_is_callable(return_fn_root.get())) {
            result_root.set(js_call_function(return_fn_root.get(), iterator_root.get(), NULL, 0));
            if (item_is_error(result_root.get())) return result_root.get();
            TypeId result_tid = get_type_id(result_root.get());
            if (result_tid != LMD_TYPE_MAP && result_tid != LMD_TYPE_ELEMENT &&
                result_tid != LMD_TYPE_ARRAY && result_tid != LMD_TYPE_FUNC &&
                result_tid != LMD_TYPE_OBJECT && result_tid != LMD_TYPE_VMAP) {
                return js_throw_type_error("Iterator result is not an object");
            }
        } else {
            TypeId rtid = get_type_id(return_fn_root.get());
            if (rtid != LMD_TYPE_UNDEFINED && rtid != LMD_TYPE_NULL && return_fn_root.get().item != ITEM_JS_UNDEFINED) {
                return js_throw_type_error("iterator return is not a function");
            }
        }
    }
    return make_js_undefined();
}

// collect remaining iterator values into a new array (for rest elements in destructuring)
extern "C" Item js_iterator_collect_rest(Item iterator) {
    RootFrame roots(3);
    Rooted<Item> iterator_root(roots, iterator);
    Rooted<Item> array_root(roots, js_array_new(0));
    Rooted<Item> value_root(roots, ItemNull);
    // The loop allocates while stepping and appending, so neither owner may
    // rely on the native stack between iterations.
    while (true) {
        value_root.set(js_iterator_step(iterator_root.get()));
        if (item_is_error(value_root.get())) return value_root.get();
        if (value_root.get().item == JS_ITER_DONE_SENTINEL) break;
        // Rest destructuring builds a JS array; use the JS array path so
        // boxed Number elements keep dense-slot invariants after migration.
        js_array_push_item_direct(array_root.get().array, value_root.get());
    }
    return array_root.get();
}

// v15: Convert an iterable to an array. If it's a generator, drain it.
// If it's already an array, return it as-is.
extern "C" Item js_iterable_to_array(Item iterable) {
    if (item_is_error(iterable)) return iterable;

    // null and undefined are not iterable — throw TypeError (ES spec GetIterator step 1)
    TypeId tid = get_type_id(iterable);
    if (tid == LMD_TYPE_NULL || iterable.item == ITEM_JS_UNDEFINED) {
        return js_throw_type_error(tid == LMD_TYPE_NULL
            ? "null is not iterable (cannot destructure)"
            : "undefined is not iterable (cannot destructure)");
    }

    RootFrame roots(4);
    Rooted<Item> iterable_root(roots, iterable);
    Rooted<Item> array_root(roots, ItemNull);
    Rooted<Item> iterator_root(roots, ItemNull);
    Rooted<Item> temp_root(roots, ItemNull);
    // Iterable conversion allocates while draining the source. Native locals
    // are not precise roots, so keep the source, iterator, destination, and
    // current compound value live until each is published into the result.

    // Typed arrays (Uint8Array, Int32Array, etc.): convert to plain array of boxed numbers
    if (js_is_typed_array(iterable_root.get())) {
        int len = js_typed_array_length(iterable_root.get());
        array_root.set(js_array_new(0));
        for (int i = 0; i < len; i++) {
            JS_ASSIGN_OR_RETURN(elem, js_typed_array_get(iterable_root.get(), (Item){.item = i2it(i)}));
            js_array_push_item_direct(array_root.get().array, elem);
        }
        return array_root.get();
    }

    // Check if it's a generator object
    if (js_is_generator(iterable_root.get())) {
        array_root.set(js_array_new(0));
        for (int safety = 0; safety < 100000; safety++) {
            temp_root.set(js_generator_next(iterable_root.get(), make_js_undefined()));
            if (item_is_error(temp_root.get())) return temp_root.get();
            // Extract .done and .value from result
            String* done_key = heap_create_name("done", 4);
            JS_ASSIGN_OR_RETURN(done_item, js_get_key_default(temp_root.get(), (Item){.item = s2it(done_key)}));
            if (get_type_id(done_item) == LMD_TYPE_BOOL && it2b(done_item)) break;
            String* val_key = heap_create_name("value", 5);
            JS_ASSIGN_OR_RETURN(value, js_get_key_default(temp_root.get(), (Item){.item = s2it(val_key)}));
            js_array_push_item_direct(array_root.get().array, value);
        }
        return array_root.get();
    }

    // Check if it's a Map/Set collection — convert to array directly
    if (get_type_id(iterable_root.get()) == LMD_TYPE_MAP) {
        JsCollectionData* cd = js_get_collection_data(iterable_root.get());
        if (cd) {
            size_t count = hashmap_count(cd->hmap);
            array_root.set(js_array_new((int)count));
            JsCollectionOrderNode* node = cd->order_head;
            int idx = 0;
            if (cd->type == JS_COLLECTION_MAP) {
                // Map: array of [key, value] pairs
                while (node) {
                    temp_root.set(js_array_new(2));
                    JS_ASSIGN_OR_RETURN(set_result, js_elements_set_int(temp_root.get(), 0, node->key));
                    JS_ASSIGN_OR_RETURN_INTO(set_result, js_elements_set_int(temp_root.get(), 1, node->value));
                    JS_ASSIGN_OR_RETURN_INTO(set_result, js_elements_set_int(array_root.get(), idx, temp_root.get()));
                    idx++;
                    node = node->next;
                }
            } else {
                // Set: array of values
                while (node) {
                    JS_ASSIGN_OR_RETURN(set_result, js_elements_set_int(array_root.get(), idx, node->key));
                    idx++;
                    node = node->next;
                }
            }
            return array_root.get();
        }
    }

    // String: split into individual characters
    if (get_type_id(iterable_root.get()) == LMD_TYPE_STRING) {
        String* str = it2s(iterable_root.get());
        if (str) {
            array_root.set(js_array_new(0));
            int i = 0;
            while (i < (int)str->len) {
                unsigned char lead = (unsigned char)str->chars[i];
                int cp_len = 1;
                if (lead >= 0xF0 && i + 4 <= (int)str->len)      cp_len = 4;
                else if (lead >= 0xE0 && i + 3 <= (int)str->len)  cp_len = 3;
                else if (lead >= 0xC0 && i + 2 <= (int)str->len)  cp_len = 2;
                int total_len = cp_len;
                // combine WTF-8/CESU-8 surrogate pairs
                if (cp_len == 3 && lead == 0xED && i + 1 < (int)str->len) {
                    unsigned char second = (unsigned char)str->chars[i + 1];
                    if (second >= 0xA0 && second <= 0xAF) {
                        int next = i + 3;
                        if (next + 2 < (int)str->len &&
                            (unsigned char)str->chars[next] == 0xED) {
                            unsigned char ns = (unsigned char)str->chars[next + 1];
                            if (ns >= 0xB0 && ns <= 0xBF) {
                                total_len = 6;
                            }
                        }
                    }
                }
                String* ch = heap_create_name(str->chars + i, total_len);
                Item ch_item = (Item){.item = s2it(ch)};
                js_array_push_item_direct(array_root.get().array, ch_item);
                i += total_len;
            }
            return array_root.get();
        }
    }

    // IterableToArray must still observe the iterator protocol for arrays:
    // test262 mutates ArrayIteratorPrototype.next and relies on holes being
    // read through iterator semantics.  The batch crash fix is limited to
    // using the lazy getter here, so lightweight built-in iterators returned
    // from user @@iterator wrappers are stepped by js_iterator_step instead of
    // being rejected for not materializing an own `.next` property.
    iterator_root.set(js_get_iterator_lazy(iterable_root.get()));
    if (item_is_error(iterator_root.get())) return iterator_root.get();
    array_root.set(js_array_new(0));
    for (int safety = 0; safety < 100000; safety++) {
        JS_ASSIGN_OR_RETURN(value, js_iterator_step(iterator_root.get()));
        if (value.item == JS_ITER_DONE_SENTINEL) break;
        js_array_push_item_direct(array_root.get().array, value);
    }
    return array_root.get();
}

// =============================================================================
// v14: Promise Runtime
// =============================================================================

// No-await async recursion allocates a promise before the body runs; keep this
// above js_call_function's depth guard so stack overflow wins over table exhaustion.
#define JS_MAX_PROMISES JS_PROMISE_STATE_MAX
#define js_promises (js_runtime_state.promises.records)
#define js_promise_count (js_runtime_state.promises.count)
#define js_promise_unhandled_epoch (js_runtime_state.promises.unhandled_epoch)
#define js_promise_unhandled_queue (js_runtime_state.promises.unhandled_queue)
#define js_promise_unhandled_queue_count (js_runtime_state.promises.unhandled_queue_count)
#define js_promise_unhandled_strict (js_runtime_state.promises.unhandled_strict)
#define js_domain_current (js_runtime_state.promises.domain_current)
#define js_domain_namespace (js_runtime_state.promises.domain_namespace)
#define js_domain_stack_slots (js_runtime_state.promises.domain_stack_slots)
#define js_domain_stack_state (js_runtime_state.promises.domain_stack)
#define js_domain_stack (js_domain_stack_state.roots.slots)
#define js_domain_stack_count (js_domain_stack_state.depth)

// global-ok: CLI policy is selected before the first EvalContext exists.
// Each context snapshots this setting during creation; executing code only
// reads and writes its own promise state.
static bool js_promise_bootstrap_unhandled_strict = false;

extern "C" bool js_promise_initial_unhandled_rejections_strict(void) {
    return js_promise_bootstrap_unhandled_strict;
}

extern "C" Item js_async_hooks_get_current_resource(void);
extern "C" Item js_async_hooks_stamp_resource(Item resource, const char* type_chars, int type_len);
extern "C" Item js_async_hooks_enter_resource(Item resource);
extern "C" void js_async_hooks_restore_resource(Item previous);
extern "C" void js_async_hooks_emit_before_resource(Item resource);
extern "C" void js_async_hooks_emit_after_resource(Item resource);
extern "C" void js_async_hooks_emit_promise_resolve_resource(Item resource);

static bool js_domain_is_domain_item(Item domain) {
    TypeId type = get_type_id(domain);
    return type == LMD_TYPE_MAP || type == LMD_TYPE_ELEMENT;
}

static void js_domain_sync_visible_state(void) {
    // D5.3/D5.4.3: domain publication allocates process properties and the
    // visible stack array, so transient values must stay exact roots across
    // each allocation instead of relying only on the persistent state slots.
    RootFrame roots(3);
    Rooted<Item> domain_root(roots, js_domain_stack_count > 0
        ? js_domain_stack[js_domain_stack_count - 1]
        : make_js_undefined());
    Rooted<Item> process_root(roots, ItemNull);
    Rooted<Item> stack_root(roots, ItemNull);
    js_domain_current = js_domain_stack_count > 0 ? domain_root.get() : (Item){0};

    process_root.set(js_get_process_object_value());
    js_set_key_default(process_root.get(), (Item){.item = s2it(heap_create_name("domain", 6))},
        domain_root.get());

    if (js_domain_namespace.item != 0) {
        stack_root.set(js_array_new(0));
        for (int i = 0; i < js_domain_stack_count; i++) {
            js_array_push(stack_root.get(), js_domain_stack[i]);
        }
        js_set_key_default(js_domain_namespace,
            (Item){.item = s2it(heap_create_name("_stack", 6))}, stack_root.get());
    }
}

extern "C" Item js_domain_capture_stack(void) {
    RootFrame roots(1);
    Rooted<Item> stack_root(roots, js_array_new(0));
    for (int i = 0; i < js_domain_stack_count; i++) {
        js_array_push(stack_root.get(), js_domain_stack[i]);
    }
    return stack_root.get();
}

extern "C" Item js_domain_capture_async_stack(void) {
    // Error dispatch already trims the emitting domain; async callbacks must
    // inherit every remaining parent rather than only the active parent.
    return js_domain_capture_stack();
}

static void js_domain_apply_stack(Item stack) {
    RootFrame roots(1);
    Rooted<Item> stack_root(roots, stack);
    if (!js_root_range_ensure_registered(&js_domain_stack_state.roots)) return;
    js_item_stack_clear(&js_domain_stack_state);
    if (get_type_id(stack_root.get()) == LMD_TYPE_ARRAY) {
        int64_t len = js_array_length(stack_root.get());
        if (len > 64) len = 64;
        for (int64_t i = 0; i < len; i++) {
            Item domain = js_elements_get_int(stack_root.get(), i);
            if (js_domain_is_domain_item(domain)) {
                if (!js_item_stack_push(&js_domain_stack_state, domain)) break;
            }
        }
    } else if (js_domain_is_domain_item(stack_root.get())) {
        js_item_stack_push(&js_domain_stack_state, stack_root.get());
    }
    js_domain_sync_visible_state();
}

extern "C" Item js_domain_set_stack(Item stack) {
    RootFrame roots(2);
    Rooted<Item> stack_root(roots, stack);
    Rooted<Item> previous_root(roots, js_domain_capture_stack());
    js_domain_apply_stack(stack_root.get());
    return previous_root.get();
}

extern "C" void js_domain_restore_stack(Item previous) {
    RootFrame roots(1);
    Rooted<Item> previous_root(roots, previous);
    js_domain_apply_stack(previous_root.get());
}

static void js_domain_push(Item domain) {
    if (!js_domain_is_domain_item(domain)) return;
    if (js_domain_stack_count < 64) js_item_stack_push(&js_domain_stack_state, domain);
    js_domain_sync_visible_state();
}

extern "C" Item js_domain_get_current(void) {
    if (js_domain_current.item == 0) return make_js_undefined();
    return js_domain_current;
}

extern "C" Item js_domain_set_current(Item domain) {
    Item previous = js_domain_get_current();
    TypeId domain_type = get_type_id(domain);
    if (domain.item == 0 || domain_type == LMD_TYPE_UNDEFINED ||
        domain_type == LMD_TYPE_NULL || domain.item == ItemNull.item) {
        js_item_stack_clear(&js_domain_stack_state);
    } else {
        if (!js_root_range_ensure_registered(&js_domain_stack_state.roots)) return previous;
        js_item_stack_clear(&js_domain_stack_state);
        js_item_stack_push(&js_domain_stack_state, domain);
    }
    js_domain_sync_visible_state();
    return previous;
}

extern "C" void js_domain_restore(Item previous) {
    js_domain_set_current(previous);
}

extern "C" Item js_domain_call_function(Item domain, Item fn, Item this_val, Item* args, int arg_count) {
    Item previous = js_domain_set_stack(domain);
    Item result = js_call_function(fn, this_val, args, arg_count);
    js_domain_restore_stack(previous);
    return result;
}

static Item js_domain_emit_error_at(Item domain, Item error, int parent_count, bool* out_handled) {
    *out_handled = false;
    if (!js_domain_is_domain_item(domain)) return ItemNull;
    JS_ASSIGN_OR_RETURN(on_error, js_get_key_default(domain, (Item){.item = s2it(heap_create_name("__domain_error__", 16))}));
    if (!js_is_callable(on_error)) return ItemNull;

    if (parent_count < 0) parent_count = 0;
    if (parent_count > js_domain_stack_count) parent_count = js_domain_stack_count;
    js_item_stack_shrink(&js_domain_stack_state, parent_count);
    // An empty domain stack exposes process.domain as undefined; overriding it
    // with null here broke root error handlers and their inherited async context.
    js_domain_sync_visible_state();

    Item handler_result = js_call_function(on_error, domain, &error, 1);
    if (item_is_error(handler_result)) {
        Item thrown = js_error_lane_payload(handler_result);
        if (parent_count > 0) {
            Item parent = js_domain_stack[parent_count - 1];
            return js_domain_emit_error_at(parent, thrown, parent_count - 1, out_handled);
        }
        return js_throw_value(thrown);
    }
    *out_handled = true;
    return ItemNull;
}

static Item js_domain_emit_error(Item domain, Item error, bool* out_handled) {
    int parent_count = js_domain_stack_count;
    while (parent_count > 0 && js_domain_stack[parent_count - 1].item == domain.item) parent_count--;
    return js_domain_emit_error_at(domain, error, parent_count, out_handled);
}

extern "C" int js_domain_emit_current_error(Item error) {
    if (js_domain_stack_count <= 0) return 0;
    Item previous = js_domain_capture_stack();
    Item domain = js_domain_stack[js_domain_stack_count - 1];
    int parent_count = js_domain_stack_count;
    while (parent_count > 0 && js_domain_stack[parent_count - 1].item == domain.item) parent_count--;
    bool handled = false;
    Item emit_status = js_domain_emit_error_at(domain, error, parent_count, &handled);
    if (item_is_error(emit_status)) return 0;
    js_domain_restore_stack(previous);
    return handled ? 1 : 0;
}

extern "C" void js_promise_set_unhandled_rejections_mode(int64_t strict_mode) {
    if (!js_active_runtime_state) {
        js_promise_bootstrap_unhandled_strict = strict_mode != 0;
        return;
    }
    js_promise_unhandled_strict = strict_mode != 0;
}

extern "C" void js_promise_note_unhandled_listener_reset(void) {
    js_promise_unhandled_epoch++;
}

static bool js_promise_register_roots_once(int required_count) {
    JsPromiseRuntimeState* promise_state = &js_runtime_state.promises;
    if (!promise_state->records) {
        promise_state->records = (JsPromise*)mem_calloc(JS_MAX_PROMISES,
            sizeof(JsPromise), MEM_CAT_JS_RUNTIME);
        if (!promise_state->records) {
            log_error("promise: failed to allocate runtime table");
            return false;
        }
    }

    uint64_t epoch = js_get_heap_epoch();
    if (promise_state->record_roots_epoch != epoch) {
        promise_state->record_roots_epoch = epoch;
        promise_state->record_roots_count = 0;
    }

    if (required_count > JS_MAX_PROMISES) required_count = JS_MAX_PROMISES;
    // Register a promise slot before initialization; registering the whole
    // slab made every first Promise allocation pay for thousands of unused
    // root ranges and obscured the lifetime boundary of a newly published slot.
    for (int i = promise_state->record_roots_count; i < required_count; i++) {
        heap_register_gc_root_range((uint64_t*)&js_promises[i].result, 1);
        heap_register_gc_root_range((uint64_t*)js_promises[i].on_fulfilled, 8);
        heap_register_gc_root_range((uint64_t*)js_promises[i].on_rejected, 8);
        heap_register_gc_root_range((uint64_t*)js_promises[i].next_promise, 8);
        heap_register_gc_root_range((uint64_t*)js_promises[i].reaction_domain, 8);
        heap_register_gc_root_range((uint64_t*)&js_promises[i].reject_domain, 1);
        heap_register_gc_root_range((uint64_t*)&js_promises[i].wrapper, 1);
    }
    if (!js_root_range_ensure_registered(&promise_state->roots) ||
        !js_root_range_ensure_registered(&js_domain_stack_state.roots)) {
        return false;
    }
    promise_state->record_roots_count = required_count;
    return true;
}

static JsPromise* js_alloc_promise() {
    if (js_promise_count >= JS_MAX_PROMISES) {
        log_error("promise: exceeded max promises (%d)", JS_MAX_PROMISES);
        return NULL;
    }
    if (!js_promise_register_roots_once(js_promise_count + 1)) return NULL;
    if (js_promise_count >= JS_MAX_PROMISES - 16 && (js_promise_count % 16 == 0)) {
        log_info("promise: approaching capacity limit (%d/%d)", js_promise_count, JS_MAX_PROMISES);
    }
    JsPromise* p = &js_promises[js_promise_count++];
    p->type_id = LMD_TYPE_MAP;
    p->state = JS_PROMISE_PENDING;
    p->result = ItemNull;
    p->then_count = 0;
    memset(p->on_fulfilled, 0, sizeof(p->on_fulfilled));
    memset(p->on_rejected, 0, sizeof(p->on_rejected));
    memset(p->next_promise, 0, sizeof(p->next_promise));
    memset(p->reaction_domain, 0, sizeof(p->reaction_domain));
    memset(p->is_finally, 0, sizeof(p->is_finally));
    p->reject_domain = ItemNull;
    p->wrapper = ItemNull;
    p->wrapper_created = false;
    p->rejection_handled = false;
    p->unhandled_check_scheduled = false;
    p->unhandled_reported = false;
    p->unhandled_epoch = 0;
    return p;
}

static Item js_promise_to_item(JsPromise* p) {
    if (p->wrapper_created) return p->wrapper;

    RootFrame roots(4);
    Rooted<Item> wrapper_root(roots, ItemNull);
    Rooted<Item> key_root(roots, ItemNull);
    Rooted<Item> ctor_key_root(roots, ItemNull);
    Rooted<Item> promise_ctor_root(roots, ItemNull);
    // Create a map object that holds a reference to the promise by index
    int idx = (int)(p - js_promises);
    wrapper_root.set(js_new_object());
    String* key = heap_create_name("__promise_idx", 13);
    key_root.set((Item){.item = s2it(key)});
    js_set_key_default(wrapper_root.get(), key_root.get(), (Item){.item = i2it(idx)});
    js_class_stamp(wrapper_root.get(), JS_CLASS_PROMISE);
    // Set __proto__ to Promise.prototype so methods are inherited
    js_wrapper_set_proto(wrapper_root.get(), "Promise", 7);
    ctor_key_root.set((Item){.item = s2it(heap_create_name("constructor", 11))});
    promise_ctor_root.set(js_get_constructor((Item){.item = s2it(heap_create_name("Promise", 7))}));
    js_set_key_default(wrapper_root.get(), ctor_key_root.get(), promise_ctor_root.get());
    js_mark_non_enumerable(wrapper_root.get(), ctor_key_root.get());
    // promise async_hooks must use the Promise wrapper itself as the resource.
    js_async_hooks_stamp_resource(wrapper_root.get(), "PROMISE", 7);
    // Wrapper setup allocates before the static promise table publishes it.
    p->wrapper = wrapper_root.get();
    p->wrapper_created = true;
    return p->wrapper;
}

static JsPromise* js_get_promise(Item promise_obj) {
    if (get_type_id(promise_obj) != LMD_TYPE_MAP) return NULL;
    if (js_class_id(promise_obj) != JS_CLASS_PROMISE) return NULL;
    // promise identity is an internal own slot; prototype lookup on every map
    // could inspect accessors or heterogeneous shaped storage on non-promises.
    int64_t idx = -1;
    if (!js_hidden_own_int_index(promise_obj,
            "__promise_idx", 13, &idx)) return NULL;
    if (idx < 0 || idx >= js_promise_count) return NULL;
    return &js_promises[idx];
}

extern "C" const char* js_promise_state_name(Item promise_obj) {
    JsPromise* p = js_get_promise(promise_obj);
    if (!p) return NULL;
    if (p->state == JS_PROMISE_PENDING) return "pending";
    if (p->state == JS_PROMISE_FULFILLED) return "fulfilled";
    if (p->state == JS_PROMISE_REJECTED) return "rejected";
    return NULL;
}

extern "C" int js_promise_pending_count(void) {
    int count = 0;
    for (int i = 0; i < js_promise_count; i++) {
        if (js_promises[i].state == JS_PROMISE_PENDING) count++;
    }
    return count;
}

// Forward declaration — js_promise_settle is called recursively from microtask runner
static void js_promise_settle(JsPromise* p, JsPromiseState state, Item result);
static void js_promise_resolve_with_value(JsPromise* p, Item value);
static void js_promise_schedule_unhandled_check(JsPromise* p);
