enum JsPromiseCapabilityAction {
    JS_PROMISE_CAPABILITY_RESOLVE,
    JS_PROMISE_CAPABILITY_REJECT
};
static Item js_all_resolve_element(Item counter_obj, Item index_item, Item result_item, Item value);
