extern "C" Item js_p5_chain_dynamic_import(Item awaited, Item namespace_obj) {
    int slot = g_p5_next_slot++ % P5_SLOTS;
    g_p5_slot_namespace[slot] = namespace_obj;
    Item handler = js_new_native_function(g_p5_thunk_fns[slot]);
    return js_promise_then(awaited, handler, ItemNull);
}

// =============================================================================
// node:vm — code execution in contexts (using js_builtin_eval)
// =============================================================================

extern "C" Item js_builtin_eval_with_options(Item code_item, int64_t eval_flags,
                                             Item filename_item,
                                             int64_t line_offset,
                                             int64_t column_offset);
extern "C" Item js_vm_swap_global_this(Item next_global);
extern "C" void js_with_push(Item obj);
extern "C" void js_with_set_stack(Item* stack, int depth);
extern "C" int js_with_save_stack(Item* out_stack, int max_depth);

struct JsVmEvalOptions {
    Item filename;
    int64_t line_offset;
    int64_t column_offset;
};

static void js_vm_eval_options_init(JsVmEvalOptions* out) {
    out->filename = (Item){.item = ITEM_JS_UNDEFINED};
    out->line_offset = 0;
    out->column_offset = 0;
}

static int64_t js_vm_option_to_int64(Item value) {
    TypeId type = get_type_id(value);
    if (type == LMD_TYPE_INT) return it2i(value);
    if (type == LMD_TYPE_FLOAT) {
        double d = it2d(value);
        if (isfinite(d)) return (int64_t)d;
    }
    return 0;
}

static Item js_vm_read_options(Item options, const char** names, int count, JsVmEvalOptions* out) {
    if (out) js_vm_eval_options_init(out);
    TypeId type = get_type_id(options);
    if (type == LMD_TYPE_STRING) {
        if (out) out->filename = options;
        return ItemNull;
    }
    if (type != LMD_TYPE_MAP && type != LMD_TYPE_OBJECT && type != LMD_TYPE_VMAP) return ItemNull;
    for (int i = 0; i < count; i++) {
        JS_ASSIGN_OR_RETURN(option, js_get_key_default(options,
            (Item){.item = s2it(heap_create_name(names[i], strlen(names[i])))}));
    }
    if (out) {
        Item filename_key = (Item){.item = s2it(heap_create_name("filename", 8))};
        JS_ASSIGN_OR_RETURN(filename, js_get_key_default(options, filename_key));
        if (get_type_id(filename) == LMD_TYPE_STRING) out->filename = filename;
        Item line_key = (Item){.item = s2it(heap_create_name("lineOffset", 10))};
        JS_ASSIGN_OR_RETURN(line, js_get_key_default(options, line_key));
        out->line_offset = js_vm_option_to_int64(line);
        Item col_key = (Item){.item = s2it(heap_create_name("columnOffset", 12))};
        JS_ASSIGN_OR_RETURN(col, js_get_key_default(options, col_key));
        out->column_offset = js_vm_option_to_int64(col);
    }
    return ItemNull;
}

static Item js_vm_throw_invalid_option_property_type(const char* name,
                                                     const char* expected,
                                                     Item actual) {
    char msg[512];
    int pos = snprintf(msg, sizeof(msg),
        "The \"%s\" property must be of type %s.", name, expected);
    if (pos < 0) pos = 0;
    if (pos >= (int)sizeof(msg)) pos = (int)sizeof(msg) - 1;
    js_format_invalid_arg_received(msg + pos, (int)sizeof(msg) - pos, actual);
    return js_throw_type_error_code("ERR_INVALID_ARG_TYPE", msg);
}

static bool js_vm_is_options_object(Item options) {
    TypeId type = get_type_id(options);
    return type == LMD_TYPE_MAP || type == LMD_TYPE_OBJECT || type == LMD_TYPE_VMAP;
}

static bool js_vm_is_undefined_item(Item value) {
    TypeId type = get_type_id(value);
    return type == LMD_TYPE_UNDEFINED || value.item == ITEM_JS_UNDEFINED || value.item == 0;
}

static bool js_vm_is_number_item(Item value) {
    TypeId type = get_type_id(value);
    return type == LMD_TYPE_INT || type == LMD_TYPE_FLOAT;
}

static Item js_vm_validate_options_object(Item options) {
    if (js_vm_is_undefined_item(options)) return ItemNull;
    if (js_vm_is_options_object(options)) return ItemNull;
    return js_throw_invalid_arg_type("options", "object", options);
}

static Item js_vm_validate_string_option(Item options, const char* key_name,
                                         int key_len, const char* display_name) {
    if (!js_vm_is_options_object(options)) return ItemNull;
    Item key = (Item){.item = s2it(heap_create_name(key_name, key_len))};
    JS_ASSIGN_OR_RETURN(value, js_get_key_default(options, key));
    TypeId type = get_type_id(value);
    if (type == LMD_TYPE_UNDEFINED || value.item == ITEM_JS_UNDEFINED) return ItemNull;
    if (type == LMD_TYPE_STRING) return ItemNull;
    return js_vm_throw_invalid_option_property_type(display_name, "string", value);
}

static Item js_vm_validate_create_context_options(Item options) {
    JS_ASSIGN_OR_RETURN(status, js_vm_validate_options_object(options));
    JS_ASSIGN_OR_RETURN_INTO(status, js_vm_validate_string_option(options, "name", 4, "options.name"));
    return js_vm_validate_string_option(options, "origin", 6, "options.origin");
}

static Item js_vm_validate_run_context_options(Item options) {
    JS_ASSIGN_OR_RETURN(status, js_vm_validate_string_option(options, "contextName", 11, "options.contextName"));
    return js_vm_validate_string_option(options, "contextOrigin", 13, "options.contextOrigin");
}

static Item js_vm_throw_invalid_arg_instance(const char* name, const char* expected, Item actual) {
    char msg[512];
    int pos = snprintf(msg, sizeof(msg),
        "The \"%s\" argument must be an instance of %s.", name, expected);
    if (pos < 0) pos = 0;
    if (pos >= (int)sizeof(msg)) pos = (int)sizeof(msg) - 1;
    js_format_invalid_arg_received(msg + pos, (int)sizeof(msg) - pos, actual);
    return js_throw_type_error_code("ERR_INVALID_ARG_TYPE", msg);
}

static Item js_vm_throw_invalid_option_property_instance(const char* name,
                                                        const char* expected,
                                                        Item actual) {
    char msg[512];
    int pos = snprintf(msg, sizeof(msg),
        "The \"%s\" property must be an instance of %s.", name, expected);
    if (pos < 0) pos = 0;
    if (pos >= (int)sizeof(msg)) pos = (int)sizeof(msg) - 1;
    js_format_invalid_arg_received(msg + pos, (int)sizeof(msg) - pos, actual);
    return js_throw_type_error_code("ERR_INVALID_ARG_TYPE", msg);
}

static Item js_vm_is_context_item(Item value) {
    if (get_type_id(value) != LMD_TYPE_MAP) return (Item){.item = ITEM_FALSE};
    JS_ASSIGN_OR_RETURN(marker, js_get_key_default(value, (Item){.item = s2it(heap_create_name("__vmContext", 11))}));
    return (Item){.item = (get_type_id(marker) == LMD_TYPE_BOOL && it2b(marker) ? ITEM_TRUE : ITEM_FALSE)};
}

static bool js_vm_is_cached_data_item(Item value) {
    if (js_is_typed_array(value) || js_is_dataview(value)) return true;
    return false;
}

static Item js_vm_validate_compile_function_options(Item options) {
    JS_ASSIGN_OR_RETURN(status, js_vm_validate_options_object(options));
    if (!js_vm_is_options_object(options)) return ItemNull;

    JS_ASSIGN_OR_RETURN(filename, js_get_key_default(options, (Item){.item = s2it(heap_create_name("filename", 8))}));
    if (!js_vm_is_undefined_item(filename) && get_type_id(filename) != LMD_TYPE_STRING) {
        return js_vm_throw_invalid_option_property_type("options.filename", "string", filename);
    }

    JS_ASSIGN_OR_RETURN(column, js_get_key_default(options, (Item){.item = s2it(heap_create_name("columnOffset", 12))}));
    if (!js_vm_is_undefined_item(column) && !js_vm_is_number_item(column)) {
        return js_vm_throw_invalid_option_property_type("options.columnOffset", "number", column);
    }

    JS_ASSIGN_OR_RETURN(line, js_get_key_default(options, (Item){.item = s2it(heap_create_name("lineOffset", 10))}));
    if (!js_vm_is_undefined_item(line) && !js_vm_is_number_item(line)) {
        return js_vm_throw_invalid_option_property_type("options.lineOffset", "number", line);
    }

    JS_ASSIGN_OR_RETURN(cached_data, js_get_key_default(options, (Item){.item = s2it(heap_create_name("cachedData", 10))}));
    if (!js_vm_is_undefined_item(cached_data) && !js_vm_is_cached_data_item(cached_data)) {
        return js_vm_throw_invalid_option_property_instance("options.cachedData", "Buffer, TypedArray, or DataView", cached_data);
    }

    JS_ASSIGN_OR_RETURN(produce, js_get_key_default(options, (Item){.item = s2it(heap_create_name("produceCachedData", 17))}));
    if (!js_vm_is_undefined_item(produce) && get_type_id(produce) != LMD_TYPE_BOOL) {
        return js_vm_throw_invalid_option_property_type("options.produceCachedData", "boolean", produce);
    }

    JS_ASSIGN_OR_RETURN(parsing_context, js_get_key_default(options, (Item){.item = s2it(heap_create_name("parsingContext", 14))}));
    JS_ASSIGN_OR_RETURN(context_status, js_vm_is_context_item(parsing_context));
    if (!js_vm_is_undefined_item(parsing_context) && !it2b(context_status)) {
        return js_vm_throw_invalid_option_property_instance("options.parsingContext", "Context", parsing_context);
    }

    JS_ASSIGN_OR_RETURN(context_extensions, js_get_key_default(options, (Item){.item = s2it(heap_create_name("contextExtensions", 17))}));
    if (!js_vm_is_undefined_item(context_extensions)) {
        if (get_type_id(context_extensions) != LMD_TYPE_ARRAY) {
            return js_vm_throw_invalid_option_property_instance("options.contextExtensions", "Array", context_extensions);
        }
        int64_t length = js_array_length(context_extensions);
        for (int64_t i = 0; i < length; i++) {
            Item extension = js_elements_get_int(context_extensions, i);
            if (!js_vm_is_options_object(extension)) {
                char prop_name[64];
                snprintf(prop_name, sizeof(prop_name), "options.contextExtensions[%lld]", (long long)i);
                return js_vm_throw_invalid_option_property_type(prop_name, "object", extension);
            }
        }
    }

    return ItemNull;
}

static bool js_vm_function_body_has_unmatched_close_brace(String* body) {
    if (!body) return false;
    int brace_depth = 0;
    bool in_sq = false;
    bool in_dq = false;
    bool in_tpl = false;
    bool in_line_comment = false;
    bool in_block_comment = false;
    bool escaped = false;
    const char* src = body->chars;
    int len = (int)body->len;
    for (int i = 0; i < len; i++) {
        char ch = src[i];
        char next = (i + 1 < len) ? src[i + 1] : 0;
        if (in_line_comment) {
            if (ch == '\n' || ch == '\r') in_line_comment = false;
            continue;
        }
        if (in_block_comment) {
            if (ch == '*' && next == '/') {
                in_block_comment = false;
                i++;
            }
            continue;
        }
        if (in_sq || in_dq || in_tpl) {
            if (escaped) {
                escaped = false;
                continue;
            }
            if (ch == '\\') {
                escaped = true;
                continue;
            }
            if ((in_sq && ch == '\'') || (in_dq && ch == '"') || (in_tpl && ch == '`')) {
                in_sq = false;
                in_dq = false;
                in_tpl = false;
            }
            continue;
        }
        if (ch == '/' && next == '/') {
            in_line_comment = true;
            i++;
            continue;
        }
        if (ch == '/' && next == '*') {
            in_block_comment = true;
            i++;
            continue;
        }
        if (ch == '\'') {
            in_sq = true;
            continue;
        }
        if (ch == '"') {
            in_dq = true;
            continue;
        }
        if (ch == '`') {
            in_tpl = true;
            continue;
        }
        if (ch == '{') {
            brace_depth++;
            continue;
        }
        if (ch == '}') {
            if (brace_depth == 0) return true;
            brace_depth--;
        }
    }
    return false;
}

static uint64_t js_vm_cache_hash_bytes(const char* data, int len) {
    uint64_t hash = 1469598103934665603ULL;
    for (int i = 0; i < len; i++) {
        hash ^= (uint8_t)data[i];
        hash *= 1099511628211ULL;
    }
    return hash;
}

static bool js_vm_cache_source_fingerprint(Item code, uint64_t* out_hash, int64_t* out_len) {
    if (get_type_id(code) != LMD_TYPE_STRING) return false;
    String* source = it2s(code);
    if (!source) return false;
    if (out_hash) *out_hash = js_vm_cache_hash_bytes(source->chars, (int)source->len);
    if (out_len) *out_len = source->len;
    return true;
}

static void js_vm_write_u64_le(uint8_t* dst, uint64_t value) {
    for (int i = 0; i < 8; i++) {
        dst[i] = (uint8_t)((value >> (i * 8)) & 0xff);
    }
}

static uint64_t js_vm_read_u64_le(const uint8_t* src) {
    uint64_t value = 0;
    for (int i = 0; i < 8; i++) {
        value |= ((uint64_t)src[i]) << (i * 8);
    }
    return value;
}

static bool js_vm_cached_data_bytes(Item value, const uint8_t** out_data, int* out_len) {
    if (js_is_typed_array(value)) {
        *out_data = (const uint8_t*)js_typed_array_current_data_ptr(value);
        *out_len = js_typed_array_byte_length(value);
        return *out_data != NULL || *out_len == 0;
    }
    if (js_is_dataview(value)) {
        JsDataView* dv = js_get_dataview_ptr(value);
        if (!dv || !dv->buffer || js_arraybuffer_detached(dv->buffer)) return false;
        int len = dv->length_tracking ?
            js_arraybuffer_length(dv->buffer) - dv->byte_offset : dv->byte_length;
        if (len < 0) len = 0;
        *out_data = js_arraybuffer_data_const(dv->buffer) + dv->byte_offset;
        *out_len = len;
        return *out_data != NULL || len == 0;
    }
    return false;
}

static bool js_vm_cached_data_matches_source(Item cached_data, Item code, bool* out_valid_type) {
    const uint8_t* bytes = NULL;
    int len = 0;
    bool valid_type = js_vm_cached_data_bytes(cached_data, &bytes, &len);
    if (out_valid_type) *out_valid_type = valid_type;
    if (!valid_type || len < 28 || !bytes) return false;
    if (memcmp(bytes, "LJSVMC1", 7) != 0 || bytes[7] != 0) return false;

    uint64_t expected_hash = 0;
    int64_t expected_len = 0;
    if (!js_vm_cache_source_fingerprint(code, &expected_hash, &expected_len)) return false;
    uint64_t actual_len = js_vm_read_u64_le(bytes + 8);
    uint64_t actual_hash = js_vm_read_u64_le(bytes + 16);
    uint64_t actual_check = js_vm_read_u64_le(bytes + 24);
    return actual_len == (uint64_t)expected_len &&
           actual_hash == expected_hash &&
           actual_check == (expected_hash ^ actual_len ^ 0x6a735f766d5f6331ULL);
}

static Item js_vm_make_cached_data_for_code(Item code) {
    uint64_t source_hash = 0;
    int64_t source_len = 0;
    if (!js_vm_cache_source_fingerprint(code, &source_hash, &source_len)) {
        source_hash = 0;
        source_len = 0;
    }

    uint8_t payload[32];
    memset(payload, 0, sizeof(payload));
    memcpy(payload, "LJSVMC1", 7);
    js_vm_write_u64_le(payload + 8, (uint64_t)source_len);
    js_vm_write_u64_le(payload + 16, source_hash);
    js_vm_write_u64_le(payload + 24, source_hash ^ (uint64_t)source_len ^ 0x6a735f766d5f6331ULL);
    return js_buffer_from_bytes((const char*)payload, (int)sizeof(payload));
}

struct JsVmContextBinding {
    Item key;
};

static void js_vm_track_temp_binding(Item key, JsVmContextBinding* bindings, int* count, int max_count) {
    if (!bindings || !count || *count >= max_count) return;
    bindings[*count].key = key;
    (*count)++;
}

static void js_vm_set_temp_global_alias(Item sandbox, const char* name, int len,
                                        JsVmContextBinding* bindings, int* count, int max_count) {
    Item key = (Item){.item = s2it(heap_create_name(name, len))};
    if (it2b(js_has_own_property(sandbox, key))) return;
    js_set_key_default(sandbox, key, sandbox);
    js_mark_non_enumerable(sandbox, key);
    js_vm_track_temp_binding(key, bindings, count, max_count);
}

static void js_vm_mask_temp_host_global(Item sandbox, const char* name, int len,
                                        JsVmContextBinding* bindings, int* count, int max_count) {
    Item key = (Item){.item = s2it(heap_create_name(name, len))};
    if (it2b(js_has_own_property(sandbox, key))) return;
    js_set_key_default(sandbox, key, make_js_undefined());
    js_mark_non_enumerable(sandbox, key);
    js_vm_track_temp_binding(key, bindings, count, max_count);
}

static int js_vm_apply_context_bindings(Item sandbox, JsVmContextBinding* bindings, int max_count) {
    int count = 0;
    js_vm_set_temp_global_alias(sandbox, "globalThis", 10, bindings, &count, max_count);
    js_vm_set_temp_global_alias(sandbox, "self", 4, bindings, &count, max_count);
    js_vm_set_temp_global_alias(sandbox, "window", 6, bindings, &count, max_count);
    js_vm_set_temp_global_alias(sandbox, "global", 6, bindings, &count, max_count);
    js_vm_mask_temp_host_global(sandbox, "process", 7, bindings, &count, max_count);
    js_vm_mask_temp_host_global(sandbox, "require", 7, bindings, &count, max_count);
    js_vm_mask_temp_host_global(sandbox, "module", 6, bindings, &count, max_count);
    js_vm_mask_temp_host_global(sandbox, "exports", 7, bindings, &count, max_count);
    js_vm_mask_temp_host_global(sandbox, "__filename", 10, bindings, &count, max_count);
    js_vm_mask_temp_host_global(sandbox, "__dirname", 9, bindings, &count, max_count);
    return count;
}

static void js_vm_restore_context_bindings(Item sandbox, JsVmContextBinding* bindings, int count) {
    for (int i = count - 1; i >= 0; i--) {
        js_delete_property(sandbox, bindings[i].key);
    }
}

static Item js_vm_contextify(Item sandbox) {
    if (get_type_id(sandbox) != LMD_TYPE_MAP) {
        sandbox = js_new_object();
    }
    Item marker_key = (Item){.item = s2it(heap_create_name("__vmContext", 11))};
    js_set_key_default(sandbox, marker_key,
                    (Item){.item = ITEM_TRUE});
    js_mark_non_enumerable(sandbox, marker_key);
    return sandbox;
}

// vm.createContext(sandbox) — returns sandbox (or new object) marked as a "context"
static Item js_vm_createContext(Item sandbox, Item options) {
    JS_ASSIGN_OR_RETURN(option_status, js_vm_validate_create_context_options(options));
    // If no sandbox provided, create a new empty object
    TypeId t = get_type_id(sandbox);
    if (t == LMD_TYPE_STRING || t == LMD_TYPE_INT || t == LMD_TYPE_FLOAT ||
        t == LMD_TYPE_BOOL || t == LMD_TYPE_SYMBOL) {
        return js_throw_type_error_code("ERR_INVALID_ARG_TYPE",
            "The \"contextObject\" argument must be an object");
    }
    if (t != LMD_TYPE_MAP) {
        sandbox = js_new_object();
    }
    return js_vm_contextify(sandbox);
}

// vm.isContext(obj) — check if object is a context
static Item js_vm_isContext(Item obj) {
    TypeId t = get_type_id(obj);
    // Arrays are objects in JS — don't throw, return false
    if (t == LMD_TYPE_ARRAY) return (Item){.item = ITEM_FALSE};
    if (t != LMD_TYPE_MAP) {
        return js_throw_type_error_code("ERR_INVALID_ARG_TYPE",
            "The \"sandbox\" argument must be an object");
    }
    if (t != LMD_TYPE_MAP) return (Item){.item = ITEM_FALSE};
    JS_ASSIGN_OR_RETURN(marker, js_get_key_default(obj, (Item){.item = s2it(heap_create_name("__vmContext", 11))}));
    if (get_type_id(marker) == LMD_TYPE_BOOL && it2b(marker))
        return (Item){.item = ITEM_TRUE};
    return (Item){.item = ITEM_FALSE};
}

static Item js_vm_runInThisContext(Item code, Item options) {
    const char* names[] = {"breakOnSigint", "timeout", "displayErrors", "filename", "lineOffset", "columnOffset"};
    JsVmEvalOptions eval_options;
    JS_ASSIGN_OR_RETURN(option_status, js_vm_read_options(options, names, 6, &eval_options));
    return js_builtin_eval_with_options(code, 1 | 16, eval_options.filename,
                                        eval_options.line_offset,
                                        eval_options.column_offset);
}

// Helper: run code with sandbox variables injected as temporary globals.
// Sets sandbox properties as globals before eval, removes after.
static Item js_vm_run_with_sandbox(Item code, Item sandbox, Item options) {
    if (get_type_id(code) != LMD_TYPE_STRING) return ItemNull;

    const char* names[] = {"breakOnSigint", "timeout", "displayErrors", "filename", "lineOffset", "columnOffset"};
    JsVmEvalOptions eval_options;
    JS_ASSIGN_OR_RETURN(option_status, js_vm_read_options(options, names, 6, &eval_options));
    JS_ASSIGN_OR_RETURN_INTO(option_status, js_vm_validate_run_context_options(options));

    sandbox = js_vm_contextify(sandbox);

    // bit 8: vm context — each runInContext unit gets its own module-var slot
    // namespace so units sharing this context don't clobber each other's slots.
    Item previous_proto = js_get_prototype_of(sandbox);
    js_set_prototype(sandbox, js_get_global_this());
    JsVmContextBinding vm_bindings[16];
    int vm_binding_count = js_vm_apply_context_bindings(sandbox, vm_bindings, 16);
    Item prev_this = js_get_current_this();
    Item prev_global = js_vm_swap_global_this(sandbox);
    Item saved_with_stack[16];
    int saved_with_depth = js_with_save_stack(saved_with_stack, 16);
    JsSavedWithScopeRoots saved_with_roots(saved_with_stack, saved_with_depth);
    js_with_push(sandbox);
    js_set_this(sandbox);
    Item result = js_builtin_eval_with_options(code, 1 | 8, eval_options.filename,
                                               eval_options.line_offset,
                                               eval_options.column_offset);
    js_set_this(prev_this);
    js_with_set_stack(saved_with_stack, saved_with_depth);
    js_vm_swap_global_this(prev_global);
    js_vm_restore_context_bindings(sandbox, vm_bindings, vm_binding_count);
    js_set_prototype(sandbox, previous_proto);
    if (get_type_id(result) == LMD_TYPE_MAP && js_class_is_error_like(js_class_id(result))) {
        // VM contexts do not yet allocate separate Error prototypes; mark the
        // result so host-realm instanceof checks still observe the realm split.
        Item vm_error_key = (Item){.item = s2it(heap_create_name("__vm_context_error__", 20))};
        js_set_key_default(result, vm_error_key, (Item){.item = b2it(true)});
        js_mark_non_enumerable(result, vm_error_key);
    }
    return result;
}

// vm.runInContext(code, context, options) — evaluate code
static Item js_vm_runInContext(Item code, Item context, Item options) {
    return js_vm_run_with_sandbox(code, context, options);
}

// vm.runInNewContext(code, sandbox, options) — create context and run code
static Item js_vm_runInNewContext(Item code, Item sandbox, Item options) {
    return js_vm_run_with_sandbox(code, sandbox, options);
}

// vm.compileFunction(code, params, options) — compile a function from string
// Returns a function object
static Item js_vm_compileFunction(Item code, Item params, Item options) {
    // Build Function constructor args: params..., body
    // For simplicity, wrap in Function() call via eval
    if (get_type_id(code) != LMD_TYPE_STRING) {
        return js_throw_invalid_arg_type("code", "string", code);
    }
    if (!js_vm_is_undefined_item(params) && get_type_id(params) != LMD_TYPE_ARRAY) {
        return js_vm_throw_invalid_arg_instance("params", "Array", params);
    }
    JS_ASSIGN_OR_RETURN(option_status, js_vm_validate_compile_function_options(options));
    const char* option_names[] = {"filename", "lineOffset", "columnOffset", "cachedData",
        "produceCachedData", "parsingContext", "contextExtensions"};
    JsVmEvalOptions eval_options;
    JS_ASSIGN_OR_RETURN_INTO(option_status, js_vm_read_options(options, option_names, 7, &eval_options));
    String* code_str = it2s(code);
    if (js_vm_function_body_has_unmatched_close_brace(code_str)) {
        return js_throw_syntax_error((Item){.item = s2it(heap_create_name("Unexpected token '}'", 20))});
    }
    Item context_extensions = (Item){.item = ITEM_JS_UNDEFINED};
    Item parsing_context = (Item){.item = ITEM_JS_UNDEFINED};
    Item cached_data = (Item){.item = ITEM_JS_UNDEFINED};
    bool cached_data_produced = false;
    bool cached_data_rejected = false;
    int extension_count = 0;
    if (js_vm_is_options_object(options)) {
        JS_ASSIGN_OR_RETURN_INTO(context_extensions, js_get_key_default(options, (Item){.item = s2it(heap_create_name("contextExtensions", 17))}));
        if (get_type_id(context_extensions) == LMD_TYPE_ARRAY) {
            int64_t length = js_array_length(context_extensions);
            extension_count = length > 16 ? 16 : (int)length;
        }
        JS_ASSIGN_OR_RETURN_INTO(parsing_context, js_get_key_default(options, (Item){.item = s2it(heap_create_name("parsingContext", 14))}));
        JS_ASSIGN_OR_RETURN_INTO(cached_data, js_get_key_default(options, (Item){.item = s2it(heap_create_name("cachedData", 10))}));
        if (!js_vm_is_undefined_item(cached_data)) {
            bool valid_cached_type = false;
            bool matched = js_vm_cached_data_matches_source(cached_data, code, &valid_cached_type);
            cached_data_rejected = !matched;
        }
        JS_ASSIGN_OR_RETURN(produce, js_get_key_default(options, (Item){.item = s2it(heap_create_name("produceCachedData", 17))}));
        if (get_type_id(produce) == LMD_TYPE_BOOL && it2b(produce)) {
            cached_data = js_vm_make_cached_data_for_code(code);
            cached_data_produced = true;
            cached_data_rejected = false;
        }
    }

    // If params array provided, build "function(p1,p2,...) { body }" string
    // For now, just wrap body as a function with no params
    StrBuf* eval_buf = strbuf_new();
    StrBuf* display_buf = strbuf_new();
    Item extension_keys[16];
    memset(extension_keys, 0, sizeof(extension_keys));
    bool use_parsing_context = !js_vm_is_undefined_item(parsing_context) &&
        get_type_id(parsing_context) == LMD_TYPE_MAP;
    Item global_obj = use_parsing_context ? parsing_context : js_get_global_this();
    static int vm_compile_extension_counter = 0;
    for (int i = 0; i < extension_count; i++) {
        char ext_name[64];
        int ext_len = snprintf(ext_name, sizeof(ext_name),
            "__vm_compile_context_ext_%d_%d", vm_compile_extension_counter++, i);
        Item ext_key = (Item){.item = s2it(heap_create_name(ext_name, ext_len))};
        extension_keys[i] = ext_key;
        Item ext_obj = js_elements_get_int(context_extensions, i);
        js_set_key_default(global_obj, ext_key, ext_obj);
        strbuf_append_str_n(eval_buf, "with(", 5);
        strbuf_append_str_n(eval_buf, ext_name, ext_len);
        strbuf_append_str_n(eval_buf, "){", 2);
    }
    strbuf_append_str_n(eval_buf, "(function(", 10);
    strbuf_append_str_n(display_buf, "function (", 10);
    if (!js_vm_is_undefined_item(params)) {
        // Extract param names from array
        int nparams = (int)js_array_length(params);
        for (int i = 0; i < nparams; i++) {
            if (i > 0) {
                strbuf_append_str_n(eval_buf, ",", 1);
                strbuf_append_str_n(display_buf, ", ", 2);
            }
            Item p = js_elements_get_int(params, i);
            if (get_type_id(p) == LMD_TYPE_STRING) {
                String* ps = it2s(p);
                strbuf_append_str_n(eval_buf, ps->chars, ps->len);
                strbuf_append_str_n(display_buf, ps->chars, ps->len);
            }
        }
    }
    strbuf_append_str_n(eval_buf, "){", 2);
    strbuf_append_str_n(eval_buf, code_str->chars, code_str->len);
    strbuf_append_str_n(eval_buf, "})", 2);
    for (int i = 0; i < extension_count; i++) {
        strbuf_append_str_n(eval_buf, "}", 1);
    }
    strbuf_append_str_n(display_buf, ") {\n", 4);
    strbuf_append_str_n(display_buf, code_str->chars, code_str->len);
    strbuf_append_str_n(display_buf, "\n}", 2);

    Item eval_code = (Item){.item = s2it(heap_create_name(eval_buf->str, eval_buf->length))};
    String* display_source = heap_create_name(display_buf->str, display_buf->length);
    strbuf_free(eval_buf);
    strbuf_free(display_buf);

    Item previous_proto = ItemNull;
    Item prev_global = ItemNull;
    Item prev_this = ItemNull;
    Item saved_with_stack[16];
    int saved_with_depth = 0;
    JsVmContextBinding vm_bindings[16];
    int vm_binding_count = 0;
    if (use_parsing_context) {
        previous_proto = js_get_prototype_of(parsing_context);
        js_set_prototype(parsing_context, js_get_global_this());
        vm_binding_count = js_vm_apply_context_bindings(parsing_context, vm_bindings, 16);
        prev_this = js_get_current_this();
        prev_global = js_vm_swap_global_this(parsing_context);
        saved_with_depth = js_with_save_stack(saved_with_stack, 16);
        js_with_push(parsing_context);
        js_set_this(parsing_context);
    }
    Item result = js_builtin_eval(eval_code, 1);
    if (use_parsing_context) {
        js_set_this(prev_this);
        js_with_set_stack(saved_with_stack, saved_with_depth);
        js_vm_swap_global_this(prev_global);
        js_vm_restore_context_bindings(parsing_context, vm_bindings, vm_binding_count);
        js_set_prototype(parsing_context, previous_proto);
    }
    for (int i = extension_count - 1; i >= 0; i--) {
        js_delete_property(global_obj, extension_keys[i]);
    }
    if (get_type_id(result) == LMD_TYPE_FUNC) {
        JsFunction* fn = (JsFunction*)result.function;
        fn->source_text = display_source;
        fn->vm_stack_filename = get_type_id(eval_options.filename) == LMD_TYPE_STRING ?
            it2s(eval_options.filename) : heap_create_name("<anonymous>", 11);
        fn->vm_stack_source = heap_create_name(code_str->chars, code_str->len);
        fn->vm_stack_line_offset = eval_options.line_offset;
        fn->vm_stack_column_offset = eval_options.column_offset;
        js_set_key_default(result, (Item){.item = s2it(heap_create_name("cachedData", 10))}, cached_data);
        js_set_key_default(result, (Item){.item = s2it(heap_create_name("cachedDataProduced", 18))},
                        (Item){.item = b2it(cached_data_produced)});
        js_set_key_default(result, (Item){.item = s2it(heap_create_name("cachedDataRejected", 18))},
                        (Item){.item = b2it(cached_data_rejected)});
    }
    return result;
}

static Item js_vm_Script_createCachedData(void) {
    Item self = js_get_this();
    Item code = js_get_key_default(self, (Item){.item = s2it(heap_create_name("_code", 5))});
    return js_vm_make_cached_data_for_code(code);
}

// Script.runInThisContext wrapper that extracts _code from `this`
static Item js_vm_Script_runInThisContext(Item options) {
    const char* names[] = {"breakOnSigint", "timeout", "displayErrors", "filename", "lineOffset", "columnOffset"};
    JsVmEvalOptions eval_options;
    JS_ASSIGN_OR_RETURN(option_status, js_vm_read_options(options, names, 6, &eval_options));
    Item self = js_get_this();
    Item code = js_get_key_default(self, (Item){.item = s2it(heap_create_name("_code", 5))});
    if (get_type_id(eval_options.filename) != LMD_TYPE_STRING) {
        eval_options.filename = js_get_key_default(self, (Item){.item = s2it(heap_create_name("_filename", 9))});
        eval_options.line_offset = js_vm_option_to_int64(js_get_key_default(self, (Item){.item = s2it(heap_create_name("_lineOffset", 11))}));
        eval_options.column_offset = js_vm_option_to_int64(js_get_key_default(self, (Item){.item = s2it(heap_create_name("_columnOffset", 13))}));
    }
    return js_builtin_eval_with_options(code, 1 | 16, eval_options.filename,
                                        eval_options.line_offset,
                                        eval_options.column_offset);
}

// Script.runInContext wrapper
static Item js_vm_Script_runInContext(Item context, Item options) {
    Item self = js_get_this();
    Item code = js_get_key_default(self, (Item){.item = s2it(heap_create_name("_code", 5))});
    if (get_type_id(options) == LMD_TYPE_UNDEFINED || options.item == ITEM_JS_UNDEFINED || options.item == 0) {
        options = js_new_object();
        js_set_key_default(options, (Item){.item = s2it(heap_create_name("filename", 8))},
                        js_get_key_default(self, (Item){.item = s2it(heap_create_name("_filename", 9))}));
        js_set_key_default(options, (Item){.item = s2it(heap_create_name("lineOffset", 10))},
                        js_get_key_default(self, (Item){.item = s2it(heap_create_name("_lineOffset", 11))}));
        js_set_key_default(options, (Item){.item = s2it(heap_create_name("columnOffset", 12))},
                        js_get_key_default(self, (Item){.item = s2it(heap_create_name("_columnOffset", 13))}));
    }
    return js_vm_run_with_sandbox(code, context, options);
}

// Script.runInNewContext wrapper
static Item js_vm_Script_runInNewContext(Item sandbox, Item options) {
    Item self = js_get_this();
    Item code = js_get_key_default(self, (Item){.item = s2it(heap_create_name("_code", 5))});
    if (get_type_id(options) == LMD_TYPE_UNDEFINED || options.item == ITEM_JS_UNDEFINED || options.item == 0) {
        options = js_new_object();
        js_set_key_default(options, (Item){.item = s2it(heap_create_name("filename", 8))},
                        js_get_key_default(self, (Item){.item = s2it(heap_create_name("_filename", 9))}));
        js_set_key_default(options, (Item){.item = s2it(heap_create_name("lineOffset", 10))},
                        js_get_key_default(self, (Item){.item = s2it(heap_create_name("_lineOffset", 11))}));
        js_set_key_default(options, (Item){.item = s2it(heap_create_name("columnOffset", 12))},
                        js_get_key_default(self, (Item){.item = s2it(heap_create_name("_columnOffset", 13))}));
    }
    return js_vm_run_with_sandbox(code, sandbox, options);
}

// Script constructor wrapper (called with `new vm.Script(code, options)`)
static Item js_vm_Script_constructor(Item code, Item options) {
    const char* names[] = {"filename", "cachedData", "produceCachedData", "lineOffset", "columnOffset"};
    JsVmEvalOptions eval_options;
    JS_ASSIGN_OR_RETURN(option_status, js_vm_read_options(options, names, 5, &eval_options));
    bool cached_data_produced = false;
    bool cached_data_rejected = false;
    Item cached_data = (Item){.item = ITEM_JS_UNDEFINED};
    if (get_type_id(options) == LMD_TYPE_MAP || get_type_id(options) == LMD_TYPE_OBJECT ||
        get_type_id(options) == LMD_TYPE_VMAP) {
        Item cached_data_key = (Item){.item = s2it(heap_create_name("cachedData", 10))};
        JS_ASSIGN_OR_RETURN_INTO(cached_data, js_get_key_default(options, cached_data_key));
        if (get_type_id(cached_data) != LMD_TYPE_UNDEFINED) {
            bool valid_cached_type = false;
            bool matched = js_vm_cached_data_matches_source(cached_data, code, &valid_cached_type);
            if (!valid_cached_type) {
                return js_throw_type_error_code("ERR_INVALID_ARG_TYPE",
                    "The \"options.cachedData\" property must be an instance of Buffer, TypedArray, or DataView.");
            }
            cached_data_rejected = !matched;
        }

        Item produce_key = (Item){.item = s2it(heap_create_name("produceCachedData", 17))};
        JS_ASSIGN_OR_RETURN(produce, js_get_key_default(options, produce_key));
        if (get_type_id(produce) == LMD_TYPE_BOOL && it2b(produce)) {
            cached_data = js_vm_make_cached_data_for_code(code);
            cached_data_produced = true;
            cached_data_rejected = false;
        }
    }
    Item script = js_new_object();
    js_set_key_default(script, (Item){.item = s2it(heap_create_name("_code", 5))}, code);
    js_set_key_default(script, (Item){.item = s2it(heap_create_name("_filename", 9))}, eval_options.filename);
    js_set_key_default(script, (Item){.item = s2it(heap_create_name("_lineOffset", 11))},
                    (Item){.item = i2it(eval_options.line_offset)});
    js_set_key_default(script, (Item){.item = s2it(heap_create_name("_columnOffset", 13))},
                    (Item){.item = i2it(eval_options.column_offset)});
    js_set_key_default(script, (Item){.item = s2it(heap_create_name("runInThisContext", 16))},
                    js_new_native_function(js_vm_Script_runInThisContext));
    js_set_key_default(script, (Item){.item = s2it(heap_create_name("runInContext", 12))},
                    js_new_native_function(js_vm_Script_runInContext));
    js_set_key_default(script, (Item){.item = s2it(heap_create_name("runInNewContext", 15))},
                    js_new_native_function(js_vm_Script_runInNewContext));
    js_set_key_default(script, (Item){.item = s2it(heap_create_name("createCachedData", 16))},
                    js_new_native_function(js_vm_Script_createCachedData));
    js_set_key_default(script, (Item){.item = s2it(heap_create_name("cachedData", 10))}, cached_data);
    js_set_key_default(script, (Item){.item = s2it(heap_create_name("cachedDataProduced", 18))},
                    (Item){.item = b2it(cached_data_produced)});
    js_set_key_default(script, (Item){.item = s2it(heap_create_name("cachedDataRejected", 18))},
                    (Item){.item = b2it(cached_data_rejected)});
    return script;
}

static Item js_vm_createScript(Item code, Item options) {
    return js_vm_Script_constructor(code, options);
}

